window.__archiveSearchData["docs-003.json"] = [{"doc_id":3000,"url":"../t12p150-topic.html#p12489","post_id":"p12489","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Ср 20 Май 2015 - 3:09","sort_key":"2015-05-20 03:09:00","excerpt":"За завершением истории, а напоролся на бэд!"},{"doc_id":3001,"url":"../t12p150-topic.html#p12495","post_id":"p12495","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 10:54","sort_key":"2015-05-20 10:54:00","excerpt":"Но история ведь завершилась, разве нет?"},{"doc_id":3002,"url":"../t12p150-topic.html#p12504","post_id":"p12504","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 20:12","sort_key":"2015-05-20 20:12:00","excerpt":"Всем привет! Может кто-нибудь объяснить в чем смысл концовки \"Моя Мику\", а то до меня как в самом оригинале не дошло и тут тоже не дошло! Просто объясните, я все читал все диалоги все мысли Семена и все равно до меня…"},{"doc_id":3003,"url":"../t12p150-topic.html#p12505","post_id":"p12505","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Ср 20 Май 2015 - 20:18","sort_key":"2015-05-20 20:18:00","excerpt":"По хардкору: Из всех способов быть с несуществующей девочкой, Семён выбрал самый очевидный - он вернулся в «Совёнок». Ну и попутно узнал, что далеко не первый раз такой трюк проделывает."},{"doc_id":3004,"url":"../t12p150-topic.html#p12506","post_id":"p12506","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 20:28","sort_key":"2015-05-20 20:28:00","excerpt":"т.е. он грубо говоря остался в том сне? И все по кругу снова и снова как в \"История одного пионера\"?"},{"doc_id":3005,"url":"../t12p150-topic.html#p12507","post_id":"p12507","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 20:37","sort_key":"2015-05-20 20:37:00","excerpt":"По кругу, да. Ну, почти по кругу. И он пытается найти выход. Найти решение. У него много времени для этого."},{"doc_id":3006,"url":"../t12p150-topic.html#p12508","post_id":"p12508","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 20:41","sort_key":"2015-05-20 20:41:00","excerpt":"как-то даже и не хорошая концовка, но все же спасибо что все разъяснили, а будет ли продолжение этой концовки или типо краткое дополнение где все разъясняется и он же все таки находит выход, а потом находит Мику."},{"doc_id":3007,"url":"../t12p150-topic.html#p12509","post_id":"p12509","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 20:50","sort_key":"2015-05-20 20:50:00","excerpt":"Я не думаю, что это нужно. Истории должны оставаться в некотором смысле недосказанными."},{"doc_id":3008,"url":"../t12p150-topic.html#p12510","post_id":"p12510","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 20:53","sort_key":"2015-05-20 20:53:00","excerpt":"Ну ладно, спасибо и на этом, а еще чуть не забыл, можешь еще объяснить что стало с Семеном в оригинальной концовки \"Моя Мику\", я так понял он просто остался в той шахте, где вырубился?"},{"doc_id":3009,"url":"../t12p150-topic.html#p12511","post_id":"p12511","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 20:55","sort_key":"2015-05-20 20:55:00","excerpt":"Эм. Ещё раз?"},{"doc_id":3010,"url":"../t12p150-topic.html#p12512","post_id":"p12512","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 21:00","sort_key":"2015-05-20 21:00:00","excerpt":"Дак он же остался в той шахте, когда вырубился, и ему начался снится сон где он снимается в кино, а потом снова сон когда он с Мику на пляже остался ночевать, и в том сне то Слява разрубленная, то Алиса повешенная, а…"},{"doc_id":3011,"url":"../t12p150-topic.html#p12513","post_id":"p12513","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Pumpurumpum","posted_at":"Ср 20 Май 2015 - 21:12","sort_key":"2015-05-20 21:12:00","excerpt":"Это в оригинале было"},{"doc_id":3012,"url":"../t12p150-topic.html#p12514","post_id":"p12514","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 21:14","sort_key":"2015-05-20 21:14:00","excerpt":"дак в самом моде она отличается от той, что в оригинале, дак вот я и хотел спросить что с Семном стало в итоге, он поцеловал Мику и все закончилось, т.е. он умер в той шахте?"},{"doc_id":3013,"url":"../t12p150-topic.html#p12515","post_id":"p12515","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Pumpurumpum","posted_at":"Ср 20 Май 2015 - 21:17","sort_key":"2015-05-20 21:17:00","excerpt":"Так, стоп. В моде пока написан только Мику-DJ рут, с 4 концовками. Кино, Маша, сон в шахте, это всё не отсюда. По крайней мере пока"},{"doc_id":3014,"url":"../t12p150-topic.html#p12516","post_id":"p12516","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Ср 20 Май 2015 - 21:17","sort_key":"2015-05-20 21:17:00","excerpt":"А это и не хорошая концовка, это тру энд. То бишь, настоящий. Семён променял то, что оставалось у него ирл на иллюзию совёнка вместе со своей ненаглядной."},{"doc_id":3015,"url":"../t12p150-topic.html#p12517","post_id":"p12517","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 21:20","sort_key":"2015-05-20 21:20:00","excerpt":"это я понял что он променял реальный мир на не реальный и остался там, но я знаю что вообще не по теме, что все таки стали с Семеном в шахте?"},{"doc_id":3016,"url":"../t12p150-topic.html#p12518","post_id":"p12518","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Ср 20 Май 2015 - 21:22","sort_key":"2015-05-20 21:22:00","excerpt":"Семён в шахте проснулся и ПОНЯЛ, что оказывается всё это время они снимали фильм. Это НЕВЕРОЯТНЫЙ СЮЖЕТНЫЙ ПОВОРОТ от сценариста. Относиться к нему серьёзно не следует, так как он был добавлен в последние недели и, судя…"},{"doc_id":3017,"url":"../t12p150-topic.html#p12519","post_id":"p12519","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Ср 20 Май 2015 - 21:24","sort_key":"2015-05-20 21:24:00","excerpt":"все же не перестают удивлять, спасибо!"},{"doc_id":3018,"url":"../t12p150-topic.html#p12520","post_id":"p12520","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 22:36","sort_key":"2015-05-20 22:36:00","excerpt":"А, у Риточки? Риточку анализировать бессмысленно, Риточка убил всю надежду."},{"doc_id":3019,"url":"../t12p150-topic.html#p12521","post_id":"p12521","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"haLf0nzio","posted_at":"Ср 20 Май 2015 - 22:39","sort_key":"2015-05-20 22:39:00","excerpt":"Да ладно вам, ванильный маша-рут был внезапен и местами увлекателен."},{"doc_id":3020,"url":"../t12p150-topic.html#p12522","post_id":"p12522","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Ср 20 Май 2015 - 22:44","sort_key":"2015-05-20 22:44:00","excerpt":"Безусловно. Но пытаться привязать его к общей истории, вывести что-то единое и непротиворечивое... Риточка убил всю надежду."},{"doc_id":3021,"url":"../t12p175-topic.html#p12523","post_id":"p12523","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"haLf0nzio","posted_at":"Чт 21 Май 2015 - 0:12","sort_key":"2015-05-21 00:12:00","excerpt":"жосткий оффтоп и айяйяй: Нуу, если слухи не врут, то все логишно получается. Кстати раз уж мы тут отошли от обсуждения мику-рута, мне было очень любопытно, кто вообще доверил ему сценарий? Был же некий абцб, от…"},{"doc_id":3022,"url":"../t12p175-topic.html#p12524","post_id":"p12524","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Чт 21 Май 2015 - 0:18","sort_key":"2015-05-21 00:18:00","excerpt":"Спойлер: Советую ознакомиться со статейкой на лурочке - её писали как раз зрители всего бурлеска, творящегося на ычане с момента старта проекта…"},{"doc_id":3023,"url":"../t12p175-topic.html#p12525","post_id":"p12525","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"haLf0nzio","posted_at":"Чт 21 Май 2015 - 1:18","sort_key":"2015-05-21 01:18:00","excerpt":"Ну тащемта как бы там ни было, в Вашем исполнении Мику-руты получилися архигодными и кошерными."},{"doc_id":3024,"url":"../t12p175-topic.html#p12526","post_id":"p12526","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 21 Май 2015 - 1:31","sort_key":"2015-05-21 01:31:00","excerpt":"Спойлер: При всех недостатках Риты, из него получился не самый плохой менеджер. Он таки раздал команде достаточно пинков, чтобы свести игру к чему-то более-менее законченному."},{"doc_id":3025,"url":"../t12p175-topic.html#p13467","post_id":"p13467","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 5 Июн 2015 - 10:06","sort_key":"2015-06-05 10:06:00","excerpt":"Блин. Блинский блин! на ФБ ж замечательная концовка лежит, \"На радиоволнах\"! Как раз под радиорут же была... А почему забраковалась?"},{"doc_id":3026,"url":"../t12p175-topic.html#p13468","post_id":"p13468","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 5 Июн 2015 - 10:50","sort_key":"2015-06-05 10:50:00","excerpt":"Она не совсем под радиорут... Она в принципе под Мику. Поэтому не забраковалась, а временно отложилась - ибо впереди ещё 2 рута, а это как минимум 4 концовки."},{"doc_id":3027,"url":"../t12p175-topic.html#p13507","post_id":"p13507","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Сб 6 Июн 2015 - 20:15","sort_key":"2015-06-06 20:15:00","excerpt":"я еще недавно узнал что Мику Хатсуне есть в моей любимой игре, думал думал, кого-же она мне напоманиет, дак это же Сона из League of Legends, правда она тамне умеет говорить((("},{"doc_id":3028,"url":"../t12p175-topic.html#p13508","post_id":"p13508","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"x4team","posted_at":"Сб 6 Июн 2015 - 20:16","sort_key":"2015-06-06 20:16:00","excerpt":"я очень обрадывался что это Мику, Мику мною завладела, так-же как и Алиса"},{"doc_id":3029,"url":"../t12p175-topic.html#p13834","post_id":"p13834","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Surv","posted_at":"Чт 11 Июн 2015 - 22:31","sort_key":"2015-06-11 22:31:00","excerpt":"На 6 дне вылетело : I'm sorry, but an uncaught exception occurred. While running game code: File \"game/scenario_alt/routes/alt_mi_dj_route.rpy\", line 7121, in script File \"game/scenario_alt/routes/alt_mi_dj_route.rpy\"…"},{"doc_id":3030,"url":"../t12p175-topic.html#p13835","post_id":"p13835","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"DJ_DAD","posted_at":"Чт 11 Июн 2015 - 22:44","sort_key":"2015-06-11 22:44:00","excerpt":"Surv, Тебе сюда"},{"doc_id":3031,"url":"../t12p175-topic.html#p14215","post_id":"p14215","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Мурфин","posted_at":"Ср 17 Июн 2015 - 1:42","sort_key":"2015-06-17 01:42:00","excerpt":"Гайз, а куда можно свернуть с Мику-рута дрыщем? Я смог выйти на ответвление Признан негодным Кажись в 4 дне, когда со Славей на сцену пошел. Еще на какой-то недописанный напоролся. Есть еще варианты развития раскрывающие…"},{"doc_id":3032,"url":"../t12p175-topic.html#p14216","post_id":"p14216","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Ср 17 Июн 2015 - 1:53","sort_key":"2015-06-17 01:53:00","excerpt":"Моар инфы надо. Как минимум, роль унд ЛП."},{"doc_id":3033,"url":"../t12p175-topic.html#p14217","post_id":"p14217","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Мурфин","posted_at":"Ср 17 Июн 2015 - 8:39","sort_key":"2015-06-17 08:39:00","excerpt":"Если ты мне, то: Дрыщ, 14 ЛП, прям перед выходом на DJ рут в Столовой остановился(на выборе с кем сесть[Лена, Мику]). P.S. Лена знатный тролль UPD: Подсмотрел одним глазком в прохождение и понял, что у меня отличается от…"},{"doc_id":3034,"url":"../t12p175-topic.html#p14218","post_id":"p14218","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Ср 17 Июн 2015 - 10:08","sort_key":"2015-06-17 10:08:00","excerpt":"Много кармы нужно. Много. Без кармы ты Мику никогда не догонишь."},{"doc_id":3035,"url":"../t12p175-topic.html#p14219","post_id":"p14219","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Мурфин","posted_at":"Ср 17 Июн 2015 - 13:37","sort_key":"2015-06-17 13:37:00","excerpt":"Хм, играя за Дрыща с Кармой в 30 и ЛП 19 вышел на концовку \"И не мечтай\". Сейчас буду перепроходить и выходить на Лучшую концовку)"},{"doc_id":3036,"url":"../t12p175-topic.html#p14221","post_id":"p14221","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Surv","posted_at":"Ср 17 Июн 2015 - 16:59","sort_key":"2015-06-17 16:59:00","excerpt":"Имхо лучшая концовка была \"С новым счастьем\",ну хэппи эндом её не назовёшь,но трогает до глубины души."},{"doc_id":3037,"url":"../t12p175-topic.html#p14226","post_id":"p14226","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Ср 17 Июн 2015 - 23:36","sort_key":"2015-06-17 23:36:00","excerpt":"Это там, где Семен за Намико в Японию едет?"},{"doc_id":3038,"url":"../t12p175-topic.html#p14227","post_id":"p14227","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Чт 18 Июн 2015 - 0:07","sort_key":"2015-06-18 00:07:00","excerpt":"Нет, там как раз наоборот."},{"doc_id":3039,"url":"../t12p175-topic.html#p14228","post_id":"p14228","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Чт 18 Июн 2015 - 0:16","sort_key":"2015-06-18 00:16:00","excerpt":"Странно, чем она не хэппиэндовая, Сене даже на билеты тратиться не пришлось! Счастье экономно само в руки пришло."},{"doc_id":3040,"url":"../t12p175-topic.html#p14229","post_id":"p14229","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Чт 18 Июн 2015 - 0:56","sort_key":"2015-06-18 00:56:00","excerpt":"...вот это вот щас прозвучало... очень не очень. Ты б сходил почитал концвку-то."},{"doc_id":3041,"url":"../t12p175-topic.html#p14230","post_id":"p14230","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Чт 18 Июн 2015 - 1:01","sort_key":"2015-06-18 01:01:00","excerpt":"Так читал жи. Все плохо, внезапно звонит Мику в дверь, все хорошо. Разве нет?"},{"doc_id":3042,"url":"../t12p175-topic.html#p14231","post_id":"p14231","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Чт 18 Июн 2015 - 1:09","sort_key":"2015-06-18 01:09:00","excerpt":"Нет. Это \"И не мечтай\"."},{"doc_id":3043,"url":"../t12p175-topic.html#p14248","post_id":"p14248","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Surv","posted_at":"Чт 18 Июн 2015 - 10:02","sort_key":"2015-06-18 10:02:00","excerpt":"Спойлер: В концовке \"С новым счастьем\" Мику умирает."},{"doc_id":3044,"url":"../t12p175-topic.html#p14249","post_id":"p14249","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Чт 18 Июн 2015 - 17:16","sort_key":"2015-06-18 17:16:00","excerpt":"Все смешалось в доме Облонских... Спойлер: Это там где она на самолете бьется и письмо оставляет Семену?"},{"doc_id":3045,"url":"../t12p175-topic.html#p14253","post_id":"p14253","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"dobrii_malii","posted_at":"Чт 18 Июн 2015 - 19:59","sort_key":"2015-06-18 19:59:00","excerpt":"Да."},{"doc_id":3046,"url":"../t12p200-topic.html#p14384","post_id":"p14384","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"navigator_zon","posted_at":"Ср 24 Июн 2015 - 20:06","sort_key":"2015-06-24 20:06:00","excerpt":"Концовка \"Моя Мику\" не очень понравилось, хотя концовка и вызвала бурю эмоций. Спойлер: Я ж, гады, так расчувствовался, что потом отходил долго! Нет, оно понятно, что они все же как бы воссоединяются, но не в реальности…"},{"doc_id":3047,"url":"../t12p200-topic.html#p14420","post_id":"p14420","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ornolfr","posted_at":"Пт 26 Июн 2015 - 22:28","sort_key":"2015-06-26 22:28:00","excerpt":"Объясните нубу как выйти на тру-концовку Мику? Играю дрищом под конец набирается лп 19 карма 70. В прохождении как-то не так прописано, мб версия стара."},{"doc_id":3048,"url":"../t12p200-topic.html#p14422","post_id":"p14422","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"dobrii_malii","posted_at":"Пт 26 Июн 2015 - 22:36","sort_key":"2015-06-26 22:36:00","excerpt":"Там нужно менее 19 лп, чтобы Мику отказала в танце на 6 день. А потом решающий выбор у склада."},{"doc_id":3049,"url":"../t12p200-topic.html#p14429","post_id":"p14429","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ornolfr","posted_at":"Пт 26 Июн 2015 - 23:38","sort_key":"2015-06-26 23:38:00","excerpt":"Так все таки меньше надо? В прохождении написано \"Концовки четыре, из них две доступны от 18 лп, ещё 2 от 20 лп.\" Я так понял, 20 лп и не наберешь."},{"doc_id":3050,"url":"../t12p200-topic.html#p14430","post_id":"p14430","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"dobrii_malii","posted_at":"Пт 26 Июн 2015 - 23:40","sort_key":"2015-06-26 23:40:00","excerpt":"Короче, если тебя продинамили с танцем в 6 дне, значит ты на верном пути."},{"doc_id":3051,"url":"../t12p200-topic.html#p14438","post_id":"p14438","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Surv","posted_at":"Сб 27 Июн 2015 - 1:46","sort_key":"2015-06-27 01:46:00","excerpt":"Я вот когда проходил Мику у меня небыло выбора у склада,а вышел на 4 концовки,мож я чё то путаю,но это так. Кстате я так и не смог попасть на момент уборки площади со Славей после дискотеки,наверное как раз потому что…"},{"doc_id":3052,"url":"../t12p200-topic.html#p14439","post_id":"p14439","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"openplace","posted_at":"Сб 27 Июн 2015 - 1:52","sort_key":"2015-06-27 01:52:00","excerpt":"Прошёл старые концовки Мику (0.15c). Хотелось бы сказать пару слов впечатлений о \"С новым счастьем\", которая впоследствии была изменена и дополнена. Спойлер: Если абстрагироваться от мира 7ДЛ, то эта концовка - о…"},{"doc_id":3053,"url":"../t12p200-topic.html#p14965","post_id":"p14965","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Leonov","posted_at":"Вт 14 Июл 2015 - 19:49","sort_key":"2015-07-14 19:49:00","excerpt":"Люди, все в +лп делаю, но все равно на сыч выхожу. В чем трабл ?"},{"doc_id":3054,"url":"../t12p200-topic.html#p14966","post_id":"p14966","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Nenil","posted_at":"Вт 14 Июл 2015 - 20:06","sort_key":"2015-07-14 20:06:00","excerpt":"Может ты на DJ рут не выходишь? Там в столовой Славя прости помочь надо на сцену идти и там надо уговаривать Мику стать DJ на дискотеке."},{"doc_id":3055,"url":"../t12p200-topic.html#p14967","post_id":"p14967","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Leonov","posted_at":"Вт 14 Июл 2015 - 20:08","sort_key":"2015-07-14 20:08:00","excerpt":"[/quote] Может ты на DJ рут не выходишь? Там в столовой Славя прости помочь надо на сцену идти и там надо уговаривать Мику стать DJ на дискотеке.[/quote] Ой спасибо, брат! Спас меня."},{"doc_id":3056,"url":"../t12p200-topic.html#p15106","post_id":"p15106","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"HandOfSorrow","posted_at":"Пн 20 Июл 2015 - 21:37","sort_key":"2015-07-20 21:37:00","excerpt":"Автору: Два часа назад второй раз прошёл \"Моя Мику\", первый раз был около двух месяцев назад, почему-то впечатления сейчас гораздо ярче чем были тогда. В плейлисте на репите стоит Jorge Méndez - Cold(где вы только…"},{"doc_id":3057,"url":"../t12p200-topic.html#p15107","post_id":"p15107","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Nenil","posted_at":"Вт 21 Июл 2015 - 15:04","sort_key":"2015-07-21 15:04:00","excerpt":"Может поправить текстовый вариант прохождения рута? А то в стиме постоянно вопросы: \"почему я не попал на рут?\"."},{"doc_id":3058,"url":"../t12p200-topic.html#p15108","post_id":"p15108","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Вт 21 Июл 2015 - 15:05","sort_key":"2015-07-21 15:05:00","excerpt":"Говоря известной фразой одной девочки \"И кто в этом виноват?\""},{"doc_id":3059,"url":"../t12p200-topic.html#p15335","post_id":"p15335","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Пн 27 Июл 2015 - 16:15","sort_key":"2015-07-27 16:15:00","excerpt":"Жители форума, распишите мне пошагово как выйти на рут с Мику, где Семьон в конце замерзает."},{"doc_id":3060,"url":"../t12p200-topic.html#p15336","post_id":"p15336","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"dobrii_malii","posted_at":"Пн 27 Июл 2015 - 16:22","sort_key":"2015-07-27 16:22:00","excerpt":"У Мику всего один рут, перепутать сложно. А если речь о концовке, то я что-то не припомню такой."},{"doc_id":3061,"url":"../t12p200-topic.html#p15344","post_id":"p15344","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Пн 27 Июл 2015 - 18:33","sort_key":"2015-07-27 18:33:00","excerpt":"Моя мику коль мне память не изменяет."},{"doc_id":3062,"url":"../t12p200-topic.html#p15346","post_id":"p15346","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пн 27 Июл 2015 - 18:54","sort_key":"2015-07-27 18:54:00","excerpt":"У Мику концовки четыре - Встреча в Японии, встреча у Семёна, Встреча в Совёнке и новый год у алтаря. Нет так концовок, где Семён замерзает."},{"doc_id":3063,"url":"../t12p200-topic.html#p15363","post_id":"p15363","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Lansar_Skavana","posted_at":"Пн 27 Июл 2015 - 22:34","sort_key":"2015-07-27 22:34:00","excerpt":"Новый год у алтаря, вот на эту концовку я и не выходил еще."},{"doc_id":3064,"url":"../t12p200-topic.html#p15366","post_id":"p15366","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пн 27 Июл 2015 - 23:13","sort_key":"2015-07-27 23:13:00","excerpt":"Тем же образом, что и на \"Мою Мику\". Спойлер: ЛП меньше 18, на выбор, либо тырим бритву, либо не помогаем Славе, либо не идём смотреть газету. Только соглашаемся с предложением Слави."},{"doc_id":3065,"url":"../t12p200-topic.html#p15431","post_id":"p15431","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Мурфин","posted_at":"Вт 28 Июл 2015 - 12:32","sort_key":"2015-07-28 12:32:00","excerpt":"Самая сильная концовка из всех в моде( на слезу пробила("},{"doc_id":3066,"url":"../t12p200-topic.html#p15557","post_id":"p15557","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Imperfect Machine","posted_at":"Пт 31 Июл 2015 - 21:24","sort_key":"2015-07-31 21:24:00","excerpt":"Неплохо было бы при допиле рута дать Физруку полноценный спрайт. Реликт ещё с старой версии остался."},{"doc_id":3067,"url":"../t12p200-topic.html#p15558","post_id":"p15558","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 31 Июл 2015 - 21:33","sort_key":"2015-07-31 21:33:00","excerpt":"Реликт? О чём речь?"},{"doc_id":3068,"url":"../t12p200-topic.html#p15576","post_id":"p15576","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Imperfect Machine","posted_at":"Сб 1 Авг 2015 - 15:16","sort_key":"2015-08-01 15:16:00","excerpt":"Ну, насколько я помню, до версии 0.20 в Мику-DJ руте Физрука вообще звали \"Борис Александрович\", когда в других рутах всё было уже по-другому. Сейчас уже пофиксили, но спрайта с физруком всё ещё нет. Так и надо, или туда…"},{"doc_id":3069,"url":"../t12p200-topic.html#p15627","post_id":"p15627","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Demiurge-kun","posted_at":"Чт 6 Авг 2015 - 11:01","sort_key":"2015-08-06 11:01:00","excerpt":"Как всегда был он Борисом Санычем, так им и стался же! Да и спрайт при нем. Вы о чем, сударь?"},{"doc_id":3070,"url":"../t12p200-topic.html#p16759","post_id":"p16759","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пн 31 Авг 2015 - 9:29","sort_key":"2015-08-31 09:29:00","excerpt":"Сегодня отмечает свой день рождения всеминамилюбимая языкбезкостей ачтоэтовытутделаетеа Хатсуне Мику! Девочке исполняется 8 лет! Поздравляем! Спойлер:"},{"doc_id":3071,"url":"../t12p225-topic.html#p17867","post_id":"p17867","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Сб 19 Сен 2015 - 20:31","sort_key":"2015-09-19 20:31:00","excerpt":"Привет. Хочу задать вопрос по сюжету. В концовке \"Моя Мику\" в конце: 1. При чём здесь Виола? 2. Разве он не может попасть на хорошую концовку в свою реальность и его тело не будет умирать 3. Как она узнала его? 4. Если…"},{"doc_id":3072,"url":"../t12p225-topic.html#p17868","post_id":"p17868","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Сб 19 Сен 2015 - 20:54","sort_key":"2015-09-19 20:54:00","excerpt":"Привет. 1. Секрет! Объяснение будет в сюжете, но позже. 2. Может, конечно. В \"даже не мечтай\" он попал в свою реальность, и его тело не умирало. 3. А как ты людей на улице узнаешь? Видишь, сличаешь с базой данных в…"},{"doc_id":3073,"url":"../t12p225-topic.html#p17869","post_id":"p17869","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Сб 19 Сен 2015 - 21:02","sort_key":"2015-09-19 21:02:00","excerpt":"Последний ответ видимо в переносном смысле? А если нет, то фамилия тоже чтоле псевдоним. Сложновато для меня)"},{"doc_id":3074,"url":"../t12p225-topic.html#p17871","post_id":"p17871","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Сб 19 Сен 2015 - 21:29","sort_key":"2015-09-19 21:29:00","excerpt":"Погугли значение имени Мику. Ты поймёшь, почему именно имя-фамилия, а не отдельно имя."},{"doc_id":3075,"url":"../t12p225-topic.html#p17875","post_id":"p17875","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Сб 19 Сен 2015 - 22:19","sort_key":"2015-09-19 22:19:00","excerpt":"Извини, поиск безрезультативен( Только что-то про небо, но понять не дало. Как связано Намики Фудзима и Мику Хатсуне)"},{"doc_id":3076,"url":"../t12p225-topic.html#p17880","post_id":"p17880","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"argh","posted_at":"Сб 19 Сен 2015 - 23:09","sort_key":"2015-09-19 23:09:00","excerpt":"Пардон, что вмешиваюсь. Уважаемый co1lector, интернет сие речёт: Имя Мику Хатсуне раскладывается на три японских слога-слова: 初 — Хацу, «первый»; 音 — Нэ, «звук»; 未来 — Мику, «будущее». Вот почему имя-фамилия."},{"doc_id":3077,"url":"../t12p225-topic.html#p17884","post_id":"p17884","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Сб 19 Сен 2015 - 23:36","sort_key":"2015-09-19 23:36:00","excerpt":"Ну да. И логически продолжаем - \"отчаянное будущее\" (см. ивент на пляже и концовки) выступает игрой слов имен Мику-Намики."},{"doc_id":3078,"url":"../t12p225-topic.html#p17885","post_id":"p17885","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Сб 19 Сен 2015 - 23:53","sort_key":"2015-09-19 23:53:00","excerpt":"Ну это уже отсылки) Это же не просто её лагерное произвище. Т.е. она же вроде в реальности лагеря и родилась и дальше жила(кстати всего 18 лет, что печально( ), а не оказалась как Семён в этом мире"},{"doc_id":3079,"url":"../t12p225-topic.html#p17890","post_id":"p17890","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Вс 20 Сен 2015 - 0:19","sort_key":"2015-09-20 00:19:00","excerpt":"А я и не говорил, что это строго лагерное прозвище. Я сказал, что она в лагере фигурировала только под этим именем и представлялась только им. Но на сцене она абсолютно точно выступала тоже как Мику. Наверное, под…"},{"doc_id":3080,"url":"../t12p225-topic.html#p17895","post_id":"p17895","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вс 20 Сен 2015 - 0:35","sort_key":"2015-09-20 00:35:00","excerpt":"Вот это уже многое объясняет, спасибо за ответ. Только Семёну не открыла даже имя собственное почему-то)"},{"doc_id":3081,"url":"../t12p225-topic.html#p17898","post_id":"p17898","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вс 20 Сен 2015 - 0:42","sort_key":"2015-09-20 00:42:00","excerpt":"А как скоро планируешь делать Мику-7дл и Мику-классик? Конечно понимаю, что дело стихийное, но может в планах уже есть"},{"doc_id":3082,"url":"../t12p225-topic.html#p17899","post_id":"p17899","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Вс 20 Сен 2015 - 0:51","sort_key":"2015-09-20 00:51:00","excerpt":"На страничке стима висит офицыяльный план разработки, 7ДЛ-Мику там в далекой перспективе. Классик, видимо, в очень далекой."},{"doc_id":3083,"url":"../t12p225-topic.html#p17977","post_id":"p17977","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 18:27","sort_key":"2015-09-21 18:27:00","excerpt":"Ещё вопрос. Почему Истинная концовка именно эта? И в чём вообще её истинность?) Значит ли, что в остальных на самом деле их встречи не происходит, а это воображение его или что"},{"doc_id":3084,"url":"../t12p225-topic.html#p17978","post_id":"p17978","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пн 21 Сен 2015 - 18:31","sort_key":"2015-09-21 18:31:00","excerpt":"Истинная концовка названа так потому, что полностью объясняет - где и при каких обстоятельствах возможно воссоединение с той самой Мику, что была в лагере. Да, это означает, что в остальных концовках встречи с ней не…"},{"doc_id":3085,"url":"../t12p225-topic.html#p17980","post_id":"p17980","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:01","sort_key":"2015-09-21 19:01:00","excerpt":"Если это кто-то другой, то получается и Семён в жизни и в лагере это разные люди? Т.к. в \"И не мечтай\" она вообще с листочком из лагеря пришла. И в какой концовке тогда он её вообще не встречает? Даже в бэд-концовке он…"},{"doc_id":3086,"url":"../t12p225-topic.html#p17981","post_id":"p17981","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:15","sort_key":"2015-09-21 19:15:00","excerpt":"Тащ, а вы заметили, что Семён каждый вечер перед сном перебирает произошедшие события, и наутро, кратенько, вспоминает их же? Вас это ни на какие мысли не наводит?"},{"doc_id":3087,"url":"../t12p225-topic.html#p17982","post_id":"p17982","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:17","sort_key":"2015-09-21 19:17:00","excerpt":"Извините, поясните. Связи не вижу"},{"doc_id":3088,"url":"../t12p225-topic.html#p17983","post_id":"p17983","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:20","sort_key":"2015-09-21 19:20:00","excerpt":"Прямо сказать не могу, тащ Автор запретил спойлерить. Думайте. тащи, думайте головой."},{"doc_id":3089,"url":"../t12p225-topic.html#p17984","post_id":"p17984","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:22","sort_key":"2015-09-21 19:22:00","excerpt":"Ну, а если не смогу додумать, это в будущих рутах объяснится хотя бы(раз спойлерить)? А то буду себя мучать вечно догадками)"},{"doc_id":3090,"url":"../t12p225-topic.html#p17985","post_id":"p17985","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:26","sort_key":"2015-09-21 19:26:00","excerpt":"В руте Третьего Дня, не раньше. На самом деле, можно ОЧ-Ч-ЧЕНь многое понять из того, что я посчу. Нужно только систематически весь массив информации проанализировать, принимая во внимание уже написанные руты. Ну а если…"},{"doc_id":3091,"url":"../t12p225-topic.html#p17986","post_id":"p17986","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:29","sort_key":"2015-09-21 19:29:00","excerpt":"Ну в голове только очень туманно про то, что как и в оригинальной игре, во всех кроме Тру всё, что происходит, - это только воображение или типа того) Но вроде как эту версию опровергали уже мне"},{"doc_id":3092,"url":"../t12p225-topic.html#p17988","post_id":"p17988","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:33","sort_key":"2015-09-21 19:33:00","excerpt":"Ты плохо думаешь, тащ. Перепройди готовые руты, просмотри рут им.Кошочки по всем веткам, и попробуй сделать непротиворечивые выводы. Всё куда проще, чем кажется."},{"doc_id":3093,"url":"../t12p225-topic.html#p17989","post_id":"p17989","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:36","sort_key":"2015-09-21 19:36:00","excerpt":"Ну ладно, пройду все руты. Только если всё в рутах практически объяснено, не понимаю чего вы так скрываете)"},{"doc_id":3094,"url":"../t12p225-topic.html#p17991","post_id":"p17991","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:40","sort_key":"2015-09-21 19:40:00","excerpt":"А потому что пока всё намёками. Часть ответов даст полное прохождение рута Юли, авторский \"Третий День\" расставит всё по местам окончательно. Но неужели не хочется самому раскусить всю интригу заранее, по намёкам?"},{"doc_id":3095,"url":"../t12p225-topic.html#p17993","post_id":"p17993","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:42","sort_key":"2015-09-21 19:42:00","excerpt":"Всё равно сомнения будут, пока прямо не скажут об этом) Версии всё же разные могут быть, это же мистика, так сказать"},{"doc_id":3096,"url":"../t12p25-topic.html#p10747","post_id":"p10747","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 0:26","sort_key":"2015-03-25 00:26:00","excerpt":"Не дуйся ты так , спасибо , за то что поведал )"},{"doc_id":3097,"url":"../t12p25-topic.html#p10748","post_id":"p10748","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Ср 25 Мар 2015 - 0:32","sort_key":"2015-03-25 00:32:00","excerpt":"Спойлер: \"С новым счастьем\" опирается на ту же \"Моя Мику\", только вместо камбэка в \"Совенок\" там просто всплывает еще одно воспоминание - про авиакатастрофу."},{"doc_id":3098,"url":"../t12p25-topic.html#p10749","post_id":"p10749","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 0:53","sort_key":"2015-03-25 00:53:00","excerpt":"Оу , я бы просто в кашу тогда превратился бы на несколько дней , недель , месяцев. . . ."},{"doc_id":3099,"url":"../t12p25-topic.html#p10750","post_id":"p10750","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Ср 25 Мар 2015 - 1:53","sort_key":"2015-03-25 01:53:00","excerpt":"Я так понимаю, Лена-рут ты тоже еще не проходил?"},{"doc_id":3100,"url":"../t12p25-topic.html#p10752","post_id":"p10752","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 11:19","sort_key":"2015-03-25 11:19:00","excerpt":"Проходил , на хорошую , блин как я охерел когда она витаминки съела . . . ."},{"doc_id":3101,"url":"../t12p25-topic.html#p10753","post_id":"p10753","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Ср 25 Мар 2015 - 11:25","sort_key":"2015-03-25 11:25:00","excerpt":"Спойлер: Просто приезжает на концерт в просто Японию, чуть не заполучив себе парочку нервных срывов во время собеседования в посольстве. Не так-то там всё просто, да и ехал он не за Мику, а за тем, чтобы поставить точку…"},{"doc_id":3102,"url":"../t12p25-topic.html#p10754","post_id":"p10754","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Ср 25 Мар 2015 - 11:52","sort_key":"2015-03-25 11:52:00","excerpt":"Спойлер: Не-а, не такой же. То есть логически да, похожи, но там худчасть создает такую странную атмосферу... Сложно это формализовать, но разница по части восприятия очень существенная. Это в смысле девочка такая…"},{"doc_id":3103,"url":"../t12p25-topic.html#p10755","post_id":"p10755","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 12:10","sort_key":"2015-03-25 12:10:00","excerpt":"Как я понял из выше сказанного - концовка Рикошет и Не Мечтай отличаются тем , что в первой он встречает Мику(ну то бишь как её там зовут . . . Наками) , а во 2 просто смотрит концерт с голограммой и уезжает сычевать ?"},{"doc_id":3104,"url":"../t12p25-topic.html#p10756","post_id":"p10756","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Ср 25 Мар 2015 - 12:11","sort_key":"2015-03-25 12:11:00","excerpt":"Смею заверить, что как минимум до одного читателя донести всё-таки удалось, так что всё не так уж безнадёжно ! Честное слово, не читай я напрямую из скрипта - до последнего момента вместе с ГГ не верил бы в хэппи-энд. Да…"},{"doc_id":3105,"url":"../t12p25-topic.html#p10757","post_id":"p10757","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Ср 25 Мар 2015 - 12:12","sort_key":"2015-03-25 12:12:00","excerpt":"Настоятельно тебе рекомендую ознакомиться со второй концовкой самостоятельно, без спойлеров. Оно того стоит!"},{"doc_id":3106,"url":"../t12p25-topic.html#p10758","post_id":"p10758","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 12:13","sort_key":"2015-03-25 12:13:00","excerpt":"Скажи мне одно , это тоже хорошая или , я буду опять размазан по стенке , как от концовки Моя мику ?"},{"doc_id":3107,"url":"../t12p25-topic.html#p10759","post_id":"p10759","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Ср 25 Мар 2015 - 12:16","sort_key":"2015-03-25 12:16:00","excerpt":"Полагаю, размазан будешь. На всякий случай приготовь носовые платки. Но это именно гуд-энд, можешь не сомневаться."},{"doc_id":3108,"url":"../t12p25-topic.html#p10760","post_id":"p10760","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 12:18","sort_key":"2015-03-25 12:18:00","excerpt":"Хех . . .чертов интригант , ну раз гуд , значит стоит того , но как я понимаю , все же самый лучший энд - это Рикошет ?"},{"doc_id":3109,"url":"../t12p25-topic.html#p10761","post_id":"p10761","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Ср 25 Мар 2015 - 12:26","sort_key":"2015-03-25 12:26:00","excerpt":"Я бы не сказал. В конце концов не зря Рикошета в моде больше нэт."},{"doc_id":3110,"url":"../t12p25-topic.html#p10762","post_id":"p10762","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Ср 25 Мар 2015 - 12:28","sort_key":"2015-03-25 12:28:00","excerpt":"@SashaFran: а в самом деле, ты читаешь 15-й или 16-й билд? В обоих по четыре концовки, но атмосфера (а то и сюжет) в 16-м стала совсем другой как минимум в трёх их них."},{"doc_id":3111,"url":"../t12p25-topic.html#p10763","post_id":"p10763","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 12:36","sort_key":"2015-03-25 12:36:00","excerpt":"16 конечно. И да ты прав , платочек пригодился , но от счастья . Концовка , что ни на есть самая лучшая , зря я сомневался"},{"doc_id":3112,"url":"../t12p25-topic.html#p10764","post_id":"p10764","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 12:38","sort_key":"2015-03-25 12:38:00","excerpt":"это да , хех , прошел весь(ну как весь, готовые руты 7ДЛ), может кто посоветует еще что-то годное на БЛку?"},{"doc_id":3113,"url":"../t12p25-topic.html#p10765","post_id":"p10765","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Ср 25 Мар 2015 - 12:47","sort_key":"2015-03-25 12:47:00","excerpt":"Уровня 7ДЛ - нэт. Это как рикошет - нигде нэт. А так еще \"Возвращение в Совенок\" можно почитать... Не то что бы прямо фонтан, криво, косо, но в целом время, затраченное на прочтение, плюс-минус окупается."},{"doc_id":3114,"url":"../t12p25-topic.html#p10766","post_id":"p10766","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 13:05","sort_key":"2015-03-25 13:05:00","excerpt":"Эх. . .было бы все так просто . Весь стим я перечитал(Саманту , возвращение и т.п) , остается только надежда на версию 1.1 . В ней я успел прочитать только этот мод - 7 Дней лета . А в общем то скажи если не трудно , чем…"},{"doc_id":3115,"url":"../t12p25-topic.html#p10767","post_id":"p10767","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Ср 25 Мар 2015 - 13:24","sort_key":"2015-03-25 13:24:00","excerpt":"Дык... Сам сравни) С заменой ты вроде уже знаком, а Рикошет здесь: http://ficbook.net/readfic/2357926 И скажи заодно, что больше понравилось, для статистики треба."},{"doc_id":3116,"url":"../t12p25-topic.html#p10769","post_id":"p10769","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 14:48","sort_key":"2015-03-25 14:48:00","excerpt":"для меня все хорошо , что хорошо кончается , но нынешняя концовочка по мне так . . . . душевней , неожиданней . . . и можно даже сказать более трогательней , да именно трогательней . Спасибо автору за \"бабочек в животе\"…"},{"doc_id":3117,"url":"../t12p25-topic.html#p10770","post_id":"p10770","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 14:55","sort_key":"2015-03-25 14:55:00","excerpt":"Не знаю . . .сначала мне Мику(Маша) , таки не очень понравилась . . .излишняя болтовня и тому подобные вещи только сопутствовали моему мнению . Однако. . . однако вскоре в моей жизни появился человек очень похожий по…"},{"doc_id":3118,"url":"../t12p25-topic.html#p10771","post_id":"p10771","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Ср 25 Мар 2015 - 15:00","sort_key":"2015-03-25 15:00:00","excerpt":"Спойлер: С Леночкой все-таки иная ситуация - существование Леночки в мире Семена не отрицалось, поэтому сбыча мечт хоть и кажется чудом, но более-менее оправданным и обоснованным. Жила-была девочка Лена, заснула в…"},{"doc_id":3119,"url":"../t12p25-topic.html#p10774","post_id":"p10774","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 15:08","sort_key":"2015-03-25 15:08:00","excerpt":"Вот тут ты не прав , в Концовках И не мечтай и в той что вместо рикошета все объясняется . В концовке , \"И не мечтай\" - Мику говорит , что иногда с виртуалкой выступают и живые артисты . А в той что вместо рикошета*никак…"},{"doc_id":3120,"url":"../t12p25-topic.html#p10776","post_id":"p10776","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 15:22","sort_key":"2015-03-25 15:22:00","excerpt":"Тем более , этоже чудо , а в чудо нужно верить , и если ты будешь пытаться найти ему научное или антинаучное подтверждение , тебя просто выплюнет из этого замечательного места(как то так Семен сказал в оригинале) и в…"},{"doc_id":3121,"url":"../t12p250-topic.html#p17995","post_id":"p17995","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пн 21 Сен 2015 - 19:52","sort_key":"2015-09-21 19:52:00","excerpt":"Мистики нету, зупдаю. Перегарретовский правый верхний клык устроит? Его как раз надо немножко простимулировать, а то он совсем в Годвилль сбежал от нашего коллекивного благородного безумия. А по логике всё чётко…"},{"doc_id":3122,"url":"../t12p250-topic.html#p17996","post_id":"p17996","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 19:57","sort_key":"2015-09-21 19:57:00","excerpt":"Ох, к сожалению я ещё ньюфаг и не могу в ЛС. Может E-mail или другое дадите"},{"doc_id":3123,"url":"../t12p250-topic.html#p17997","post_id":"p17997","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"argh","posted_at":"Пн 21 Сен 2015 - 20:01","sort_key":"2015-09-21 20:01:00","excerpt":"Семён - очень криво разработанная ОС-ка. Без ежедневных вечерних бэкапов, и утренней их загрузки - не работает. Это если лень думать. И не вдаваться в подробности, чтобы прийти к другим выводам."},{"doc_id":3124,"url":"../t12p250-topic.html#p17998","post_id":"p17998","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"argh","posted_at":"Пн 21 Сен 2015 - 20:02","sort_key":"2015-09-21 20:02:00","excerpt":"Вас приглашают в раздел \"Флудильня\", подраздел \"Бар \"7 летних ночей\"."},{"doc_id":3125,"url":"../t12p250-topic.html#p18018","post_id":"p18018","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 23:09","sort_key":"2015-09-21 23:09:00","excerpt":"Поясните, сир, будьте добры. Прямым текстом, не доходит. Я пойму, скажу \"Какой же я тупой, это так просто\" и буду думать новые вопросы)"},{"doc_id":3126,"url":"../t12p250-topic.html#p18025","post_id":"p18025","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"argh","posted_at":"Пн 21 Сен 2015 - 23:31","sort_key":"2015-09-21 23:31:00","excerpt":"Да шутка это корявая, может в ней и есть крупица правды, а может и нет. Разработчикам Семёна виднее. Милсдарь co1lector. Но трудно представить себе психически здорового человека. Перед сном - сегодня было 1. 2. 3. и т.д…"},{"doc_id":3127,"url":"../t12p250-topic.html#p19121","post_id":"p19121","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вт 29 Сен 2015 - 12:53","sort_key":"2015-09-29 12:53:00","excerpt":"Господа, нету ли ни у кого такой Мику, но на фото профиля в формате квадрата желательно? Буду очень благодарен Спойлер:"},{"doc_id":3128,"url":"../t12p250-topic.html#p19124","post_id":"p19124","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Вт 29 Сен 2015 - 13:44","sort_key":"2015-09-29 13:44:00","excerpt":"Это же ЦГ из пятого дня. Спойлер:"},{"doc_id":3129,"url":"../t12p250-topic.html#p19128","post_id":"p19128","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вт 29 Сен 2015 - 14:17","sort_key":"2015-09-29 14:17:00","excerpt":"Спасибо, но мне бы найти ЦГ, где голова не обрезана"},{"doc_id":3130,"url":"../t12p250-topic.html#p19129","post_id":"p19129","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Вт 29 Сен 2015 - 14:18","sort_key":"2015-09-29 14:18:00","excerpt":"Руками только"},{"doc_id":3131,"url":"../t12p250-topic.html#p19131","post_id":"p19131","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вт 29 Сен 2015 - 14:25","sort_key":"2015-09-29 14:25:00","excerpt":"Вот я и спрашиваю. Может у кого-то из пряморуких свободное время и желание найдётся"},{"doc_id":3132,"url":"../t12p250-topic.html#p19132","post_id":"p19132","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Вт 29 Сен 2015 - 15:57","sort_key":"2015-09-29 15:57:00","excerpt":"Не сказал бы, чтобы я особо пряморукий, но как-то так, наверное. Спойлер:"},{"doc_id":3133,"url":"../t12p250-topic.html#p19133","post_id":"p19133","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Вт 29 Сен 2015 - 16:02","sort_key":"2015-09-29 16:02:00","excerpt":"Спасибо огромное, тащ автор! Очень даже пряморукий"},{"doc_id":3134,"url":"../t12p250-topic.html#p19475","post_id":"p19475","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:04","sort_key":"2015-10-02 01:04:00","excerpt":"А как же депрессия насчёт существования себя самой? И в чём выражается её поверхностность и легкомысленность, например? Ведь \"болтает и смеётся\" может быть описанием просто позитивного человека. Это задевает меня…"},{"doc_id":3135,"url":"../t12p250-topic.html#p19477","post_id":"p19477","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:18","sort_key":"2015-10-02 01:18:00","excerpt":"Депрессия входит в оставшийся 1%. Поверхностность заключается в именно этой попрыгушечности. И нет, \"болтает и смеётся\" не может быть описанием позитивного человека, потому что у него кроме этого обязательно есть и…"},{"doc_id":3136,"url":"../t12p250-topic.html#p19478","post_id":"p19478","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:21","sort_key":"2015-10-02 01:21:00","excerpt":"Ну \"легкомысленность и поверхностность\" звучат, как плохие черты."},{"doc_id":3137,"url":"../t12p250-topic.html#p19479","post_id":"p19479","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:25","sort_key":"2015-10-02 01:25:00","excerpt":"Только для тебя. Де факто это объективный критерий оценки персонажа. Не грузит своими проблемами и не ноет, как все вокруг плохо, не ударяется в дешёвый психоанализ - чего тебе ещё для счастья надо?"},{"doc_id":3138,"url":"../t12p250-topic.html#p19480","post_id":"p19480","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:26","sort_key":"2015-10-02 01:26:00","excerpt":"А попробуй на эти черты с плохой стороны посмотреть, я просто что-то не могу найти таких моментов. И где гарантия, что не ударяется в психоанализ?"},{"doc_id":3139,"url":"../t12p250-topic.html#p19482","post_id":"p19482","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:30","sort_key":"2015-10-02 01:30:00","excerpt":"А зачем мне на это смотреть с плохой стороны? Чем лично мне это может быть полезно? Или персонажу? Никаких гарантий. Ещё одна аксиома - Мику не ударяется в психоанализ. Для этого есть Леночка."},{"doc_id":3140,"url":"../t12p250-topic.html#p19483","post_id":"p19483","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:31","sort_key":"2015-10-02 01:31:00","excerpt":"Хорошо, тогда мне интересно, глупая ли Мику?"},{"doc_id":3141,"url":"../t12p250-topic.html#p19485","post_id":"p19485","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:44","sort_key":"2015-10-02 01:44:00","excerpt":"Ну вот чем ты читал то, что я тебе писал несколькими постами выше?.."},{"doc_id":3142,"url":"../t12p250-topic.html#p19486","post_id":"p19486","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:45","sort_key":"2015-10-02 01:45:00","excerpt":"Прямым текстом хочу узнать"},{"doc_id":3143,"url":"../t12p250-topic.html#p19487","post_id":"p19487","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:49","sort_key":"2015-10-02 01:49:00","excerpt":"Хорошо, прямым текстом пишу тебе то, что ты и так должен был понять: нет. Не дурочка."},{"doc_id":3144,"url":"../t12p250-topic.html#p19488","post_id":"p19488","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:51","sort_key":"2015-10-02 01:51:00","excerpt":"Фух, спасибо. Просто когда ты написал про то, что она не занимается психоанализом, у меня почему-то этот вопрос возник. Да и Гуглъ по \"Бака\" выдал \"дурак\""},{"doc_id":3145,"url":"../t12p250-topic.html#p19489","post_id":"p19489","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 2 Окт 2015 - 1:54","sort_key":"2015-10-02 01:54:00","excerpt":"Человеку хватает ума понять все недостатки сложившегося образа. Человеку хватает ума не пытаться переломить себя ради каждого встречного-поперечное (моё любимое \"я вам не пятьсот рублей, чтобы нравиться напропалую…"},{"doc_id":3146,"url":"../t12p275-topic.html#p19490","post_id":"p19490","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 2 Окт 2015 - 1:56","sort_key":"2015-10-02 01:56:00","excerpt":"Просто ты лишний раз мне доказал, что в Мику недостатков нет(для меня), за что огромное спасибо"},{"doc_id":3147,"url":"../t12p275-topic.html#p20504","post_id":"p20504","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 15:20","sort_key":"2015-10-09 15:20:00","excerpt":"Я так и не понял В \"Обязательно дождись!\" ему привиделась встреча? Просто то это пишут, а потом рассуждают на тему того, откуда у Намики-ровесницы есть воспоминания про лагерь. Если ему это всё привиделось, то зачем…"},{"doc_id":3148,"url":"../t12p275-topic.html#p20505","post_id":"p20505","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Пт 9 Окт 2015 - 15:48","sort_key":"2015-10-09 15:48:00","excerpt":"Где же эта картинка с котами, когда она так нужна..."},{"doc_id":3149,"url":"../t12p275-topic.html#p20506","post_id":"p20506","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 15:55","sort_key":"2015-10-09 15:55:00","excerpt":"Лучше бы пояснил. И понять я в состоянии, только неоднозначные комментарии путают меня."},{"doc_id":3150,"url":"../t12p275-topic.html#p20507","post_id":"p20507","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 16:25","sort_key":"2015-10-09 16:25:00","excerpt":"Вроде как встреча привиделась Семену в концовке \"И не мечтай!\", там после титров есть послесловие (не знаю, добавлено ли оно в основной мод, ориентируюсь по \"7дл концовки\"), а в \"Обязательно дождись!\" такого нет."},{"doc_id":3151,"url":"../t12p275-topic.html#p20508","post_id":"p20508","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:29","sort_key":"2015-10-09 16:29:00","excerpt":"Однако почитай всю Мику-тему. Я знаю про \"И не мечтай\", все концовки не на раз перечитал."},{"doc_id":3152,"url":"../t12p275-topic.html#p20509","post_id":"p20509","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 9 Окт 2015 - 16:33","sort_key":"2015-10-09 16:33:00","excerpt":"Это временно, если память не изменяет."},{"doc_id":3153,"url":"../t12p275-topic.html#p20510","post_id":"p20510","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:34","sort_key":"2015-10-09 16:34:00","excerpt":"Значит привиделось? Ну что ж, это более определённо, чем peregarrett."},{"doc_id":3154,"url":"../t12p275-topic.html#p20511","post_id":"p20511","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 16:37","sort_key":"2015-10-09 16:37:00","excerpt":"Тогда печалька, я вообще люблю драму и нетривиальные концовки, но все же один хэппи энд с каждой девочкой Сема, на мой взгляд, заслужил (если все сделал по высшему разряду, разумеется)"},{"doc_id":3155,"url":"../t12p275-topic.html#p20512","post_id":"p20512","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:38","sort_key":"2015-10-09 16:38:00","excerpt":"Да, печально.. Будем довольствоваться Моей Мику"},{"doc_id":3156,"url":"../t12p275-topic.html#p20513","post_id":"p20513","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 16:43","sort_key":"2015-10-09 16:43:00","excerpt":"\"Моя Мику\" можно назвать хэппи эндом с большой натяжкой) Эта концовка нужна скорее для более глубокого понимания происходящего. Хотя не думаю, что все будет так плохо, в любом случае положительные концовки будут, просто…"},{"doc_id":3157,"url":"../t12p275-topic.html#p20514","post_id":"p20514","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:43","sort_key":"2015-10-09 16:43:00","excerpt":"Всяко лучше \"С Новым счастьем\". И если \"гуд\" концовки всего лишь галлюцинации - то и их лучше."},{"doc_id":3158,"url":"../t12p275-topic.html#p20515","post_id":"p20515","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 16:49","sort_key":"2015-10-09 16:49:00","excerpt":"А вот тут черт его знает. В \"Моей Мику\" слишком много неопределенности. Да, они вроде как встретились, и все хорошо. Но где гарантия, что они останутся вместе? Что Семена не вышвырнет опять в другую реальность? Что не…"},{"doc_id":3159,"url":"../t12p275-topic.html#p20516","post_id":"p20516","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:50","sort_key":"2015-10-09 16:50:00","excerpt":"Хм.. А по-моему понятно то, что он нашёл способ всегда оставаться в лагере, ведь он уже там много и больше раз."},{"doc_id":3160,"url":"../t12p275-topic.html#p20517","post_id":"p20517","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 9 Окт 2015 - 16:54","sort_key":"2015-10-09 16:54:00","excerpt":"Может и привиделось. Но возможно - лишь возможно - все несколько сложнее. В конце концов не тот это мод, чтобы джойкиллер был просто джойкиллером. ПГС: Моя ставка на то, что после перехода на альт-первый день 7ДЛ…"},{"doc_id":3161,"url":"../t12p275-topic.html#p20518","post_id":"p20518","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:56","sort_key":"2015-10-09 16:56:00","excerpt":"Интересная версия. Я думал, что альт-день просто открывает недосказанности. Но ведь даже с ним в \"Обязательно дождись\" особых намёков на нереальность происходящего нет."},{"doc_id":3162,"url":"../t12p275-topic.html#p20519","post_id":"p20519","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 16:59","sort_key":"2015-10-09 16:59:00","excerpt":"Да, действительно концепт выглядит интересно, только это уже напоминает концепт оригинала (множество Семенов в разных мирах, пускай здесь и один альтернативный Семен), а автор говорил вроде, что не собирается…"},{"doc_id":3163,"url":"../t12p275-topic.html#p20520","post_id":"p20520","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 16:59","sort_key":"2015-10-09 16:59:00","excerpt":"Да вроде тут тоже дофига и больше Семёнов и миров."},{"doc_id":3164,"url":"../t12p275-topic.html#p20521","post_id":"p20521","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Dantiras","posted_at":"Пт 9 Окт 2015 - 17:04","sort_key":"2015-10-09 17:04:00","excerpt":"Привет Вам от дневника ОД из Сыч-рута. Про множественность миров никто не говорил. Разговор уже вышел за рамки Мику-ДЖ - пора во флудильню, господа."},{"doc_id":3165,"url":"../t12p275-topic.html#p20522","post_id":"p20522","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:05","sort_key":"2015-10-09 17:05:00","excerpt":"Цикличность во всяком случае присутствует."},{"doc_id":3166,"url":"../t12p275-topic.html#p20524","post_id":"p20524","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 17:18","sort_key":"2015-10-09 17:18:00","excerpt":"Откуда странные выводы о том, что ему что-то привиделось? Я где-то это писал? Там, где ему что-то привиделось, добавлены послесловия (бесплатный хинт от автора: послесловия добавлены во все концовки, где Семёну всё…"},{"doc_id":3167,"url":"../t12p275-topic.html#p20525","post_id":"p20525","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:21","sort_key":"2015-10-09 17:21:00","excerpt":"Хм, ну это.."},{"doc_id":3168,"url":"../t12p275-topic.html#p20526","post_id":"p20526","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Moonshine","posted_at":"Пт 9 Окт 2015 - 17:25","sort_key":"2015-10-09 17:25:00","excerpt":"Ну тут как бы имелось ввиду, что Семен поехал туда, чтобы свыкнуться с мыслью о том, что ему события в лагере привиделись. И забыть об этом раз и навсегда. А получилось все несколько иначе."},{"doc_id":3169,"url":"../t12p275-topic.html#p20527","post_id":"p20527","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 17:27","sort_key":"2015-10-09 17:27:00","excerpt":"И что дальше? Требуется перевод с русского на русский?"},{"doc_id":3170,"url":"../t12p275-topic.html#p20528","post_id":"p20528","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 17:27","sort_key":"2015-10-09 17:27:00","excerpt":"Да, как я понял, суть в том, что Семен не верил в то, что встретит Мику в Японии. Просто нужно было сделать хоть что-то (собственно, как выше уже автор сказал, инициативный Семен придет к успеху, в отличие от Емели на…"},{"doc_id":3171,"url":"../t12p300-topic.html#p20529","post_id":"p20529","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:31","sort_key":"2015-10-09 17:31:00","excerpt":"А это что тогда"},{"doc_id":3172,"url":"../t12p300-topic.html#p20530","post_id":"p20530","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:32","sort_key":"2015-10-09 17:32:00","excerpt":"Ну вроде как в этом сообщении говорится о том, что встречи как бы не было, а минутой раньше вы сказали, что была.. Я в замешательстве немного."},{"doc_id":3173,"url":"../t12p300-topic.html#p20531","post_id":"p20531","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Moonshine","posted_at":"Пт 9 Окт 2015 - 17:37","sort_key":"2015-10-09 17:37:00","excerpt":"Ну сходил бы на концерт, спел песню, убедился бы, что Мику в его мире действительно лишь виртуальный образ. И продолжил бы жить своей обычной жизнью, той которая была до лагеря."},{"doc_id":3174,"url":"../t12p300-topic.html#p20532","post_id":"p20532","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Skiminok","posted_at":"Пт 9 Окт 2015 - 17:39","sort_key":"2015-10-09 17:39:00","excerpt":"Да, это скорее как внутренний монолог Семена, план действий. Я думаю, кого-то может смутить отсутствие частицы \"бы\", тогда все сразу понятно становится."},{"doc_id":3175,"url":"../t12p300-topic.html#p20533","post_id":"p20533","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:39","sort_key":"2015-10-09 17:39:00","excerpt":"Именно это меня и смущает."},{"doc_id":3176,"url":"../t12p300-topic.html#p20534","post_id":"p20534","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 17:40","sort_key":"2015-10-09 17:40:00","excerpt":"Возможно, стоит читать нормально, а не по диагонали? А теперь читаем вместе - ехал на за Мику, а затем, чтобы закрыть историю. Теперь о том, как он хочет закрыть эту историю, культурная программа: покричал, помахал…"},{"doc_id":3177,"url":"../t12p300-topic.html#p20535","post_id":"p20535","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:41","sort_key":"2015-10-09 17:41:00","excerpt":"Хм, видимо только мне. Я подумал, что это хронология событий, а не его мысли."},{"doc_id":3178,"url":"../t12p300-topic.html#p20536","post_id":"p20536","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 17:47","sort_key":"2015-10-09 17:47:00","excerpt":"Он не пел, не махал палочкой. Он вообще ничего не сделал, кроме того, что позвал её по имени и потом десять минут постоял в беснующейся толпе. Там даже песня начаться не успела Ну вы хотя бы чуть-чуть внимательнее…"},{"doc_id":3179,"url":"../t12p300-topic.html#p20537","post_id":"p20537","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:52","sort_key":"2015-10-09 17:52:00","excerpt":"Хм, ну если бы я просто прочитал рут - у меня бы и не возникло мысли, что это привиделось. А, посмотрев сообщение, можно предположить так: ему эта встреча и охранник привиделись, а потом он уже махал палочкой и пел. Как…"},{"doc_id":3180,"url":"../t12p300-topic.html#p20538","post_id":"p20538","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 17:55","sort_key":"2015-10-09 17:55:00","excerpt":"Я не виноват в твоём ПГС. Да и в чьём-либо ещё. Оккама на вас нет."},{"doc_id":3181,"url":"../t12p300-topic.html#p20539","post_id":"p20539","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 17:56","sort_key":"2015-10-09 17:56:00","excerpt":"ПГС тут мой как раз не сработал. Я просто прочитал твоё сообщение и понял его в прямом смысле."},{"doc_id":3182,"url":"../t12p300-topic.html#p20540","post_id":"p20540","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 18:04","sort_key":"2015-10-09 18:04:00","excerpt":"Нет, не в прямом. Оно же противоречит вообще всему, что здесь обсуждалось, какой же это прямой смысл? Включая пояснения по хардкору: в \"Мёрзну\" Семён завершает цикл Шизы, становясь Шизой сам, в \"Мир сошёл с ума\"…"},{"doc_id":3183,"url":"../t12p300-topic.html#p20541","post_id":"p20541","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:13","sort_key":"2015-10-09 18:13:00","excerpt":"А я и не против Ну, если брать это единичное сообщение, то в прямом смысле я его понял. Просто ты не написал, что это (\"Приснилось, привиделось. Укатил к себе сычевать\") - мысли Семёна, вот я и счёл это за твои мысли. А…"},{"doc_id":3184,"url":"../t12p300-topic.html#p20543","post_id":"p20543","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 9 Окт 2015 - 18:21","sort_key":"2015-10-09 18:21:00","excerpt":"Пральна, нафиг нужен унылый генофонд, когда есть лучшая девочка планеты? И раз уж пояснения по хардорку пошли. Превращение Семена в Шизу объясняет перенос его памяти с завершенного рута. А как Мика свой багаж притащила?"},{"doc_id":3185,"url":"../t12p300-topic.html#p20544","post_id":"p20544","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:25","sort_key":"2015-10-09 18:25:00","excerpt":"Тут об этом уже говорилось, попробую объяснить. Намики-2014 как бы заимствовала тело и, судя по всему, память (ведь она не вспомнила, что из будущего сама) Намики-советской, а потом вернулась в своё время."},{"doc_id":3186,"url":"../t12p300-topic.html#p20547","post_id":"p20547","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 9 Окт 2015 - 18:28","sort_key":"2015-10-09 18:28:00","excerpt":"Эт понятно. Меня механика реверса интересует - как Намики-советская в начале цикла подхватила память из своего уже завершенного рута."},{"doc_id":3187,"url":"../t12p300-topic.html#p20549","post_id":"p20549","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:29","sort_key":"2015-10-09 18:29:00","excerpt":"Хм, а про какой рут идёт речь? Вроде Намики-советская ничего не знает о будущем."},{"doc_id":3188,"url":"../t12p300-topic.html#p20554","post_id":"p20554","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 9 Окт 2015 - 18:33","sort_key":"2015-10-09 18:33:00","excerpt":"Ну труЪ-концовка, \"Моя Мику\"."},{"doc_id":3189,"url":"../t12p300-topic.html#p20556","post_id":"p20556","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:35","sort_key":"2015-10-09 18:35:00","excerpt":"Дак там же вроде далеко не начало цикла. Но видимо она начала вспоминать предыдущие циклы. Семён же тоже сначала не вспоминал, судя по записке, данной ОД."},{"doc_id":3190,"url":"../t12p300-topic.html#p20557","post_id":"p20557","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 9 Окт 2015 - 18:35","sort_key":"2015-10-09 18:35:00","excerpt":"Мику в \"моей Мику\"? Да так же, примерно, как Лена нарисовала крушение самолёта в \"с Новым счастьем\" (= И да, \"генофонду\" набиты 5к строчек, но мне их лениво гнать в код, так что пишу текстом напропалую. Прямо сейчас…"},{"doc_id":3191,"url":"../t12p300-topic.html#p20560","post_id":"p20560","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 9 Окт 2015 - 18:38","sort_key":"2015-10-09 18:38:00","excerpt":"> Лена нарисовала крушение самолёта Что-что?"},{"doc_id":3192,"url":"../t12p300-topic.html#p20561","post_id":"p20561","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:41","sort_key":"2015-10-09 18:41:00","excerpt":"Вообщем я думаю это то, что я написал. Просто начала вспоминать, как и Семён в этих циклах. Каким образом? - Ответ нас ждёт в Д3, я думаю."},{"doc_id":3193,"url":"../t12p300-topic.html#p20566","post_id":"p20566","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Коллекционер","posted_at":"Пт 9 Окт 2015 - 18:51","sort_key":"2015-10-09 18:51:00","excerpt":"Оффтопчик: В моде стимовском ошибочка, игра тупо не запускается. В Жуках уже писали"},{"doc_id":3194,"url":"../t12p300-topic.html#p20568","post_id":"p20568","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 9 Окт 2015 - 18:55","sort_key":"2015-10-09 18:55:00","excerpt":"я знаю: Сегодня вечером обновлю - вчера не было возможности, на работе тоже возможности нет."},{"doc_id":3195,"url":"../t12p300-topic.html#p20587","post_id":"p20587","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Dantiras","posted_at":"Пт 9 Окт 2015 - 19:21","sort_key":"2015-10-09 19:21:00","excerpt":"Оффтоп ще раз: Дрищ-вариант рута Леночки с предусловием записи в стенгазету. Там ещё и Алёна всплывает до кучи"},{"doc_id":3196,"url":"../t12p325-topic.html#p20765","post_id":"p20765","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Do.rian","posted_at":"Сб 10 Окт 2015 - 2:01","sort_key":"2015-10-10 02:01:00","excerpt":"А вдруг *внезапно* это аторская задумка? </X-FILES_THEME\\>"},{"doc_id":3197,"url":"../t12p325-topic.html#p20773","post_id":"p20773","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Сб 10 Окт 2015 - 2:38","sort_key":"2015-10-10 02:38:00","excerpt":"Да нет, это стопудово само в руте написалось, ерунду какую-то городишь!"},{"doc_id":3198,"url":"../t12p50-topic.html#p10780","post_id":"p10780","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 17:17","sort_key":"2015-03-25 17:17:00","excerpt":"А еще , автор сея творения может поведать - что же случилось с Микой в \"Моя Мику\"(из-за чего она умерла) ?"},{"doc_id":3199,"url":"../t12p50-topic.html#p10781","post_id":"p10781","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Ср 25 Мар 2015 - 17:40","sort_key":"2015-03-25 17:40:00","excerpt":"Не знаю, что поведает автор, но как по мне, Спойлер: если это и не суицид, то очень-очень своевременная и очень-очень гуманная по отношению к страдающей Мику смерть... EDIT: А вообще, такие вопросы надо бы под спойлер…"},{"doc_id":3200,"url":"../t12p50-topic.html#p10782","post_id":"p10782","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 20:56","sort_key":"2015-03-25 20:56:00","excerpt":"Оу , забыл"},{"doc_id":3201,"url":"../t12p50-topic.html#p10783","post_id":"p10783","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 20:58","sort_key":"2015-03-25 20:58:00","excerpt":"Оу , забыл"},{"doc_id":3202,"url":"../t12p50-topic.html#p10787","post_id":"p10787","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Ср 25 Мар 2015 - 21:28","sort_key":"2015-03-25 21:28:00","excerpt":"Посоветуйте фанфиков с главным рутом которого была Мику(Маша)"},{"doc_id":3203,"url":"../t12p50-topic.html#p10790","post_id":"p10790","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Константин Noir Сычев","posted_at":"Чт 26 Мар 2015 - 0:16","sort_key":"2015-03-26 00:16:00","excerpt":"Miku no uta. А вообще зайди на Викию в раздел фанфиков, посмотри там."},{"doc_id":3204,"url":"../t12p50-topic.html#p10805","post_id":"p10805","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Вс 29 Мар 2015 - 17:27","sort_key":"2015-03-29 17:27:00","excerpt":"Ребзь, это нормально, что при этом руте меня не пропускает дальше 4 дня? В другом руте мику не пропускает далее 5. Это версия старая, или я идиот?"},{"doc_id":3205,"url":"../t12p50-topic.html#p10806","post_id":"p10806","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Вс 29 Мар 2015 - 18:14","sort_key":"2015-03-29 18:14:00","excerpt":"Ненормально. Или ты вместо диджей-рута попал на классик или 7дл."},{"doc_id":3206,"url":"../t12p50-topic.html#p10819","post_id":"p10819","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Пн 30 Мар 2015 - 11:49","sort_key":"2015-03-30 11:49:00","excerpt":"Хм, я точно пригласил мику быть диджеем, до этого был пляж, на диджея она согласилась... Мне написали что то типа: \"Вы соблазнили звезду, молодцы, но рут в разработке\". Версия старая?"},{"doc_id":3207,"url":"../t12p50-topic.html#p10820","post_id":"p10820","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Пн 30 Мар 2015 - 11:59","sort_key":"2015-03-30 11:59:00","excerpt":"Старая, похоже. Бери свежую из соседнего подфорума"},{"doc_id":3208,"url":"../t12p50-topic.html#p10821","post_id":"p10821","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Пн 30 Мар 2015 - 14:13","sort_key":"2015-03-30 14:13:00","excerpt":"Ага, спасибо, нашел. Ммм, можно ещё вопрос? В чем разница между классик мику и 7дл мику?"},{"doc_id":3209,"url":"../t12p50-topic.html#p10822","post_id":"p10822","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Пн 30 Мар 2015 - 15:28","sort_key":"2015-03-30 15:28:00","excerpt":"Две разных ветки, обе не доделаны. Выход на классик - после первого танца пойти помочь кибениматикам, на 7дл - послать кибениматиков и танцевать с Мику (при условии, что не вляпался в поиск диджея)."},{"doc_id":3210,"url":"../t12p50-topic.html#p10828","post_id":"p10828","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Пн 30 Мар 2015 - 17:23","sort_key":"2015-03-30 17:23:00","excerpt":"Ага, значит я был на 7дл. Жаль что не доделан, оч понравилось :с"},{"doc_id":3211,"url":"../t12p50-topic.html#p10933","post_id":"p10933","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 1:54","sort_key":"2015-04-02 01:54:00","excerpt":"alt_mi_dj_route.rpy: 786 \"в помещении разнеслись едва слышимые клавишные\" - и в это время фоном играет не то гитара, не то две..."},{"doc_id":3212,"url":"../t12p50-topic.html#p10935","post_id":"p10935","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 2:14","sort_key":"2015-04-02 02:14:00","excerpt":"Ой, и баг. Переменная alt_day4_mi_dj_reasons объявлена в начале скрипта как написано, зато потом в условиях она выглядит как alt_day4_Mi_dj_reasons. Я рекомендую всё-таки всё в нижнем регистре писать. И пройтись по всем…"},{"doc_id":3213,"url":"../t12p50-topic.html#p10939","post_id":"p10939","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 3:16","sort_key":"2015-04-02 03:16:00","excerpt":"3522: dv \"Ольга Дмитриевна, вы слышали?\" 3523: me \"Слышала. Теперь твой второй косяк…\" Здесь точно me? А не mt, то есть Ольга?"},{"doc_id":3214,"url":"../t12p50-topic.html#p10940","post_id":"p10940","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 3:31","sort_key":"2015-04-02 03:31:00","excerpt":"Пятый день. \"Я бы помнил, как летом 89го года\" - а ему в этом руте кто-то говорил про год? Я помню точную дату только у Лены."},{"doc_id":3215,"url":"../t12p50-topic.html#p10942","post_id":"p10942","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Чт 2 Апр 2015 - 12:27","sort_key":"2015-04-02 12:27:00","excerpt":"До этого так здорово указывал ошибки, с номером строки. А тут раз... и ищи как хошь."},{"doc_id":3216,"url":"../t12p50-topic.html#p10943","post_id":"p10943","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 12:51","sort_key":"2015-04-02 12:51:00","excerpt":"Ну лень мне было в скрипт лезть уже... Мне кажется, что поиск по \\D89 выдаст не больше одного вхождения."},{"doc_id":3217,"url":"../t12p50-topic.html#p10945","post_id":"p10945","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 13:51","sort_key":"2015-04-02 13:51:00","excerpt":"Строка 3868 в alt_mi_dj_route.rpy."},{"doc_id":3218,"url":"../t12p50-topic.html#p10946","post_id":"p10946","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 14:07","sort_key":"2015-04-02 14:07:00","excerpt":"Ещё замечание по сюжету. Уля говорит Семёну - \"Мику взяла у вожатой опасную бритву, хотя у неё есть японский станок\". У 16-летней советской девушки наличие бритвы предполагается нормальным и вопросов не вызывает?"},{"doc_id":3219,"url":"../t12p50-topic.html#p10951","post_id":"p10951","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Чт 2 Апр 2015 - 14:57","sort_key":"2015-04-02 14:57:00","excerpt":"У Алисы же взяла вроде, не? Её еще вернуть можно будет потом."},{"doc_id":3220,"url":"../t12p50-topic.html#p10952","post_id":"p10952","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 15:06","sort_key":"2015-04-02 15:06:00","excerpt":"Ну или у Алисы. Тем более. Меня сюжетный аспект интересует. Советская девочка Ульяна считает нормальным, что 16-летняя девушка использует бритву. Что Мику, что, тем более, Алиса..."},{"doc_id":3221,"url":"../t12p50-topic.html#p10954","post_id":"p10954","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Чт 2 Апр 2015 - 15:11","sort_key":"2015-04-02 15:11:00","excerpt":"Советская девочка Ульяна смотрит на Алису как на старшую подругу, и априори одобряет ее безумства. А Алиса - дитя улиц... Хотя опасная бритва - это все-таки странновато. Хотя бы потому, что девайс это весьма непростой…"},{"doc_id":3222,"url":"../t12p50-topic.html#p10955","post_id":"p10955","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 15:16","sort_key":"2015-04-02 15:16:00","excerpt":"Просто Алиса с Леночкой выросли вместе."},{"doc_id":3223,"url":"../t12p75-topic.html#p10959","post_id":"p10959","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 15:59","sort_key":"2015-04-02 15:59:00","excerpt":"Впрочем, ладно, спишем бритву на условности."},{"doc_id":3224,"url":"../t12p75-topic.html#p10962","post_id":"p10962","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Чт 2 Апр 2015 - 23:10","sort_key":"2015-04-02 23:10:00","excerpt":"В разборки с разрезанием руки я бы добавил шизокомментарии. Потому что Сеня ведёт себя как полный неадекват. Сам натворил дел, а потом плачется \"Мику, мне больно, зачем ТЫ это делаешь, Мику, ыыы, я даже руку себе…"},{"doc_id":3225,"url":"../t12p75-topic.html#p10964","post_id":"p10964","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Пт 3 Апр 2015 - 0:36","sort_key":"2015-04-03 00:36:00","excerpt":"Вероятно, я и сам не вполне адекватен, но этот эпизод, как раз, никаких претензий или сомнений не вызвал. Жёстко, но предельно ясно и доходчиво. Очень убедительно. Возможно, один из самых впечатляющих эпизодов в руте до…"},{"doc_id":3226,"url":"../t12p75-topic.html#p10965","post_id":"p10965","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 0:43","sort_key":"2015-04-03 00:43:00","excerpt":"Да нет, эпизод хороший. Визуально. И чувственно. Жертва есть жертва, она всегда впечатляет. Только комментарии к жертве \"посмотри, как мне больно от того, что я тебе сделал больно\" - это же перенос ответственности…"},{"doc_id":3227,"url":"../t12p75-topic.html#p10968","post_id":"p10968","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Chess","posted_at":"Пт 3 Апр 2015 - 1:04","sort_key":"2015-04-03 01:04:00","excerpt":"А пусть он себе шкуру с руки сдерёт, как во втором терминаторе! Будет мощно ящетаю."},{"doc_id":3228,"url":"../t12p75-topic.html#p10969","post_id":"p10969","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 1:09","sort_key":"2015-04-03 01:09:00","excerpt":"А зачем? Вообще, когда я в баблах читал спойлеры про бритву и членовредительство, я думал, будет что-то про \"настоящее-не настоящее\". Сон-не сон, выдуманные не чувствуют боли, что-то в этом роде. Да, я знаю, что это Мику…"},{"doc_id":3229,"url":"../t12p75-topic.html#p10971","post_id":"p10971","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 1:27","sort_key":"2015-04-03 01:27:00","excerpt":"9634: me \"Ну… Я не знаю.\" Я думаю, здесь всё-так mi."},{"doc_id":3230,"url":"../t12p75-topic.html#p10972","post_id":"p10972","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Пт 3 Апр 2015 - 1:39","sort_key":"2015-04-03 01:39:00","excerpt":"\"Нэ так это было, совсэм нэ так…\" Собссно, что мешает отмотать назад и отдать бритву Алисе??? В этом-то и прелесть ветвления сюжета, что каждый может (если захочет и сможет), обрести подходящую цепь событий. Лично я…"},{"doc_id":3231,"url":"../t12p75-topic.html#p10973","post_id":"p10973","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 1:42","sort_key":"2015-04-03 01:42:00","excerpt":"> Собссно, что мешает отмотать назад и отдать бритву Алисе??? Ничего. Отмотаю, отдам и посмотрю, что будет. Но сюжет в любом ветвлении должен быть правильным. Я эту историю не воспринимаю как \"есть настоящий сюжет, а…"},{"doc_id":3232,"url":"../t12p75-topic.html#p10974","post_id":"p10974","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 1:43","sort_key":"2015-04-03 01:43:00","excerpt":"> Здесь просто одна боль на двоих. Я циник. И прагматик. И ещё раз циник. И я вижу не \"боль на двоих\", а я вижу проблему, которую надо решать. И которую я же (герой) создал."},{"doc_id":3233,"url":"../t12p75-topic.html#p10975","post_id":"p10975","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Ленивый бегун","posted_at":"Пт 3 Апр 2015 - 1:45","sort_key":"2015-04-03 01:45:00","excerpt":"Ну я вот свой красивый и честный выбрал, чего и всем остальным желаю. Повторюсь, в том-то и прелесть, что все ветки разные - каждому своё. Кто-то предпочтёт Лена-рут, кто-то - Мику или Алису. Кто-то спасёт Лену, кто-то…"},{"doc_id":3234,"url":"../t12p75-topic.html#p10976","post_id":"p10976","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 1:49","sort_key":"2015-04-03 01:49:00","excerpt":"В оригинале мой любимый сюжет - Алиса. Именно сюжет. Он наиболее... живой. А здесь - посмотрим. Ждать осталось, как говорится..."},{"doc_id":3235,"url":"../t12p75-topic.html#p10978","post_id":"p10978","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 3 Апр 2015 - 1:59","sort_key":"2015-04-03 01:59:00","excerpt":"Плюсую Бегуна, сцена сильная, ни к чему ее трогать. Тем более что трактовать ее можно по-разному, что наглядно демонстрируется выше. Разве что подтверждалку намерений можно поставить непосредственно перед, а то немного…"},{"doc_id":3236,"url":"../t12p75-topic.html#p10993","post_id":"p10993","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 11:28","sort_key":"2015-04-03 11:28:00","excerpt":"Вариант без бритвы оказался куда лучше. Я не против, манипуляция так манипуляция, совершенно не понимаю, почему бы благородному дону Семёну не манипулировать, я просто просил добавить пару комментариев для прояснения…"},{"doc_id":3237,"url":"../t12p75-topic.html#p10994","post_id":"p10994","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"7dl-kun","posted_at":"Пт 3 Апр 2015 - 12:06","sort_key":"2015-04-03 12:06:00","excerpt":"Не буду я бритву править. Если камрады с СПГС видят там какие-то попытки манипуляции - пускай. А я писал эту сценку как вполне себе логичное продолжение сумасбродного дня. Все эти прыжки, отмороженность Мику, всплывшее…"},{"doc_id":3238,"url":"../t12p75-topic.html#p10995","post_id":"p10995","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 13:09","sort_key":"2015-04-03 13:09:00","excerpt":"Блин. Когда ночью перепроходил, ежа скипнул. А интересная ветка, оказывается, завязана на ежа..."},{"doc_id":3239,"url":"../t12p75-topic.html#p10997","post_id":"p10997","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Гость","posted_at":"Пт 3 Апр 2015 - 15:27","sort_key":"2015-04-03 15:27:00","excerpt":"О каком еже идет речь?"},{"doc_id":3240,"url":"../t12p75-topic.html#p10998","post_id":"p10998","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Пт 3 Апр 2015 - 15:37","sort_key":"2015-04-03 15:37:00","excerpt":"Помоги девочке ночью, когда она к тебе прибегает."},{"doc_id":3241,"url":"../t12p75-topic.html#p10999","post_id":"p10999","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Arlien","posted_at":"Пт 3 Апр 2015 - 16:06","sort_key":"2015-04-03 16:06:00","excerpt":"Гхых, смотрю, товарищ автор сделал выбор небезальтернативным очень удачно :Д"},{"doc_id":3242,"url":"../t12p75-topic.html#p11000","post_id":"p11000","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"Элдхэнн","posted_at":"Пт 3 Апр 2015 - 16:15","sort_key":"2015-04-03 16:15:00","excerpt":"Ветвление вообще очень удачно сделано, мне очень понравилось. Много разных подветок, подвыборов, эвентов, связанных с выборами, но не влияющих напрямую на результат."},{"doc_id":3243,"url":"../t12p75-topic.html#p11271","post_id":"p11271","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"epicfailman","posted_at":"Чт 16 Апр 2015 - 1:34","sort_key":"2015-04-16 01:34:00","excerpt":"Ребят подскажите. Версия последняя, сделал всё по схеме уже, после танцев ночная поимка ежа, потом уборка в клубе, переодевание в чистое, разговор со Славей. Потом идёт описание того что случится, кидает на начало 5 дня…"},{"doc_id":3244,"url":"../t12p75-topic.html#p11272","post_id":"p11272","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Чт 16 Апр 2015 - 2:02","sort_key":"2015-04-16 02:02:00","excerpt":"Точно последнюю версию скачал и поставил?"},{"doc_id":3245,"url":"../t12p75-topic.html#p11273","post_id":"p11273","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"epicfailman","posted_at":"Чт 16 Апр 2015 - 2:06","sort_key":"2015-04-16 02:06:00","excerpt":"Да. Изначально вытащил сборку с вики по magnet-ссылке. Потом когда столкнулся с проблемой, скачал уже из раздела с новыми версиями. Старую папку scenario_alt удалил от греха подальше, установил новую. Влепил хотфикс…"},{"doc_id":3246,"url":"../t12p75-topic.html#p11274","post_id":"p11274","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Чт 16 Апр 2015 - 2:12","sort_key":"2015-04-16 02:12:00","excerpt":"Ну вот даже хз, чем помочь. БЛ 1.1 + модпак + мод версии 0.16b - все ок."},{"doc_id":3247,"url":"../t12p75-topic.html#p11275","post_id":"p11275","topic_title":"Мику - DJ -рут","forum_title":"Мику","author":"peregarrett","posted_at":"Чт 16 Апр 2015 - 2:18","sort_key":"2015-04-16 02:18:00","excerpt":"Поиск по фразе \"кто сделал Мику диджеем\" ничег оне нашел. Сдается мне, у тебя все-таки старая версия, где Мику-ДЖ недопилен."},{"doc_id":3248,"url":"../t13-topic.html#p13","post_id":"p13","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Admin","posted_at":"Вс 7 Сен 2014 - 15:15","sort_key":"2014-09-07 15:15:00","excerpt":"Сценарий от разработчика 7дл"},{"doc_id":3249,"url":"../t13-topic.html#p1452","post_id":"p1452","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Чт 25 Сен 2014 - 11:31","sort_key":"2014-09-25 11:31:00","excerpt":"В отличие от других девочек (мику не в счёт, её сценарий пока предмет размышлений), сценарий Слави получает жёсткое ответвление только после второго танца - при наличии выполненных квестов за утро и за тихий час."},{"doc_id":3250,"url":"../t13-topic.html#p1453","post_id":"p1453","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Ingvar","posted_at":"Чт 25 Сен 2014 - 16:59","sort_key":"2014-09-25 16:59:00","excerpt":"Хорошо, главное теперь сам этот рут увидеть."},{"doc_id":3251,"url":"../t13-topic.html#p1454","post_id":"p1454","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Чт 25 Сен 2014 - 17:11","sort_key":"2014-09-25 17:11:00","excerpt":"А вы таки за него сели?) В следующей обнове ждать?)"},{"doc_id":3252,"url":"../t13-topic.html#p1455","post_id":"p1455","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Чт 25 Сен 2014 - 17:27","sort_key":"2014-09-25 17:27:00","excerpt":"Я таки его пишу уже четвёртый день (= К сожалению, скорость по независящим от меня обстоятельствам, несколько упала, поэтому в пятницу не выкачу, скорее всего, в субботу или утром воскресенья."},{"doc_id":3253,"url":"../t13-topic.html#p1456","post_id":"p1456","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Чт 25 Сен 2014 - 17:43","sort_key":"2014-09-25 17:43:00","excerpt":"Та скорость не беда, вы по-прежнему самый быстрый разработчик БЛ в обозримой вселенной :Д"},{"doc_id":3254,"url":"../t13-topic.html#p1457","post_id":"p1457","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Demiurge-kun","posted_at":"Чт 25 Сен 2014 - 18:40","sort_key":"2014-09-25 18:40:00","excerpt":"Когда видишь как господа из кучки команд, мини-фиков, и прочей лабуды собирают вундервафлю, понимаешь, какой однако титанический труд. Даже грустно немного от того, что меняются направления сюжета, меняются действия, все…"},{"doc_id":3255,"url":"../t13-topic.html#p1503","post_id":"p1503","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Пн 29 Сен 2014 - 23:57","sort_key":"2014-09-29 23:57:00","excerpt":"Собсна, фидбек по четвертому дню от 0.7А. Не по форме. Большую часть очередной простыни съела самоцензура, так что отмечу только образцово выполненный как минимум с хужожественной точки зрения транзит. Инженерную часть…"},{"doc_id":3256,"url":"../t13-topic.html#p1520","post_id":"p1520","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Вт 30 Сен 2014 - 0:32","sort_key":"2014-09-30 00:32:00","excerpt":"Не совсем понял про лабуду и мини-фики, но за позитивчик спасибо. Держит в тонусе не хуже пометок на полях от товарищей Драго и Перегарретта. Вот! Этого и хотел. Сюжетный обоснуй... Правда, он длиной всего в сутки, но…"},{"doc_id":3257,"url":"../t13-topic.html#p1528","post_id":"p1528","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Вт 30 Сен 2014 - 0:41","sort_key":"2014-09-30 00:41:00","excerpt":"Ну для истории длиной всего в четверо суток этого вполне достаточно, кмк. Я, кстати, правильно догадался, что лейбмотивом четвертого дня Славяны стал \"Wicked man\"?"},{"doc_id":3258,"url":"../t13-topic.html#p1535","post_id":"p1535","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Вт 30 Сен 2014 - 0:51","sort_key":"2014-09-30 00:51:00","excerpt":"Если бы я ещё знал, что это такое... (="},{"doc_id":3259,"url":"../t13-topic.html#p1551","post_id":"p1551","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Вт 30 Сен 2014 - 1:26","sort_key":"2014-09-30 01:26:00","excerpt":"Ну через 7ДЛ Мику-рут, к примеру, \"Достучаться до небес\" идет, в Алисоруте, если я ничего не путаю, периодические отсылки к Паланику, а тут вот... Триллер такой старенький, не так давно римейкали его. \"Плетеный человек\"…"},{"doc_id":3260,"url":"../t13-topic.html#p1554","post_id":"p1554","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Вт 30 Сен 2014 - 1:34","sort_key":"2014-09-30 01:34:00","excerpt":"Не смотрел. Но если про расчётливых блондинок - обязательно ознакомлюсь (="},{"doc_id":3261,"url":"../t13-topic.html#p1571","post_id":"p1571","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"peregarrett","posted_at":"Вт 30 Сен 2014 - 2:22","sort_key":"2014-09-30 02:22:00","excerpt":"Ох елки-палки. Дочитал. Охренел. Кто тут еще будет заикаться про ламповость и дыньки, а?! Автор, ждем следующий день!"},{"doc_id":3262,"url":"../t13-topic.html#p1575","post_id":"p1575","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Ingvar","posted_at":"Вт 30 Сен 2014 - 4:08","sort_key":"2014-09-30 04:08:00","excerpt":"Пока не смог пройти обход, но одну опечатку уже нашел Спойлер:"},{"doc_id":3263,"url":"../t13-topic.html#p1577","post_id":"p1577","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Вт 30 Сен 2014 - 11:58","sort_key":"2014-09-30 11:58:00","excerpt":"Не трогать деук! Это святое!"},{"doc_id":3264,"url":"../t13-topic.html#p1588","post_id":"p1588","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"peregarrett","posted_at":"Ср 1 Окт 2014 - 0:02","sort_key":"2014-10-01 00:02:00","excerpt":"Хм. Новая ламповая версия - шатковата, по сравнению с предыдущей. Во-первых, много где по тексту упоминается что Славя - родом из деревни, и тут внезапно - мама-хирург Раиса Францевна, мезальянс, помолвка... Это вообще…"},{"doc_id":3265,"url":"../t13-topic.html#p1590","post_id":"p1590","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Гость","posted_at":"Ср 1 Окт 2014 - 0:15","sort_key":"2014-10-01 00:15:00","excerpt":"Прошлый вариант по разряду абсурда по той банальной причине, что будь такая традиция в какой-то там деревне, и не было бы никакой умницы и красавицы Слави, а была бы тупая колхозная корова. Сами подумайте, если раз за…"},{"doc_id":3266,"url":"../t13-topic.html#p1591","post_id":"p1591","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Ср 1 Окт 2014 - 0:23","sort_key":"2014-10-01 00:23:00","excerpt":"Да нормально, внутри новеллы можно всё, если это сквозь жирок достать может. Я от прошлой версии отказался потому что камрады из обсуждения и так чернухи навели, незачем чернить сверх того. Ну и в с целью вывода именно…"},{"doc_id":3267,"url":"../t13-topic.html#p1592","post_id":"p1592","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Arlien","posted_at":"Ср 1 Окт 2014 - 0:25","sort_key":"2014-10-01 00:25:00","excerpt":"А на мой вкус, что то, шо это... Хрен редьки не слаще. В начальном варианте-то хоть 'специфичное' поведение можно было списать на издержки деревенского воспитания, а во втором уже как бы без особых вариантов, плюс…"},{"doc_id":3268,"url":"../t13-topic.html#p1596","post_id":"p1596","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Radkar","posted_at":"Ср 1 Окт 2014 - 0:55","sort_key":"2014-10-01 00:55:00","excerpt":"Ахх, автор, что ж ты творишь, мне предыдущий вариант больше нравился. :/ Теперь сюжет стал логичнее (здесь соглашусь с drago23; кроме его доводов - ну кто в Семёне партию разглядит, да еще так быстро?!), но банальнее…"},{"doc_id":3269,"url":"../t13-topic.html#p1601","post_id":"p1601","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"7dl-kun","posted_at":"Ср 1 Окт 2014 - 1:08","sort_key":"2014-10-01 01:08:00","excerpt":"Все ведь от отношения к персонажу зависит. Желание избавиться от навязываемой родителями обузы, например, можно разглядеть без проблем. Славя не в восторге от того, что ей давали, но, не имея вменяемой альтернативы…"},{"doc_id":3270,"url":"../t13-topic.html#p1604","post_id":"p1604","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"peregarrett","posted_at":"Ср 1 Окт 2014 - 1:13","sort_key":"2014-10-01 01:13:00","excerpt":"При условии, что местный партком полностью состоит из своих людей - никакого хая. Во всяких там среднеазиатских республиках и в тру-советские времена вполне в порядке вещей были всякие вторые и третьи жены, похищение…"},{"doc_id":3271,"url":"../t13-topic.html#p1617","post_id":"p1617","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Гость","posted_at":"Ср 1 Окт 2014 - 1:31","sort_key":"2014-10-01 01:31:00","excerpt":"Вы определитесь уж, Славя - деревенщина, или свои люди в парткоме. Что такое северная деревня, я знаю. Мой дед с материнской стороны - коми по национальности. До 14 лет по-русски не говорил. В таёжных деревушках всё ещё…"},{"doc_id":3272,"url":"../t13-topic.html#p1619","post_id":"p1619","topic_title":"Славя - 7дл - рут","forum_title":"Славя","author":"Radkar","posted_at":"Ср 1 Окт 2014 - 1:39","sort_key":"2014-10-01 01:39:00","excerpt":"Тогда всё же больше негатива в адрес Василия хотелось бы. А то \"есть в моей жизни\", \"с детства дружим\" - будто на двух стульях пытается усидеть. Ну и можно было от помолвки отказаться, здесь я с вашим же Семёном…"},{"doc_id":3273,"url":"../t130-topic.html#p17225","post_id":"p17225","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:35","sort_key":"2015-09-05 22:35:00","excerpt":"Учитывая, как пастофарианство легко зашло, продвинуть кошку в религию - не проблема, аудитория есть, поддержка есть, верования есть, всё сходится."},{"doc_id":3274,"url":"../t130-topic.html#p17226","post_id":"p17226","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:36","sort_key":"2015-09-05 22:36:00","excerpt":"Юливианство? Или Кошлам?"},{"doc_id":3275,"url":"../t130-topic.html#p17227","post_id":"p17227","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 5 Сен 2015 - 22:37","sort_key":"2015-09-05 22:37:00","excerpt":"Котоличество"},{"doc_id":3276,"url":"../t130-topic.html#p17228","post_id":"p17228","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:38","sort_key":"2015-09-05 22:38:00","excerpt":"О! Звучит, так и запишем."},{"doc_id":3277,"url":"../t130-topic.html#p17229","post_id":"p17229","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:39","sort_key":"2015-09-05 22:39:00","excerpt":"Это название зарезервированно для одной из ересей, не путай людей."},{"doc_id":3278,"url":"../t130-topic.html#p17230","post_id":"p17230","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 5 Сен 2015 - 22:40","sort_key":"2015-09-05 22:40:00","excerpt":"Про мертвого кота-мага, который спит в мавзолее? И когда проснется, начнется Закопалипсис?"},{"doc_id":3279,"url":"../t130-topic.html#p17231","post_id":"p17231","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:41","sort_key":"2015-09-05 22:41:00","excerpt":"Угу, это начинает быть крайне интересно, он случайно луну в розовый не красил?"},{"doc_id":3280,"url":"../t130-topic.html#p17232","post_id":"p17232","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 5 Сен 2015 - 22:41","sort_key":"2015-09-05 22:41:00","excerpt":"Акоталипсис же."},{"doc_id":3281,"url":"../t130-topic.html#p17233","post_id":"p17233","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:43","sort_key":"2015-09-05 22:43:00","excerpt":"Тащ Автор, вы не вкурсе, вот и не смущайте народ. Котокалипсис с котоклизмой путаете, а ещё моды пишете!"},{"doc_id":3282,"url":"../t130-topic.html#p17234","post_id":"p17234","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 5 Сен 2015 - 22:43","sort_key":"2015-09-05 22:43:00","excerpt":"Нет, именно Закопалипсис. Кот проснется, понюхает то, во что превратился мир - и закопает его от греха."},{"doc_id":3283,"url":"../t130-topic.html#p17235","post_id":"p17235","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:46","sort_key":"2015-09-05 22:46:00","excerpt":"Ага, понял, схожу в подсобку за морфием, глядишь и яснее всё станет."},{"doc_id":3284,"url":"../t130-topic.html#p17236","post_id":"p17236","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 5 Сен 2015 - 22:46","sort_key":"2015-09-05 22:46:00","excerpt":"И керосину там же хлебни."},{"doc_id":3285,"url":"../t130-topic.html#p17237","post_id":"p17237","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:47","sort_key":"2015-09-05 22:47:00","excerpt":"Боюсь, что даже морфий с керосином не дадут полной картины упадка цивилизации."},{"doc_id":3286,"url":"../t130-topic.html#p17238","post_id":"p17238","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 5 Сен 2015 - 22:48","sort_key":"2015-09-05 22:48:00","excerpt":"Эфир?"},{"doc_id":3287,"url":"../t130-topic.html#p17239","post_id":"p17239","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:49","sort_key":"2015-09-05 22:49:00","excerpt":"Он не вкусный("},{"doc_id":3288,"url":"../t130-topic.html#p17240","post_id":"p17240","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:50","sort_key":"2015-09-05 22:50:00","excerpt":"Мне бы базис кошки для начала потянуть, а до упадка не так важно, лучше дальше буду в свои альтруистичные забвения ударяться."},{"doc_id":3289,"url":"../t130-topic.html#p17241","post_id":"p17241","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:52","sort_key":"2015-09-05 22:52:00","excerpt":"Ишь, куда замахнулсо! Даже я, творец баббла рута, до сих пор не постиг всей мощи кошочки! Как пропадают люди, причастные к руту, видел, но границ не ведаю. Оглянись. На тебя кот не смотрит многозначительно?"},{"doc_id":3290,"url":"../t130-topic.html#p17242","post_id":"p17242","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:54","sort_key":"2015-09-05 22:54:00","excerpt":"Я даже специально пошёл и отыскал своего кота, в его глазах была печаль."},{"doc_id":3291,"url":"../t130-topic.html#p17243","post_id":"p17243","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 22:57","sort_key":"2015-09-05 22:57:00","excerpt":"Это тоска по твоей неизбежной скорой смерти и мысли о том, кто же его будет кормить. Не жалей еды коту, возможно, он отвлечёт кошочку."},{"doc_id":3292,"url":"../t130-topic.html#p17244","post_id":"p17244","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Surv","posted_at":"Сб 5 Сен 2015 - 22:58","sort_key":"2015-09-05 22:58:00","excerpt":"Не мог не заметить что в каждой теме есть разговоры про котов"},{"doc_id":3293,"url":"../t130-topic.html#p17245","post_id":"p17245","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 22:59","sort_key":"2015-09-05 22:59:00","excerpt":"Ага, то есть за мной уже выехали, прискорбно, это как неведомое клеймо и проклятье тьмы у Лавкрафта, от которого нельзя убежать?"},{"doc_id":3294,"url":"../t130-topic.html#p17246","post_id":"p17246","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 23:00","sort_key":"2015-09-05 23:00:00","excerpt":""},{"doc_id":3295,"url":"../t130-topic.html#p17247","post_id":"p17247","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 23:04","sort_key":"2015-09-05 23:04:00","excerpt":"Ну при чём тут какой-то самозванец? Культ кота ведёт историю минимум с Древнего Египта. Думаешь, просто так всё?"},{"doc_id":3296,"url":"../t130-topic.html#p17248","post_id":"p17248","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 23:06","sort_key":"2015-09-05 23:06:00","excerpt":"Ну почему же сразу самозванец, пересказчик, не более, Йог Шоггот тоже парень весьма старый и обаятельный )"},{"doc_id":3297,"url":"../t130-topic.html#p17249","post_id":"p17249","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 5 Сен 2015 - 23:09","sort_key":"2015-09-05 23:09:00","excerpt":"Тащемта именно Говард Лавкрафт его и придумал. Как и разумные грыбы с пояса Койпера, и \"Некрономикон\". А кошочек все культуры издревле отмечали отдельно. Или обожествляли, или конкретно ненавидели."},{"doc_id":3298,"url":"../t130p100-topic.html#p17427","post_id":"p17427","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 20:30","sort_key":"2015-09-11 20:30:00","excerpt":"Безалкогольной водки с ароматизатором сивушных масел?"},{"doc_id":3299,"url":"../t130p100-topic.html#p17428","post_id":"p17428","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 20:40","sort_key":"2015-09-11 20:40:00","excerpt":"Ну я тя умоляю... Проводить день трезвости в пятницу - это по меньшей мере наивно."},{"doc_id":3300,"url":"../t130p100-topic.html#p17429","post_id":"p17429","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 20:43","sort_key":"2015-09-11 20:43:00","excerpt":"Пошёл тогда в магазин."},{"doc_id":3301,"url":"../t130p100-topic.html#p17430","post_id":"p17430","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Пт 11 Сен 2015 - 20:43","sort_key":"2015-09-11 20:43:00","excerpt":"Еще рано! Обнова скоро же."},{"doc_id":3302,"url":"../t130p100-topic.html#p17431","post_id":"p17431","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 20:46","sort_key":"2015-09-11 20:46:00","excerpt":"Ну вот как раз повысить уровень сентиментальности перед чтением! Ну прямо всё один к одному."},{"doc_id":3303,"url":"../t130p100-topic.html#p17432","post_id":"p17432","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 20:47","sort_key":"2015-09-11 20:47:00","excerpt":"А все уже будут поддатыми, умиротворёнными. И ни один товарищ Ч. и товарищ А. (к примеру) не устроят эн-надцатую Пуническую битву."},{"doc_id":3304,"url":"../t130p100-topic.html#p17433","post_id":"p17433","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 20:51","sort_key":"2015-09-11 20:51:00","excerpt":"Товарищ Ч. сегодня на редкость благодушен, так что битва обязательно будет. В конце концов, зачем ещё в итнернеты ходить?"},{"doc_id":3305,"url":"../t130p100-topic.html#p17434","post_id":"p17434","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 20:55","sort_key":"2015-09-11 20:55:00","excerpt":"Интересная какая психическая организация. Благодушие, скорее, располагает к неспешной беседе, вальяжно сядете, чокнетесь несколько тостов."},{"doc_id":3306,"url":"../t130p100-topic.html#p17435","post_id":"p17435","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Пт 11 Сен 2015 - 20:55","sort_key":"2015-09-11 20:55:00","excerpt":"Не, сначала очепятки, сентиментальность потом. А шобы искать очепятки, нужно глаз как у собаки и нюх как у орла."},{"doc_id":3307,"url":"../t130p100-topic.html#p17436","post_id":"p17436","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 11 Сен 2015 - 20:55","sort_key":"2015-09-11 20:55:00","excerpt":"Шел непонятно какой день написания рута Слави. В код ушли 1600 строчек сырого сценария. Впереди ещё 2200. Скоро? Спойлер:"},{"doc_id":3308,"url":"../t130p100-topic.html#p17437","post_id":"p17437","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:02","sort_key":"2015-09-11 21:02:00","excerpt":"В который раз замечаю у некоторых тащей болезненную страсть к выдаванию желаемого за действительное. Это \"ж-ж-ж\" неспроста, как мне кажется, и свидетельствует о какой-то поведенческой аберрации. Нет, я, разумеется, не…"},{"doc_id":3309,"url":"../t130p100-topic.html#p17439","post_id":"p17439","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Пт 11 Сен 2015 - 21:06","sort_key":"2015-09-11 21:06:00","excerpt":"Ну по меркам других модов - еще как скоро!"},{"doc_id":3310,"url":"../t130p100-topic.html#p17440","post_id":"p17440","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:37","sort_key":"2015-09-11 21:37:00","excerpt":"День сегодня богат на памятные даты, тащемта"},{"doc_id":3311,"url":"../t130p100-topic.html#p17441","post_id":"p17441","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:39","sort_key":"2015-09-11 21:39:00","excerpt":"Это ты об \"Airplains win\"? Грандиозный развод всего мира. Даже \"высадку на Луну\" по эпичности превосходит."},{"doc_id":3312,"url":"../t130p100-topic.html#p17442","post_id":"p17442","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:40","sort_key":"2015-09-11 21:40:00","excerpt":"Не, у меня личный праздник. У дочки др"},{"doc_id":3313,"url":"../t130p100-topic.html#p17443","post_id":"p17443","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:41","sort_key":"2015-09-11 21:41:00","excerpt":"Типа, не было никаких башен-близнецов, да и вообще никакой Америки нет?"},{"doc_id":3314,"url":"../t130p100-topic.html#p17444","post_id":"p17444","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:41","sort_key":"2015-09-11 21:41:00","excerpt":"Удачно как, до понедельника отмечать можно."},{"doc_id":3315,"url":"../t130p100-topic.html#p17445","post_id":"p17445","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:42","sort_key":"2015-09-11 21:42:00","excerpt":"Нет, я про террористов, вооружённых канцелярскими ножами и падение башен."},{"doc_id":3316,"url":"../t130p100-topic.html#p17446","post_id":"p17446","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:42","sort_key":"2015-09-11 21:42:00","excerpt":"Лол, сразу видно бездетного человека. Отмечать можно, а вот отдохнуть не выйдет"},{"doc_id":3317,"url":"../t130p100-topic.html#p17447","post_id":"p17447","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:44","sort_key":"2015-09-11 21:44:00","excerpt":"Да нет, вполне представляю, что там у тебя творится. Удивлён, что ты в инете время находишь сидеть."},{"doc_id":3318,"url":"../t130p100-topic.html#p17448","post_id":"p17448","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:46","sort_key":"2015-09-11 21:46:00","excerpt":"Места надо знать."},{"doc_id":3319,"url":"../t130p100-topic.html#p17449","post_id":"p17449","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 21:49","sort_key":"2015-09-11 21:49:00","excerpt":"В сортире заперся?"},{"doc_id":3320,"url":"../t130p100-topic.html#p17450","post_id":"p17450","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 21:51","sort_key":"2015-09-11 21:51:00","excerpt":"Ты знал!"},{"doc_id":3321,"url":"../t130p100-topic.html#p17451","post_id":"p17451","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 21:54","sort_key":"2015-09-11 21:54:00","excerpt":"Если уже, или всё ещё, в прятки можно играть, пусть дети прячутся, а ты ищи. Долго-о-о так."},{"doc_id":3322,"url":"../t130p100-topic.html#p17452","post_id":"p17452","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 22:33","sort_key":"2015-09-11 22:33:00","excerpt":"Хм, как обычно я пропустил всё самое интересное, ну да ладно. Перегарыч, поздравляю, это тоже твой праздник. Хотя туалет -крепость крестоносцев это что-то новенькое."},{"doc_id":3323,"url":"../t130p125-topic.html#p17453","post_id":"p17453","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:42","sort_key":"2015-09-11 22:42:00","excerpt":"Очень даже старенькое. Где ещё можно самозаточиться с твёрдым приказом не беспокоить? З.Ы. Та-а-ак, кажется, я виолизмы подхватил..."},{"doc_id":3324,"url":"../t130p125-topic.html#p17454","post_id":"p17454","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 22:46","sort_key":"2015-09-11 22:46:00","excerpt":"В древнем архиве.) Да, видно, судя по контексту, тоже в хентай мастера уйдешь?)"},{"doc_id":3325,"url":"../t130p125-topic.html#p17455","post_id":"p17455","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 22:47","sort_key":"2015-09-11 22:47:00","excerpt":"Организм, ослабленный никотином, алкоголем..."},{"doc_id":3326,"url":"../t130p125-topic.html#p17456","post_id":"p17456","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 22:48","sort_key":"2015-09-11 22:48:00","excerpt":"...ведёт тебя в глубины твоего сознания?"},{"doc_id":3327,"url":"../t130p125-topic.html#p17457","post_id":"p17457","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:48","sort_key":"2015-09-11 22:48:00","excerpt":"Нет, я отношусь к мастерам логики, устного творчества и коротких реприз. Иначе рут давно уже дописан был бы и пугал вас порциями контролируемого безумия."},{"doc_id":3328,"url":"../t130p125-topic.html#p17458","post_id":"p17458","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 22:52","sort_key":"2015-09-11 22:52:00","excerpt":"Ну, надеюсь оно неконтролируемое)"},{"doc_id":3329,"url":"../t130p125-topic.html#p17459","post_id":"p17459","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 22:53","sort_key":"2015-09-11 22:53:00","excerpt":"В.Ц. Коллайдер, \"Особые процедуры\". Сборник жизненных историй."},{"doc_id":3330,"url":"../t130p125-topic.html#p17460","post_id":"p17460","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:53","sort_key":"2015-09-11 22:53:00","excerpt":"Оу, очепятался. Кот ролируемого, конечно же."},{"doc_id":3331,"url":"../t130p125-topic.html#p17461","post_id":"p17461","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:54","sort_key":"2015-09-11 22:54:00","excerpt":"-...В рот не хочет, в попу больно, говорит. - Так бы и сказали, что ни таблетки, ни уколы не подходят."},{"doc_id":3332,"url":"../t130p125-topic.html#p17462","post_id":"p17462","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 22:54","sort_key":"2015-09-11 22:54:00","excerpt":"\"Кошкорут будет дописан - правда или вымысел\". п.к.н. Чесс P.S. профессор кошкорутонаписательных наук"},{"doc_id":3333,"url":"../t130p125-topic.html#p17463","post_id":"p17463","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:56","sort_key":"2015-09-11 22:56:00","excerpt":"Пишу-то рут не я. Я его всего лишь придумал."},{"doc_id":3334,"url":"../t130p125-topic.html#p17464","post_id":"p17464","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 22:57","sort_key":"2015-09-11 22:57:00","excerpt":"Говард будет доволен?)"},{"doc_id":3335,"url":"../t130p125-topic.html#p17465","post_id":"p17465","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 22:58","sort_key":"2015-09-11 22:58:00","excerpt":"Це хто?"},{"doc_id":3336,"url":"../t130p125-topic.html#p17466","post_id":"p17466","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:00","sort_key":"2015-09-11 23:00:00","excerpt":"А если не секрет Чесс, 6-й день есть?"},{"doc_id":3337,"url":"../t130p125-topic.html#p17467","post_id":"p17467","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:01","sort_key":"2015-09-11 23:01:00","excerpt":"Дядя знает не по наслышке, что такое безумие)"},{"doc_id":3338,"url":"../t130p125-topic.html#p17468","post_id":"p17468","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:02","sort_key":"2015-09-11 23:02:00","excerpt":"Есть. В виде баббла. И большей части текстов."},{"doc_id":3339,"url":"../t130p125-topic.html#p17469","post_id":"p17469","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 11 Сен 2015 - 23:04","sort_key":"2015-09-11 23:04:00","excerpt":"Прокрастинаторы прокрастинировали, прокрастинировали да не выпрокрастинировали."},{"doc_id":3340,"url":"../t130p125-topic.html#p17470","post_id":"p17470","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:04","sort_key":"2015-09-11 23:04:00","excerpt":"А-а-а, вон который! Не, у нас не примитив вековой давности, не пионерские страшилки. Ма-а-аленький намёк - непонятная мотивация пугает куда сильнее."},{"doc_id":3341,"url":"../t130p125-topic.html#p17471","post_id":"p17471","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:05","sort_key":"2015-09-11 23:05:00","excerpt":"Кхм. Кто бы говорил, позволю себе заметить. Вы, кстати, какие напитки предпочитаете?"},{"doc_id":3342,"url":"../t130p125-topic.html#p17472","post_id":"p17472","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:05","sort_key":"2015-09-11 23:05:00","excerpt":"Что такое хороший фильм ужасов? По лесной полянке весело бежит ёжик, а ты обделываешься со страха."},{"doc_id":3343,"url":"../t130p125-topic.html#p17473","post_id":"p17473","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:08","sort_key":"2015-09-11 23:08:00","excerpt":"Эх, пионерские страшилки - святое дело! До сих пор на полке есть собрание страшилок Эдуарда Успенского, классная вещь! А так - Говарда всегда можно связать с бункером, да и хоррора нагнать про гроб на колёсиках всегда к…"},{"doc_id":3344,"url":"../t130p125-topic.html#p17474","post_id":"p17474","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:09","sort_key":"2015-09-11 23:09:00","excerpt":"Там на детей ядрёная бомба плавно спускается, какой к чертям гроб."},{"doc_id":3345,"url":"../t130p125-topic.html#p17475","post_id":"p17475","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:10","sort_key":"2015-09-11 23:10:00","excerpt":"Ну, бомба - это не ламопово, не атмосферно как-то. Так и запишем."},{"doc_id":3346,"url":"../t130p125-topic.html#p17476","post_id":"p17476","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:11","sort_key":"2015-09-11 23:11:00","excerpt":"Ну это же мелко унд низкопошибно, тащ. Ящетаю, что лучше держать в состоянии обалдевания до лёгкой степени дебилизма до прохождения всех основных сюжетных цепочек рута."},{"doc_id":3347,"url":"../t130p125-topic.html#p17477","post_id":"p17477","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:13","sort_key":"2015-09-11 23:13:00","excerpt":"И на выходе из лабиринта, окажемся на входе следующего."},{"doc_id":3348,"url":"../t130p150-topic.html#p17478","post_id":"p17478","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:13","sort_key":"2015-09-11 23:13:00","excerpt":"А что не так? Свет есть? Да сколько угодно! Тёплый? Тёплый! Что не так?"},{"doc_id":3349,"url":"../t130p150-topic.html#p17479","post_id":"p17479","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:14","sort_key":"2015-09-11 23:14:00","excerpt":"Не, про Говарда - шутка. Если такой концепт по эмпирии в руте будет - я только больше за. Чтобы всё прохождения сидеть с раскрытой челюстью, выставленной к экрану руку и полным непонимание происходяшего в стиле: ЧТО…"},{"doc_id":3350,"url":"../t130p150-topic.html#p17480","post_id":"p17480","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 11 Сен 2015 - 23:15","sort_key":"2015-09-11 23:15:00","excerpt":"Я бы говорил, я! У меня только постановка осталась, где-то 1850 строк. Абсент наше всё."},{"doc_id":3351,"url":"../t130p150-topic.html#p17481","post_id":"p17481","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:16","sort_key":"2015-09-11 23:16:00","excerpt":"Этого будет сколько угодно."},{"doc_id":3352,"url":"../t130p150-topic.html#p17482","post_id":"p17482","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:17","sort_key":"2015-09-11 23:17:00","excerpt":"Абсент - классический? Или раствор современный, с массовой долей сколько-то процентов."},{"doc_id":3353,"url":"../t130p150-topic.html#p17483","post_id":"p17483","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:18","sort_key":"2015-09-11 23:18:00","excerpt":"Тогда буду с радостью потирать ладошки, а учитывая, что Перегарыч-сама отвечает за эротический контент, тереть ладони об друг друга буду довольно сильно. (Плоская шутка- прибаутка)"},{"doc_id":3354,"url":"../t130p150-topic.html#p17484","post_id":"p17484","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:19","sort_key":"2015-09-11 23:19:00","excerpt":"Вы, тащ Автор, не сравнивайте! Вы там один пишете, а мне приходится десяток душ пинать! К сожалению, виртуально... Абсент, говорите... Вот теперь понятны некоторые моменты некоторых рутов. И это я, заметьте, ещё Алисочки…"},{"doc_id":3355,"url":"../t130p150-topic.html#p17485","post_id":"p17485","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:20","sort_key":"2015-09-11 23:20:00","excerpt":"Опять меня склоняют. Эротический контент им подавай..."},{"doc_id":3356,"url":"../t130p150-topic.html#p17486","post_id":"p17486","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:20","sort_key":"2015-09-11 23:20:00","excerpt":"Разочарую - групповухи не предвидится. Автор запретил."},{"doc_id":3357,"url":"../t130p150-topic.html#p17487","post_id":"p17487","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 11 Сен 2015 - 23:21","sort_key":"2015-09-11 23:21:00","excerpt":"Угу, где здесь классический-то купишь? Раньше в одном месте наливали, но закрыли. Сейчас в тёмном стоят несколько литров по рецепту, но это до НГ."},{"doc_id":3358,"url":"../t130p150-topic.html#p17488","post_id":"p17488","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:23","sort_key":"2015-09-11 23:23:00","excerpt":"Главное - мыло не ронять. Извиняюсь, если чем-то обидел."},{"doc_id":3359,"url":"../t130p150-topic.html#p17489","post_id":"p17489","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:23","sort_key":"2015-09-11 23:23:00","excerpt":"В принципе, вполне может и произойдёт как с любым мало-мальским известным фильмом, рано или поздно появляется версия, где все друг-друга любят, но не женятся."},{"doc_id":3360,"url":"../t130p150-topic.html#p17490","post_id":"p17490","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:23","sort_key":"2015-09-11 23:23:00","excerpt":"Итак пойдёт"},{"doc_id":3361,"url":"../t130p150-topic.html#p17491","post_id":"p17491","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 11 Сен 2015 - 23:23","sort_key":"2015-09-11 23:23:00","excerpt":"Алисочка полностью вменяемая. Но пятый день Слави будет занятным. Собственно, все классики пойдут по тем же рельсам."},{"doc_id":3362,"url":"../t130p150-topic.html#p17492","post_id":"p17492","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:24","sort_key":"2015-09-11 23:24:00","excerpt":"Про сцену, где сначала Лена, потом Славя, а потом уже и Юля - забыл? Уже поздно что-то менять!"},{"doc_id":3363,"url":"../t130p150-topic.html#p17493","post_id":"p17493","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:25","sort_key":"2015-09-11 23:25:00","excerpt":"Вменяемая или нет - это, извините, читателям оценивать, хотя ваши слова вселяют некоторую надежду, не скрою. А про Славю вам и без меня выскажут, не сомневаюсь. И вообще она мне не нравится."},{"doc_id":3364,"url":"../t130p150-topic.html#p17494","post_id":"p17494","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:26","sort_key":"2015-09-11 23:26:00","excerpt":"Там всё в строгой очерёдности, не надо народ путать!"},{"doc_id":3365,"url":"../t130p150-topic.html#p17495","post_id":"p17495","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:27","sort_key":"2015-09-11 23:27:00","excerpt":"А, ну раз это за групповуху не считается, тогда окей"},{"doc_id":3366,"url":"../t130p150-topic.html#p17496","post_id":"p17496","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:27","sort_key":"2015-09-11 23:27:00","excerpt":"Это воспринимать как маленький анонс?"},{"doc_id":3367,"url":"../t130p150-topic.html#p17497","post_id":"p17497","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:28","sort_key":"2015-09-11 23:28:00","excerpt":"Групповуха - это когда одновременно. А там не одновременно, там всё в строгой очерёдности, остальные просто смотрят."},{"doc_id":3368,"url":"../t130p150-topic.html#p17498","post_id":"p17498","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:29","sort_key":"2015-09-11 23:29:00","excerpt":"Ну, Славя же у нас - олицитворения альтруизма и всех благ, ну или как-то так. А вы, товарищ, вполне соответствуете своему статусу"},{"doc_id":3369,"url":"../t130p150-topic.html#p17499","post_id":"p17499","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:29","sort_key":"2015-09-11 23:29:00","excerpt":"Чесс - это конвейер получается."},{"doc_id":3370,"url":"../t130p150-topic.html#p17500","post_id":"p17500","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:31","sort_key":"2015-09-11 23:31:00","excerpt":"Лично мне она кажется олицетворением незамутнённого идеализма. Приходилось сталкиваться с подобными, и ничего, кроме кромешного 3,14159здеца, в воспоминаниях не осталось."},{"doc_id":3371,"url":"../t130p150-topic.html#p17501","post_id":"p17501","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 11 Сен 2015 - 23:32","sort_key":"2015-09-11 23:32:00","excerpt":"Но не групповуха же?!"},{"doc_id":3372,"url":"../t130p150-topic.html#p17502","post_id":"p17502","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пт 11 Сен 2015 - 23:33","sort_key":"2015-09-11 23:33:00","excerpt":"Нет, обыкновенный открытый урок."},{"doc_id":3373,"url":"../t130p175-topic.html#p17503","post_id":"p17503","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:33","sort_key":"2015-09-11 23:33:00","excerpt":"И с этих строк начинается обсуждение Слави страниц на 40 в стиле - Всё не так! Учитывая, что там товарищ в новых в треде новых версиях про обожествление Слави говорил, то это будет эпично. Богиня покарает . Если ещё…"},{"doc_id":3374,"url":"../t130p175-topic.html#p17504","post_id":"p17504","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:34","sort_key":"2015-09-11 23:34:00","excerpt":"Зато мне нравится. Постепенно мигрирую в стан Славяфагов."},{"doc_id":3375,"url":"../t130p175-topic.html#p17505","post_id":"p17505","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:36","sort_key":"2015-09-11 23:36:00","excerpt":"На VN реакторе заметил, что же, welcome to our team!"},{"doc_id":3376,"url":"../t130p175-topic.html#p17506","post_id":"p17506","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:37","sort_key":"2015-09-11 23:37:00","excerpt":"Прям как под колпаком себя чувствуешь..."},{"doc_id":3377,"url":"../t130p175-topic.html#p17507","post_id":"p17507","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:37","sort_key":"2015-09-11 23:37:00","excerpt":"Теперь их стало больше... Лол)"},{"doc_id":3378,"url":"../t130p175-topic.html#p17508","post_id":"p17508","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:39","sort_key":"2015-09-11 23:39:00","excerpt":"Та не, никакого колпака, но принадлежность к тому или иному, ммм...складу вкусов или архитипической предрасположенности - определенная цепь. Но человек не может без определенных цепей, да и они - не всегда что-то плохое…"},{"doc_id":3379,"url":"../t130p175-topic.html#p17509","post_id":"p17509","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:41","sort_key":"2015-09-11 23:41:00","excerpt":"... мне МОЖНО!\""},{"doc_id":3380,"url":"../t130p175-topic.html#p17510","post_id":"p17510","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:42","sort_key":"2015-09-11 23:42:00","excerpt":"Ахаха, оценил) Скоро шутки про легионеров подойдут) А так же - СЛАВЯКАРТОНКА!11!001"},{"doc_id":3381,"url":"../t130p175-topic.html#p17511","post_id":"p17511","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пт 11 Сен 2015 - 23:46","sort_key":"2015-09-11 23:46:00","excerpt":"Не, обойдемся без легионеров. Рим пал, центурион."},{"doc_id":3382,"url":"../t130p175-topic.html#p17512","post_id":"p17512","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Пт 11 Сен 2015 - 23:48","sort_key":"2015-09-11 23:48:00","excerpt":"Да и про картон не стоит, иначе у меня возникнет внутренний диссонанс на тему - А зачем я писал работ 5 по психоанализу архетипа Слави) Прям фраза Виолы)"},{"doc_id":3383,"url":"../t130p175-topic.html#p17514","post_id":"p17514","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 0:11","sort_key":"2015-09-12 00:11:00","excerpt":"Что-то даже Антон Павлович вспомнился:\"Ну что ж, раздевайтесь, но слегка сопротивляйтесь.\""},{"doc_id":3384,"url":"../t130p175-topic.html#p17515","post_id":"p17515","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 1:48","sort_key":"2015-09-12 01:48:00","excerpt":"Таки-шо, реально писал? А где ознакомиться можно? Не, ты не подумай, я без задней мысли. Реально интересно было бы ознакомится."},{"doc_id":3385,"url":"../t130p175-topic.html#p17516","post_id":"p17516","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 1:55","sort_key":"2015-09-12 01:55:00","excerpt":"Дак три точно в Славятреде валяется, ещё со времён Макиавелли, их спецом для фендома пилил, алсо для Автора, если запчасти будут нужны. Если вломы искать, то могу сюда кинуть."},{"doc_id":3386,"url":"../t130p175-topic.html#p17517","post_id":"p17517","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 2:01","sort_key":"2015-09-12 02:01:00","excerpt":"Ток сразу предупреждаю, что работа - нубская. Я писал её очень давно, будучи крайне неопытным в этой деле. Это вообще моя первая работа, сейчас их число перевалило за 50+."},{"doc_id":3387,"url":"../t130p175-topic.html#p17518","post_id":"p17518","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 2:15","sort_key":"2015-09-12 02:15:00","excerpt":"Размяв пальцы и прочитав ОЧЕНЬ много материала о Славяне, начиная от характеристики Arlien и портрета от Элдхэнна ( 19 стр.), заканчивая модами, фанфиками и прочими источниками типо диздоков, форумов и тд., решил…"},{"doc_id":3388,"url":"../t130p175-topic.html#p17519","post_id":"p17519","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 2:21","sort_key":"2015-09-12 02:21:00","excerpt":"Ух, наконец-то засел за 2ую часть, где постараюсь описать недостатки или как правильнее сказать отрицательные черты Слави. Во многом работа основывается на некоторых, как по мне, интересных идеях 7dl-kun и Элдхэнна . Так…"},{"doc_id":3389,"url":"../t130p175-topic.html#p17520","post_id":"p17520","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 2:22","sort_key":"2015-09-12 02:22:00","excerpt":"Славя/Семён Да, что-то я долго с этой работой, но лучше поздно, чем никогда. Начну, пожалуй, с закуски, хоть и люблю начинать с десерта. Семён. Все мы знаем, кто есть Семён, все знаем его бэк, характер, черты и с чем его…"},{"doc_id":3390,"url":"../t130p175-topic.html#p17521","post_id":"p17521","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 2:39","sort_key":"2015-09-12 02:39:00","excerpt":"Чувак, а ведь ты в корне не прав. Славю воспитали альтруисткой, но сама она, учитывая возраст, является супер-эгоисткой, подгоняющей подсознательно все события под себя. Типа \"выгодно - не выгодно\". Не забывай, ей всего…"},{"doc_id":3391,"url":"../t130p175-topic.html#p17522","post_id":"p17522","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 3:06","sort_key":"2015-09-12 03:06:00","excerpt":"Насколько я помню, так начинается Славя тред на 1000 и 1 страницу) Честно говоря мне так влом устраивать вайфу срач и перекидку на ИМХО, а уж тем более на эту тему."},{"doc_id":3392,"url":"../t130p175-topic.html#p17523","post_id":"p17523","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 3:06","sort_key":"2015-09-12 03:06:00","excerpt":"Ну а в целом, эгоизм это вполне нормально."},{"doc_id":3393,"url":"../t130p175-topic.html#p17526","post_id":"p17526","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 15:41","sort_key":"2015-09-12 15:41:00","excerpt":"Ну а про возраст, кто его знает, бэк-то мы не особо знаем, может и было что. На момент 17 лет мне уже 2 раза приходилось спасать людей от смерти + видел довольно много, такие дела. Не хвастаюсь и не горжусь, просто…"},{"doc_id":3394,"url":"../t130p175-topic.html#p17527","post_id":"p17527","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 12 Сен 2015 - 15:54","sort_key":"2015-09-12 15:54:00","excerpt":"Обострённое восприятие рука об руку идёт с эгоизмом. Ты не можешь делать плохо людям, так как тебе от этого самому плохо."},{"doc_id":3395,"url":"../t130p175-topic.html#p17528","post_id":"p17528","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 15:56","sort_key":"2015-09-12 15:56:00","excerpt":"Да, это универсальная истина. За пыл свой, прощу прощение, голова что-то чрезмерно горячая последнее время."},{"doc_id":3396,"url":"../t130p175-topic.html#p17529","post_id":"p17529","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 15:58","sort_key":"2015-09-12 15:58:00","excerpt":"Только вот проблема - к 17-и годам детский эгоизм это болячка сугубо городских единственных детишек. Братья-сестры какбе с малолетства демонстрируют, что ты не пуп земли."},{"doc_id":3397,"url":"../t130p175-topic.html#p17530","post_id":"p17530","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 16:01","sort_key":"2015-09-12 16:01:00","excerpt":"Особенно старшие"},{"doc_id":3398,"url":"../t130p200-topic.html#p17531","post_id":"p17531","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 12 Сен 2015 - 16:20","sort_key":"2015-09-12 16:20:00","excerpt":"А кто говорит о детском эгоизме? Речь скорее об эгоизме вполне себе взрослом, без попыток вращать вселенную вокруг собственного пупа."},{"doc_id":3399,"url":"../t130p200-topic.html#p17532","post_id":"p17532","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 16:28","sort_key":"2015-09-12 16:28:00","excerpt":"Сундук говорит. Не то что бы я собирался с ним дискутировать, но если уж вы косвенно с ним соглашаетесь..."},{"doc_id":3400,"url":"../t130p200-topic.html#p17533","post_id":"p17533","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Сб 12 Сен 2015 - 17:23","sort_key":"2015-09-12 17:23:00","excerpt":"Да не правда. Всё зависит от мотивации и собственного отношения. И примеров тому в различных вариантах у меня есть куча."},{"doc_id":3401,"url":"../t130p200-topic.html#p17534","post_id":"p17534","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 18:45","sort_key":"2015-09-12 18:45:00","excerpt":"Ну конечно, Сундук ведь априори не может быть прав!"},{"doc_id":3402,"url":"../t130p200-topic.html#p17535","post_id":"p17535","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 18:57","sort_key":"2015-09-12 18:57:00","excerpt":""},{"doc_id":3403,"url":"../t130p200-topic.html#p17536","post_id":"p17536","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 18:57","sort_key":"2015-09-12 18:57:00","excerpt":"Нет, Сундук просто не заинтересован в плодотворной дискуссии."},{"doc_id":3404,"url":"../t130p200-topic.html#p17537","post_id":"p17537","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 19:02","sort_key":"2015-09-12 19:02:00","excerpt":"Всегда доставляет)"},{"doc_id":3405,"url":"../t130p200-topic.html#p17538","post_id":"p17538","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 19:03","sort_key":"2015-09-12 19:03:00","excerpt":"Алсо мы уже обсуждали мой концепт в Славятреде, ни к чему дельному это ни привело. Да, это штука такая, никакой пользы, а у народ горит. Сразу можно сказать, что текст мне принадлежит)"},{"doc_id":3406,"url":"../t130p200-topic.html#p17539","post_id":"p17539","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 19:03","sort_key":"2015-09-12 19:03:00","excerpt":"Не то что некий тащ А., который упёрся рогом и не может взглянуть на предмет дискуссии глазами оппонента."},{"doc_id":3407,"url":"../t130p200-topic.html#p17540","post_id":"p17540","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 19:06","sort_key":"2015-09-12 19:06:00","excerpt":"Йеп, именно об этом и речь. Голословие и траленг."},{"doc_id":3408,"url":"../t130p200-topic.html#p17541","post_id":"p17541","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 19:08","sort_key":"2015-09-12 19:08:00","excerpt":"Ну почему же, я неоднократно излагал свою точку зрения, но ты её с негодованием отметал каждый раз. Как же, на Идеал™ покусились!"},{"doc_id":3409,"url":"../t130p200-topic.html#p17542","post_id":"p17542","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 19:15","sort_key":"2015-09-12 19:15:00","excerpt":"Я всего лишь указывал на зияющие в ней дыры и прямые противоречия с прямо объявленной концепцией 7ДЛ. А ты почему-то вместо контраргументации или признания поражения обижался и бежал в флудилку рассказывать, какой этот…"},{"doc_id":3410,"url":"../t130p200-topic.html#p17543","post_id":"p17543","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 19:17","sort_key":"2015-09-12 19:17:00","excerpt":"Осталось только поделиться на два лагеря и ждать, пока товарищ автор не объявит перемирие."},{"doc_id":3411,"url":"../t130p200-topic.html#p17544","post_id":"p17544","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 19:20","sort_key":"2015-09-12 19:20:00","excerpt":"А про концепт 7ДЛ речи не было, я говорил именно о Славе и её поведении. И, кстати, расскажи-ка мне, когда это я тебя во флудилке \"гнусным дураком\" называл? С примерами, желательно."},{"doc_id":3412,"url":"../t130p200-topic.html#p17545","post_id":"p17545","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 19:21","sort_key":"2015-09-12 19:21:00","excerpt":"И делать ставки. Самое интересное в интернет-срачах, это то, что объективного критерия победы тут нет, поэтому будем ждать, пока кто-нибудь не согласится считать себя побежденным."},{"doc_id":3413,"url":"../t130p200-topic.html#p17546","post_id":"p17546","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 19:22","sort_key":"2015-09-12 19:22:00","excerpt":"Ставлю 50 на тебя)"},{"doc_id":3414,"url":"../t130p200-topic.html#p17547","post_id":"p17547","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 19:25","sort_key":"2015-09-12 19:25:00","excerpt":"50 чего?"},{"doc_id":3415,"url":"../t130p200-topic.html#p17548","post_id":"p17548","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 19:30","sort_key":"2015-09-12 19:30:00","excerpt":"Орены конечно же."},{"doc_id":3416,"url":"../t130p200-topic.html#p17549","post_id":"p17549","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 19:44","sort_key":"2015-09-12 19:44:00","excerpt":"На форуме, посвященном 7ДЛ, в топике для обсуждения персонажа 7ДЛ, о 7ДЛ речи не шло? Воа. Уволь. Тратить на составление постов тебе более двух минут я зарекся)"},{"doc_id":3417,"url":"../t130p200-topic.html#p17550","post_id":"p17550","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 19:46","sort_key":"2015-09-12 19:46:00","excerpt":"[quote=\"Arlien\"] На форуме, посвященном 7ДЛ, в топике для обсуждения персонажа 7ДЛ, о 7ДЛ речи не шло? Воа. Ага, именно. Обсуждали персонажа, а не общие положения мода, представь себе."},{"doc_id":3418,"url":"../t130p200-topic.html#p17551","post_id":"p17551","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 21:54","sort_key":"2015-09-12 21:54:00","excerpt":"Итак, что мы наблюдаем, коллеги? Необоснованные обвинения в оскорблениях, не подкреплённые никакими пруфами, абсолютное нежелание разговаривать по теме дискуссии, нелепая попытка выдать тёплое за мягкое и окончание…"},{"doc_id":3419,"url":"../t130p200-topic.html#p17552","post_id":"p17552","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 21:55","sort_key":"2015-09-12 21:55:00","excerpt":"Но кто же, все-таки, победил?"},{"doc_id":3420,"url":"../t130p200-topic.html#p17553","post_id":"p17553","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 21:58","sort_key":"2015-09-12 21:58:00","excerpt":"А шо, был поединок? С моей стороны имела место быть попытка расставить все точки над характером и внутренними побуждениями Славяны, но оппонент предпочёл... Ладно, не будем о грустном."},{"doc_id":3421,"url":"../t130p200-topic.html#p17554","post_id":"p17554","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 21:59","sort_key":"2015-09-12 21:59:00","excerpt":"Как в шахматы с голубем сыграл."},{"doc_id":3422,"url":"../t130p200-topic.html#p17555","post_id":"p17555","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 22:02","sort_key":"2015-09-12 22:02:00","excerpt":"Смотря с какой стороны посмотреть. Я в принципе достиг своей цели - убедился в том, что Сундук все такой же дубовый. Но поле боя осталось за ним. Ситуация примерно как при Бородино - каждый может хвастаться победой, и…"},{"doc_id":3423,"url":"../t130p225-topic.html#p17556","post_id":"p17556","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 22:04","sort_key":"2015-09-12 22:04:00","excerpt":"Давайте, давайте, второй раунд!"},{"doc_id":3424,"url":"../t130p225-topic.html#p17557","post_id":"p17557","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 22:08","sort_key":"2015-09-12 22:08:00","excerpt":"Я где-то не прав в своём посте? Прошу указать, в чём именно. Если хочешь дальше дискутировать по теме, предлагаю перейти в соответствующую тему форума."},{"doc_id":3425,"url":"../t130p225-topic.html#p17558","post_id":"p17558","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 22:28","sort_key":"2015-09-12 22:28:00","excerpt":"Ну, собссно, как и следовало ожидать, Арли не хочет понять чужую точку зрения, Арли хочет, штоп все заткнулись и не порочили божественный Идеал™ маде ин его. И автору то же навязать, он наверняка тоже он не осознаёт…"},{"doc_id":3426,"url":"../t130p225-topic.html#p17559","post_id":"p17559","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 22:30","sort_key":"2015-09-12 22:30:00","excerpt":"Вангую гневный пост с завуалированными оскорблениями."},{"doc_id":3427,"url":"../t130p225-topic.html#p17560","post_id":"p17560","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 22:41","sort_key":"2015-09-12 22:41:00","excerpt":"Ой, я как-то имел глупость указать, в чем ты неправ :Д Второй раз? Не-не-не. Я бы и сегодня твой наброс проигнорил, но тащ автор всплыл, пришлось уточнить некоторые моменты."},{"doc_id":3428,"url":"../t130p225-topic.html#p17561","post_id":"p17561","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 22:46","sort_key":"2015-09-12 22:46:00","excerpt":"Барин, будьте добре, повторите, где именно это произошло. Таки я был прав: ...насчёт завуалированных оскорблений."},{"doc_id":3429,"url":"../t130p225-topic.html#p17562","post_id":"p17562","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 23:00","sort_key":"2015-09-12 23:00:00","excerpt":"Э-э-эх, Сундук-Сундук. Ты на мне сегодня уже с пяток методов своего МЛГ-траленга испробовал. Ну не стыдно тебе после этого косить под \"дискуссию\", а? Палишься же безбожно) На , держи, так уж и быть. Не то что бы я…"},{"doc_id":3430,"url":"../t130p225-topic.html#p17563","post_id":"p17563","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:02","sort_key":"2015-09-12 23:02:00","excerpt":"Я и слов-то таких не знаю, а уж аббревиатура эта для меня вообще загадка. Не мог бы просветить? Ну а \"примеры\" твои, извиняй, у меня что-то не отображаются:"},{"doc_id":3431,"url":"../t130p225-topic.html#p17564","post_id":"p17564","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 23:09","sort_key":"2015-09-12 23:09:00","excerpt":"Э-э-эх.. http://bl7dl.2x2forum.ru/t68p150-topic"},{"doc_id":3432,"url":"../t130p225-topic.html#p17565","post_id":"p17565","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:13","sort_key":"2015-09-12 23:13:00","excerpt":"Это даже волне логично. Арли изначально Славяфаг, а Чесс изначально Алисофаг. Что приводит нас к тому, что Арли будет всегда относится к Славе положительно, а Чесс отрицательно. Таким образом этот спор будет вечен, ведь…"},{"doc_id":3433,"url":"../t130p225-topic.html#p17566","post_id":"p17566","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:15","sort_key":"2015-09-12 23:15:00","excerpt":"И в где же я на указанной тобой странице не прав?"},{"doc_id":3434,"url":"../t130p225-topic.html#p17567","post_id":"p17567","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:17","sort_key":"2015-09-12 23:17:00","excerpt":"Я вовсе не отношусь к Славе отрицательно, более того, я прекрасно понимаю её мотивы, хоть и не принимаю. Проблема именно в том, что Арли категорически не приемлет чужих мнений и при этом пытается навязать собственную…"},{"doc_id":3435,"url":"../t130p225-topic.html#p17568","post_id":"p17568","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 23:18","sort_key":"2015-09-12 23:18:00","excerpt":"Как инь и ян?"},{"doc_id":3436,"url":"../t130p225-topic.html#p17569","post_id":"p17569","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 12 Сен 2015 - 23:19","sort_key":"2015-09-12 23:19:00","excerpt":"То неземное чувство, когда твой провайдер заблокировал картинки на буре, но забыл заблокировать буру целиком."},{"doc_id":3437,"url":"../t130p225-topic.html#p17570","post_id":"p17570","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:19","sort_key":"2015-09-12 23:19:00","excerpt":"Такблять. Никаких хентаев."},{"doc_id":3438,"url":"../t130p225-topic.html#p17571","post_id":"p17571","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 23:20","sort_key":"2015-09-12 23:20:00","excerpt":"Между прочим, я самый невинный арт приложил!"},{"doc_id":3439,"url":"../t130p225-topic.html#p17572","post_id":"p17572","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:21","sort_key":"2015-09-12 23:21:00","excerpt":"В то время как он считает наоборот. Тем не менее уверенность в своей позиции верный путь на осветит, как говорится. Просто ты видишь одну сторону медали, а сэмпай вторую. Как сэмпай сам говорил - не ищите пятна на…"},{"doc_id":3440,"url":"../t130p225-topic.html#p17573","post_id":"p17573","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:23","sort_key":"2015-09-12 23:23:00","excerpt":"Знаешь, именно это я и имел ввиду, по крайней мере инь и ян данного форума, а вы как всегда очень точны, Перегарыч-сама)"},{"doc_id":3441,"url":"../t130p225-topic.html#p17574","post_id":"p17574","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:25","sort_key":"2015-09-12 23:25:00","excerpt":"По моему 50 оренов сыграли, победа за тобой, все были сражены артом)"},{"doc_id":3442,"url":"../t130p225-topic.html#p17575","post_id":"p17575","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 23:25","sort_key":"2015-09-12 23:25:00","excerpt":"Как-то не приходилось еще сравнивать... Но тут, наверно, будет уместно вспомнить Хайнлайновское \"Ты еси бог\"."},{"doc_id":3443,"url":"../t130p225-topic.html#p17576","post_id":"p17576","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:26","sort_key":"2015-09-12 23:26:00","excerpt":"Я свою точку зрения, по крайней мере, никому не навязываю. И к критике открытой готов. И даже то, что я при нелестном упоминании Алисочки якобы стол грызу - не более, чем гипербола, признаюсь. Взрослые люди ведь."},{"doc_id":3444,"url":"../t130p225-topic.html#p17577","post_id":"p17577","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:28","sort_key":"2015-09-12 23:28:00","excerpt":"Да всё в порядке, если у всех конечности на месте, то проблем нет. А я теперь трижды подумаю перед тем, как что-нибудь по Славе кидать, а то устраивать потасовку весело, конечно, но это привносит негатив и деструктив."},{"doc_id":3445,"url":"../t130p225-topic.html#p17578","post_id":"p17578","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Сб 12 Сен 2015 - 23:29","sort_key":"2015-09-12 23:29:00","excerpt":"Да ладно?!"},{"doc_id":3446,"url":"../t130p225-topic.html#p17579","post_id":"p17579","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:29","sort_key":"2015-09-12 23:29:00","excerpt":"Отличительная черта людей в том, что они, в отличие от большинства божеств, способны удивлять своим поведением. Прыгать выше головы и облизывать локоть порою. Такие дела."},{"doc_id":3447,"url":"../t130p225-topic.html#p17580","post_id":"p17580","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:30","sort_key":"2015-09-12 23:30:00","excerpt":"Так как Арли нет в баре, а капитана кто-то должен сыграть, то займусь этим я)"},{"doc_id":3448,"url":"../t130p25-topic.html#p17250","post_id":"p17250","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 5 Сен 2015 - 23:13","sort_key":"2015-09-05 23:13:00","excerpt":"Знаю знаю, благо красивейший томик сочинений уахпал ещё года 3 назад себе в коллекцию Кошки - всегда топ!"},{"doc_id":3449,"url":"../t130p25-topic.html#p17307","post_id":"p17307","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пн 7 Сен 2015 - 23:37","sort_key":"2015-09-07 23:37:00","excerpt":"О Семёне, разуме и девушках:"},{"doc_id":3450,"url":"../t130p25-topic.html#p17308","post_id":"p17308","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 7 Сен 2015 - 23:45","sort_key":"2015-09-07 23:45:00","excerpt":"Не видят этого женщины. Раздался бы истошный вопль \"ШОВИНИСТ!!!\". И в слёзы. Потом звук бьющейся посуды. Опять слёзы. Опять посуда. Звук извлекаемого из антресолей чемодана. В общем, к утру ты ей оказываешься должен как…"},{"doc_id":3451,"url":"../t130p25-topic.html#p17309","post_id":"p17309","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пн 7 Сен 2015 - 23:48","sort_key":"2015-09-07 23:48:00","excerpt":"Не, я в этом варианте реакции непробиваем. Начинаю обидно ржать и беспощадно разить логикой в ответ на каждую претензию."},{"doc_id":3452,"url":"../t130p25-topic.html#p17310","post_id":"p17310","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 7 Сен 2015 - 23:53","sort_key":"2015-09-07 23:53:00","excerpt":"Хорошо быть дредноутом. Правда с логическим восприятием иной раз такая беда бывает."},{"doc_id":3453,"url":"../t130p25-topic.html#p17311","post_id":"p17311","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пн 7 Сен 2015 - 23:56","sort_key":"2015-09-07 23:56:00","excerpt":"Моя любовь сидит на кухне в фиолетовых клубах, Я растоптал ее надежды молодые в пух и прах. Она хотела к Авалону с белым лебедем лететь, А ей приходится над грязной сковородкою корпеть. \"Это не жизнь, - она думает, - это…"},{"doc_id":3454,"url":"../t130p25-topic.html#p17312","post_id":"p17312","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 7 Сен 2015 - 23:59","sort_key":"2015-09-07 23:59:00","excerpt":"Я и есть жизнь. Кому не нравится - на выход. Так что ли?"},{"doc_id":3455,"url":"../t130p25-topic.html#p17313","post_id":"p17313","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:06","sort_key":"2015-09-08 00:06:00","excerpt":"Это называется \"положительное отношение\". Положил - и относись."},{"doc_id":3456,"url":"../t130p25-topic.html#p17314","post_id":"p17314","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 0:11","sort_key":"2015-09-08 00:11:00","excerpt":"Есть всё-таки что-то эдакое в японском стихосложении. Вчера прождала, Пустым обещаньям поверив Сегодня опять Опускается вечер унылый Могу ли я верить, что завтра?"},{"doc_id":3457,"url":"../t130p25-topic.html#p17315","post_id":"p17315","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:25","sort_key":"2015-09-08 00:25:00","excerpt":"Жил на свете самурай Добрый и внимательный. Каждый день он собирал Икебану матери."},{"doc_id":3458,"url":"../t130p25-topic.html#p17316","post_id":"p17316","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:31","sort_key":"2015-09-08 00:31:00","excerpt":"Или вот ещё: Семён крадётся, Кошочку заметил он. Не поймаешь, Дрищ. Вроде даже по слогам попал?"},{"doc_id":3459,"url":"../t130p25-topic.html#p17317","post_id":"p17317","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 0:34","sort_key":"2015-09-08 00:34:00","excerpt":"Неплохо. И не надо придумывать рут в неделю. 3 строчки и всё понятно."},{"doc_id":3460,"url":"../t130p25-topic.html#p17318","post_id":"p17318","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:37","sort_key":"2015-09-08 00:37:00","excerpt":"Всё, посоны, кошкорут отменяется. Тремя строчками обойдёмся."},{"doc_id":3461,"url":"../t130p25-topic.html#p17319","post_id":"p17319","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 0:38","sort_key":"2015-09-08 00:38:00","excerpt":"Ну, может снизойдёте к нам и, хотя бы, в 9. Ещё же Локи, Герк."},{"doc_id":3462,"url":"../t130p25-topic.html#p17320","post_id":"p17320","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:43","sort_key":"2015-09-08 00:43:00","excerpt":"Сам же сказал, что не надо!"},{"doc_id":3463,"url":"../t130p25-topic.html#p17321","post_id":"p17321","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 0:46","sort_key":"2015-09-08 00:46:00","excerpt":"Не надо глупую мысль одного недоиндивидума проецировать на всех модопочитателей."},{"doc_id":3464,"url":"../t130p25-topic.html#p17322","post_id":"p17322","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:48","sort_key":"2015-09-08 00:48:00","excerpt":"А при чём здесь мод? Речь вроде о руте им.Кошочки шла?"},{"doc_id":3465,"url":"../t130p25-topic.html#p17323","post_id":"p17323","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 0:50","sort_key":"2015-09-08 00:50:00","excerpt":"Так какое может сложиться целостное мнение о моде без рута Юли всея Руси и окрестныя шахты?????"},{"doc_id":3466,"url":"../t130p25-topic.html#p17324","post_id":"p17324","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 0:57","sort_key":"2015-09-08 00:57:00","excerpt":"А можно элементарно постигнуть концепт Автора, например. Кошочка-то чисто вариативна, в конце концов. Именно поэтому кошочкины недры и разрабатываются группой добровольцев, а не Автором лично."},{"doc_id":3467,"url":"../t130p25-topic.html#p17325","post_id":"p17325","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 0:58","sort_key":"2015-09-08 00:58:00","excerpt":"Решил в разум человека кошку подселить, аль просто глаз высосать?"},{"doc_id":3468,"url":"../t130p25-topic.html#p17326","post_id":"p17326","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:02","sort_key":"2015-09-08 01:02:00","excerpt":"М-да, Штейн. Быстро из тебя рыцарь Света выветрился. Сразу и глаз высосать, а мизерикорд для чего у тебя?"},{"doc_id":3469,"url":"../t130p25-topic.html#p17327","post_id":"p17327","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:03","sort_key":"2015-09-08 01:03:00","excerpt":"Честно говоря, я просто возмущён подобной постановкой вопроса. Почему нас все окружающие держат за каких-то неадекватных маньяков, скажите мне? Рут Юли - всего лишь вариант отхождения Семёна от рутов девушек или поиска…"},{"doc_id":3470,"url":"../t130p25-topic.html#p17328","post_id":"p17328","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:04","sort_key":"2015-09-08 01:04:00","excerpt":"Всё нормально, тащ меня цитирует."},{"doc_id":3471,"url":"../t130p25-topic.html#p17329","post_id":"p17329","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:05","sort_key":"2015-09-08 01:05:00","excerpt":"Знаю. Правда до этого, только при поминании всуе Алиски замечалось."},{"doc_id":3472,"url":"../t130p25-topic.html#p17330","post_id":"p17330","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:09","sort_key":"2015-09-08 01:09:00","excerpt":"Да нет, у меня за это время спасённых душ в статке только прибавилось, на повышение иду, новый ранг скоро, просто я всегда был неправильным паладином, в отличие от Арли. Темным что-ли, поэтому мы с Чессом и ладим…"},{"doc_id":3473,"url":"../t130p250-topic.html#p17581","post_id":"p17581","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 23:34","sort_key":"2015-09-12 23:34:00","excerpt":"Как же с тобой сложно... На пальцах. Выдвинут тезис - якобы инстинкт самосохранения перевешивает всё. Тезис опровергнут наглядным примером. После опровержения ты тихонько сливаешься - и, если мне не изменяет память, как…"},{"doc_id":3474,"url":"../t130p250-topic.html#p17582","post_id":"p17582","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:41","sort_key":"2015-09-12 23:41:00","excerpt":"Чо, правда? Пойдём по пунктам. Инстинкт самосохранения способен перебить только инстинкт материнский. Славе сколько годиков? Ткни меня носом, плиз, в наглядный пример. И опять же, носом в туда, где я якобы сливаюсь. И по…"},{"doc_id":3475,"url":"../t130p250-topic.html#p17583","post_id":"p17583","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 23:47","sort_key":"2015-09-12 23:47:00","excerpt":"Ненавижу повторяться, я уже говорил, да? Но так уж и быть. Если инстинкт самосохранения ничем не перевешивается - как в принципе возможен акт самоубийства? Хотя бы?"},{"doc_id":3476,"url":"../t130p250-topic.html#p17584","post_id":"p17584","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:49","sort_key":"2015-09-12 23:49:00","excerpt":"Героизм и самопожертвование к этому добавлю, например."},{"doc_id":3477,"url":"../t130p250-topic.html#p17585","post_id":"p17585","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Сб 12 Сен 2015 - 23:51","sort_key":"2015-09-12 23:51:00","excerpt":"Не надо к этому ничего добавлять. Тут только офигенных историй про пьяницу Матросова, который на льду поскользнулся, не хватало."},{"doc_id":3478,"url":"../t130p250-topic.html#p17586","post_id":"p17586","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:51","sort_key":"2015-09-12 23:51:00","excerpt":"А что, я тебе по твоей же ссылке не ответил?"},{"doc_id":3479,"url":"../t130p250-topic.html#p17587","post_id":"p17587","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:52","sort_key":"2015-09-12 23:52:00","excerpt":"По пьяне на катке в футбол играли, инстинкт был подавлен чуть больше, чем полностью)"},{"doc_id":3480,"url":"../t130p250-topic.html#p17588","post_id":"p17588","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 12 Сен 2015 - 23:54","sort_key":"2015-09-12 23:54:00","excerpt":"Це ж ремиссия. Краткая и неустойчивая. Кураж, если хотите. Полностью отказаться нельзя, можно только временно задавить."},{"doc_id":3481,"url":"../t130p250-topic.html#p17589","post_id":"p17589","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 12 Сен 2015 - 23:57","sort_key":"2015-09-12 23:57:00","excerpt":"Ну да, это прописано в самых базовых правил человеческого сознания. Как протокол - Не умирать и не получать демедж по возможности. Речь же не идёт о том, что просто руководствоваться инстинктом самосохранения для того…"},{"doc_id":3482,"url":"../t130p250-topic.html#p17590","post_id":"p17590","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Сб 12 Сен 2015 - 23:59","sort_key":"2015-09-12 23:59:00","excerpt":"Вот кстати, тащ Автор. Вы наверняка старательно фиксировали в анналах. Скажите, я не прав?"},{"doc_id":3483,"url":"../t130p250-topic.html#p17591","post_id":"p17591","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:00","sort_key":"2015-09-13 00:00:00","excerpt":"Ну, как бы ответил. Рассказал мне о вещах, которые в итоге этот самый инстинкт успешно перевешивают."},{"doc_id":3484,"url":"../t130p250-topic.html#p17592","post_id":"p17592","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:02","sort_key":"2015-09-13 00:02:00","excerpt":"Ага, в критических ситуациях. Коих может и не выпасть за всю жизнь. А что по поводу \"слился\"?"},{"doc_id":3485,"url":"../t130p250-topic.html#p17593","post_id":"p17593","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:05","sort_key":"2015-09-13 00:05:00","excerpt":"Т.е. ты признаешь, что в тезисе уже одна дыра нашлась, да?"},{"doc_id":3486,"url":"../t130p250-topic.html#p17594","post_id":"p17594","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:09","sort_key":"2015-09-13 00:09:00","excerpt":"В каком именно тезисе? Какая именно дыра? Излагай полнее, не стесняйся, люди тебе сочувствуют, и даже, может, поймут."},{"doc_id":3487,"url":"../t130p250-topic.html#p17595","post_id":"p17595","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:10","sort_key":"2015-09-13 00:10:00","excerpt":"Толстовато не в меру уже."},{"doc_id":3488,"url":"../t130p250-topic.html#p17596","post_id":"p17596","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:13","sort_key":"2015-09-13 00:13:00","excerpt":"Я вполне серьёзен. Нет, ну Арли прадва не понимает, что инстинкт защиты потомства перевешивает всё? Он кошочек с котятками никогда не видел?"},{"doc_id":3489,"url":"../t130p250-topic.html#p17597","post_id":"p17597","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:16","sort_key":"2015-09-13 00:16:00","excerpt":"Ыхыхыхы, неотразимая техника \"Прикинуться золотой рыбкой\" :Д Давненько я не видел ее в деле."},{"doc_id":3490,"url":"../t130p250-topic.html#p17598","post_id":"p17598","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:17","sort_key":"2015-09-13 00:17:00","excerpt":"Я больше про последнюю фразу. Ну не всё же в жизни курирует от желания не получить люлей. Это всегда регулируется, как рынок. Да, это самый базис психологии любого, боязнь за свою шкуру, без него мы бы уже все туда…"},{"doc_id":3491,"url":"../t130p250-topic.html#p17599","post_id":"p17599","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:17","sort_key":"2015-09-13 00:17:00","excerpt":"Буль буль, аквариум штука довольно прочная, сэмпай."},{"doc_id":3492,"url":"../t130p250-topic.html#p17600","post_id":"p17600","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:20","sort_key":"2015-09-13 00:20:00","excerpt":"Да в рот компот... Да, инстинкт самосохранения может быть подавлен инстинктом защиты потомства, факт. Какое отношение это имеет к Славе? Или она ранняя, деревенская и всё такое? Как-то не вписывается в твоё видение её…"},{"doc_id":3493,"url":"../t130p250-topic.html#p17601","post_id":"p17601","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:25","sort_key":"2015-09-13 00:25:00","excerpt":"Вопрос ко мне или к Сэмпаю?"},{"doc_id":3494,"url":"../t130p250-topic.html#p17602","post_id":"p17602","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:26","sort_key":"2015-09-13 00:26:00","excerpt":"К Арли, очевидно же. Но если есть неодолимое желание общаться, можем и с тобой поговорить."},{"doc_id":3495,"url":"../t130p250-topic.html#p17603","post_id":"p17603","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:27","sort_key":"2015-09-13 00:27:00","excerpt":"Ок, не встревай меж двух огней, понял)"},{"doc_id":3496,"url":"../t130p250-topic.html#p17604","post_id":"p17604","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:29","sort_key":"2015-09-13 00:29:00","excerpt":"\"Давайте поговорим о вашем поведении.\" Даже страшновато стало) Сложно сказать о великом желании, не большой фанат срачей, как видишь. Пытаюсь немного все стабилизировать. Ну, что-то этаким Арли заменителем 2ого эшелона…"},{"doc_id":3497,"url":"../t130p250-topic.html#p17605","post_id":"p17605","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:32","sort_key":"2015-09-13 00:32:00","excerpt":"Обязательно побеседуем, Сундук. Но не раньше, чем ты начнешь соблюдать хотя бы базовую последовательность диспута."},{"doc_id":3498,"url":"../t130p275-topic.html#p17606","post_id":"p17606","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:32","sort_key":"2015-09-13 00:32:00","excerpt":"Правильней сказать \"арлиимитатором\"."},{"doc_id":3499,"url":"../t130p275-topic.html#p17607","post_id":"p17607","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:33","sort_key":"2015-09-13 00:33:00","excerpt":"Копировать кого-то - совершенно не мой стиль."},{"doc_id":3500,"url":"../t130p275-topic.html#p17608","post_id":"p17608","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:34","sort_key":"2015-09-13 00:34:00","excerpt":"Во-первых, прошу перестать называть меня \"Сундуком\", если уж речь зашла о минимальных приличиях. У меня ник есть, между прочим. Во-вторых - ю а велком. Но не сегодня и не в баре."},{"doc_id":3501,"url":"../t130p275-topic.html#p17609","post_id":"p17609","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:35","sort_key":"2015-09-13 00:35:00","excerpt":"Тем не менее, как бы я тут не выпендривался, мои работы во многом базированы на работах Арли, как минимум процентов на 15."},{"doc_id":3502,"url":"../t130p275-topic.html#p17610","post_id":"p17610","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:40","sort_key":"2015-09-13 00:40:00","excerpt":"Минимальные - шта?.. о приличиях заговорил человек, только за последнее время сравнивший меня с голубем, голословно обвинивший в тотальном неконструктиве и обозвавший аберрацией? :Д П.С. А копирование, между прочим, один…"},{"doc_id":3503,"url":"../t130p275-topic.html#p17611","post_id":"p17611","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:43","sort_key":"2015-09-13 00:43:00","excerpt":"Я имею ввиду, что при всё уважении и схожести нас, я всё таки я, как бы это очевидно ни было, а из вашего арсенала беру, что подходит, запчасти, как вы сами сказали, сэмпай."},{"doc_id":3504,"url":"../t130p275-topic.html#p17612","post_id":"p17612","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вс 13 Сен 2015 - 0:48","sort_key":"2015-09-13 00:48:00","excerpt":"Голословно, говоришь? Что, и фанатичное неприятие мнений, отличающихся от твоего, сюда тоже входит? Что касается \"голубя\"... ТЫ реально не видишь разницы между аллегорическим сравнением и прямым оскорблением? Я имею…"},{"doc_id":3505,"url":"../t130p275-topic.html#p17613","post_id":"p17613","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:53","sort_key":"2015-09-13 00:53:00","excerpt":"Коль битва в Славе треде будет проходить, то тоже буду присутствовать."},{"doc_id":3506,"url":"../t130p275-topic.html#p17614","post_id":"p17614","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 0:58","sort_key":"2015-09-13 00:58:00","excerpt":"Во-от, старый-добрый Сундук) И по уровню развития проехался, и по сленгу... И чем с тобой говорить можно, а? О погоде разве что да о котиках."},{"doc_id":3507,"url":"../t130p275-topic.html#p17615","post_id":"p17615","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 0:59","sort_key":"2015-09-13 00:59:00","excerpt":"О футболе ещё немного, а так же о моей бабуле)"},{"doc_id":3508,"url":"../t130p275-topic.html#p17616","post_id":"p17616","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 1:01","sort_key":"2015-09-13 01:01:00","excerpt":"И о жирных мамашах еще наверное :Д Ежли его еще немного потыкать - думаю и до такого скатится."},{"doc_id":3509,"url":"../t130p275-topic.html#p17617","post_id":"p17617","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 1:05","sort_key":"2015-09-13 01:05:00","excerpt":"Что-то мы сейчас под Т2 на 10 минуте зайдём)"},{"doc_id":3510,"url":"../t130p275-topic.html#p17618","post_id":"p17618","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 1:11","sort_key":"2015-09-13 01:11:00","excerpt":"Ой не напоминай -_- После того, как с 2500 на 2000 съехал, туда не ходок."},{"doc_id":3511,"url":"../t130p275-topic.html#p17619","post_id":"p17619","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вс 13 Сен 2015 - 1:12","sort_key":"2015-09-13 01:12:00","excerpt":"Лол, тяжело время)"},{"doc_id":3512,"url":"../t130p275-topic.html#p17631","post_id":"p17631","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вс 13 Сен 2015 - 22:57","sort_key":"2015-09-13 22:57:00","excerpt":"Олололо, унлы-мод в стиме. Интересно, тоже без спросу?"},{"doc_id":3513,"url":"../t130p275-topic.html#p17633","post_id":"p17633","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вс 13 Сен 2015 - 23:31","sort_key":"2015-09-13 23:31:00","excerpt":"Я прямого разрешения не давал, но не против в целом. Пускай. Правда, бл из стима убрали..."},{"doc_id":3514,"url":"../t130p275-topic.html#p17650","post_id":"p17650","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пн 14 Сен 2015 - 1:56","sort_key":"2015-09-14 01:56:00","excerpt":"Блин, день погромиста чуть не проспали! С праздником!:"},{"doc_id":3515,"url":"../t130p275-topic.html#p17665","post_id":"p17665","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Lansar_Skavana","posted_at":"Вт 15 Сен 2015 - 0:54","sort_key":"2015-09-15 00:54:00","excerpt":"Это еще почему? Риточка опять что то не поделил с Мунворксами?"},{"doc_id":3516,"url":"../t130p275-topic.html#p17666","post_id":"p17666","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 15 Сен 2015 - 1:00","sort_key":"2015-09-15 01:00:00","excerpt":"Да кто ж их знает, что у них там случилось. 7дл пишется на основе лета, а не подковёрной возни вовлечённых людей (="},{"doc_id":3517,"url":"../t130p275-topic.html#p17669","post_id":"p17669","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Вт 15 Сен 2015 - 1:22","sort_key":"2015-09-15 01:22:00","excerpt":"Да, вновь не поделил. Конкретно со Смолевым. Рита коммерчески реализовывал стикеры с персонажами в ВК, что другой части бывшей команды не понравилось. Ему предложили свернуть лавочку, но получили грубый отказ. Итог…"},{"doc_id":3518,"url":"../t130p275-topic.html#p17670","post_id":"p17670","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вт 15 Сен 2015 - 1:36","sort_key":"2015-09-15 01:36:00","excerpt":"Вор у вора дубину украл..."},{"doc_id":3519,"url":"../t130p275-topic.html#p17702","post_id":"p17702","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Вт 15 Сен 2015 - 22:30","sort_key":"2015-09-15 22:30:00","excerpt":"Если вкратце, то Максим \"Пожарник\" Смолев снова подорвался на ровном месте, а Мунворксы решили подхватить и, внезапно, впервые за полтора с лишним года, обнаружили что про них-то Рита почти не упоминет нигде! Ни в коем…"},{"doc_id":3520,"url":"../t130p275-topic.html#p17718","post_id":"p17718","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"navigator_zon","posted_at":"Ср 16 Сен 2015 - 10:48","sort_key":"2015-09-16 10:48:00","excerpt":"Мда, а пострадали как обычно игроки, которые юзали стим-версию."},{"doc_id":3521,"url":"../t130p275-topic.html#p17719","post_id":"p17719","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 16 Сен 2015 - 10:53","sort_key":"2015-09-16 10:53:00","excerpt":"А я всегда говорил, версия 1.2 — барахло, от которого проблем больше, чем пользы."},{"doc_id":3522,"url":"../t130p275-topic.html#p17750","post_id":"p17750","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"mannych","posted_at":"Ср 16 Сен 2015 - 20:33","sort_key":"2015-09-16 20:33:00","excerpt":"Все правильно они сделали... идея, персонажи, вся музыкальная и визуальная часть - работа мунворксов и их гнев в данном случае вполне понятен... Только вот конечно обидно, что такую хорошую новеллу окружают постоянные…"},{"doc_id":3523,"url":"../t130p300-topic.html#p17751","post_id":"p17751","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 16 Сен 2015 - 20:36","sort_key":"2015-09-16 20:36:00","excerpt":"Я вот тоже не понимал смысла, или кто-то так повёрнут на ачивках или лицензионных играх онли"},{"doc_id":3524,"url":"../t130p300-topic.html#p17752","post_id":"p17752","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 16 Сен 2015 - 21:07","sort_key":"2015-09-16 21:07:00","excerpt":"Так у нас тоже такие есть."},{"doc_id":3525,"url":"../t130p300-topic.html#p17753","post_id":"p17753","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 16 Сен 2015 - 21:27","sort_key":"2015-09-16 21:27:00","excerpt":"В смысле ачивок ? Я имел ввиду то что они отображаться будут в профиле на Стиме, кто-то же за ними охотится прям. Кто-то ради этого и покупает лицензионные игры, чтобы было чем хвастаться"},{"doc_id":3526,"url":"../t130p300-topic.html#p17754","post_id":"p17754","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 16 Сен 2015 - 21:31","sort_key":"2015-09-16 21:31:00","excerpt":"Просто другой причины, почему люди упорно играют в стимовскую версию, когда моды в основе своей выходят на 1.1, я не вижу"},{"doc_id":3527,"url":"../t130p300-topic.html#p17755","post_id":"p17755","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Ср 16 Сен 2015 - 21:34","sort_key":"2015-09-16 21:34:00","excerpt":"Creative Commons? Не, не слышали! В лучших традициях отечественной медиа-сферы, после достижения популярности продукта начинаются срачи об авторских правах. Я просто напомню, что Мунворксы во-первых прямым текстом…"},{"doc_id":3528,"url":"../t130p300-topic.html#p17756","post_id":"p17756","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Ср 16 Сен 2015 - 21:37","sort_key":"2015-09-16 21:37:00","excerpt":"Собственно, на 1.1 сейчас выходят только крупные моды и динозавры из числа тех, что начинали делаться задолго до стим-релиза (Саманта например). Плюс сам по себе воркшоп - крайне удобная площадка для распространения и…"},{"doc_id":3529,"url":"../t130p300-topic.html#p17758","post_id":"p17758","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 16 Сен 2015 - 22:13","sort_key":"2015-09-16 22:13:00","excerpt":"В смысле болезненного интереса к лицензиям."},{"doc_id":3530,"url":"../t130p300-topic.html#p17765","post_id":"p17765","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 17 Сен 2015 - 0:00","sort_key":"2015-09-17 00:00:00","excerpt":"Ааа, ну у каждого свои интересы. Не всем понятны они бывают, но на вкус и цвет, как говорится"},{"doc_id":3531,"url":"../t130p300-topic.html#p17766","post_id":"p17766","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 0:03","sort_key":"2015-09-17 00:03:00","excerpt":"Не, тот тащ, кажется, уже несколько сожалеет о своих инициативах."},{"doc_id":3532,"url":"../t130p300-topic.html#p17769","post_id":"p17769","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"mannych","posted_at":"Чт 17 Сен 2015 - 0:55","sort_key":"2015-09-17 00:55:00","excerpt":"От совет геймз открещивались, потому что в старом составе команда перестала существовать как таковая (в мунворкс воссоединились они позже), а брэнд остался за сценаристом... открещивались и когда БЛ была на пике…"},{"doc_id":3533,"url":"../t130p300-topic.html#p17790","post_id":"p17790","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Чт 17 Сен 2015 - 12:11","sort_key":"2015-09-17 12:11:00","excerpt":"Вот как раз где это самое \"фактическое присваивание\" я и не вижу - в паблике авторство указано, в стиме игра была опубликована от имени той команды, которая была на момент релиза. Зато я вижу размахивание кулаками после…"},{"doc_id":3534,"url":"../t130p300-topic.html#p17791","post_id":"p17791","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Элдхэнн","posted_at":"Чт 17 Сен 2015 - 12:47","sort_key":"2015-09-17 12:47:00","excerpt":"Я не утерпел и рещил высказаться. Господин Обидчивый, прекратите разговаривать с голосами в своей голове. Если не можете самостоятельно - обратитесь к специалистам, это не страшно и не больно."},{"doc_id":3535,"url":"../t130p300-topic.html#p17792","post_id":"p17792","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Чт 17 Сен 2015 - 12:58","sort_key":"2015-09-17 12:58:00","excerpt":"Быть может Господин Эксперт пояснит болезному где он не прав?"},{"doc_id":3536,"url":"../t130p300-topic.html#p17794","post_id":"p17794","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 13:24","sort_key":"2015-09-17 13:24:00","excerpt":"Не парься, это он мне. Никто меня не любит, вот и Элдхен тоже."},{"doc_id":3537,"url":"../t130p300-topic.html#p17795","post_id":"p17795","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"MoonkinBig","posted_at":"Чт 17 Сен 2015 - 13:48","sort_key":"2015-09-17 13:48:00","excerpt":"А за что тебя не любить? Ты клёвый и кошку пишешь."},{"doc_id":3538,"url":"../t130p300-topic.html#p17797","post_id":"p17797","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 14:12","sort_key":"2015-09-17 14:12:00","excerpt":"Не сошлись во мнениях по некоторым поводам. Пишу, кстати, не я, а Бегун с Перегарретом. На мне сценарий и логика."},{"doc_id":3539,"url":"../t130p300-topic.html#p17800","post_id":"p17800","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 17 Сен 2015 - 14:56","sort_key":"2015-09-17 14:56:00","excerpt":"И еще мощный положительный инструмент под названием Вето. Больше ни у кого такого нет!"},{"doc_id":3540,"url":"../t130p300-topic.html#p17801","post_id":"p17801","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 15:06","sort_key":"2015-09-17 15:06:00","excerpt":"А потому что вам волю дай - так вы Семёном весь лагерь перетрахаете."},{"doc_id":3541,"url":"../t130p300-topic.html#p17802","post_id":"p17802","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 17 Сен 2015 - 15:19","sort_key":"2015-09-17 15:19:00","excerpt":"Ну почему сразу - весь? Совёнка, Саныча и Толика, пожалуй, трогать не будем."},{"doc_id":3542,"url":"../t130p300-topic.html#p17803","post_id":"p17803","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 17 Сен 2015 - 16:08","sort_key":"2015-09-17 16:08:00","excerpt":"Семёну экстракт мартовского кота ввели ?"},{"doc_id":3543,"url":"../t130p300-topic.html#p17804","post_id":"p17804","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 16:18","sort_key":"2015-09-17 16:18:00","excerpt":"Не знаю, чего они ему там ввели, но бдить над текстами приходится неусыпно."},{"doc_id":3544,"url":"../t130p300-topic.html#p17805","post_id":"p17805","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Чт 17 Сен 2015 - 16:55","sort_key":"2015-09-17 16:55:00","excerpt":"Толик sexy and he know it!"},{"doc_id":3545,"url":"../t130p300-topic.html#p17806","post_id":"p17806","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 17:15","sort_key":"2015-09-17 17:15:00","excerpt":"Заметьте, ни про Шурика, ни про Эла он даже не заикнулся. Теперь вы понимаете, почему мне приходится со страшной силой бдеть?"},{"doc_id":3546,"url":"../t130p300-topic.html#p17807","post_id":"p17807","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 17 Сен 2015 - 17:38","sort_key":"2015-09-17 17:38:00","excerpt":"У Эла есть Женя, а у Шурика есть Маша и любимая арматурина. Они и сами справятся"},{"doc_id":3547,"url":"../t130p300-topic.html#p17808","post_id":"p17808","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Чт 17 Сен 2015 - 18:05","sort_key":"2015-09-17 18:05:00","excerpt":"Главное им не злоупотреблять . Речь Посполитая в своё время, в частности и от права \"Liberum veto\" на сейме любого делегата, загнулась."},{"doc_id":3548,"url":"../t130p325-topic.html#p17809","post_id":"p17809","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 18:09","sort_key":"2015-09-17 18:09:00","excerpt":"Пока что инциденты, повлёкшие за собой применение, можно пересчитать по пальцам одной руки."},{"doc_id":3549,"url":"../t130p325-topic.html#p17810","post_id":"p17810","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Чт 17 Сен 2015 - 18:13","sort_key":"2015-09-17 18:13:00","excerpt":"Чесс, а если на тебе сценарий, то получается коллеги партизанят втихую, отсебятину толкают?"},{"doc_id":3550,"url":"../t130p325-topic.html#p17811","post_id":"p17811","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 17 Сен 2015 - 18:39","sort_key":"2015-09-17 18:39:00","excerpt":"Ну кагбе если идея здравая, то отчего бы её не рассмотреть? Вот, например, тащ Бегун давеча предложил сценку в обход сценария, при внимательном изучении оказавшуюся более соответствующей стандартным реакциям участников с…"},{"doc_id":3551,"url":"../t130p325-topic.html#p17825","post_id":"p17825","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Константин Noir Сычев","posted_at":"Пт 18 Сен 2015 - 12:51","sort_key":"2015-09-18 12:51:00","excerpt":"Может кто-то ещё не видел. Косплей по БЛ на фестивале АкиБан 2015. Спойлер: Внешний embed: https://www.youtube.com/embed/asUAsuxhZAc"},{"doc_id":3552,"url":"../t130p325-topic.html#p17826","post_id":"p17826","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пт 18 Сен 2015 - 13:02","sort_key":"2015-09-18 13:02:00","excerpt":"Тот самый момент прозрения, когда посмотрел на заставочную картинку, и больше не надо (="},{"doc_id":3553,"url":"../t130p325-topic.html#p17831","post_id":"p17831","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пт 18 Сен 2015 - 20:33","sort_key":"2015-09-18 20:33:00","excerpt":"Юлификацию не остановить!:"},{"doc_id":3554,"url":"../t130p325-topic.html#p17863","post_id":"p17863","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Сб 19 Сен 2015 - 19:03","sort_key":"2015-09-19 19:03:00","excerpt":"Юля такого ужаса не вызывает ведь"},{"doc_id":3555,"url":"../t130p325-topic.html#p17864","post_id":"p17864","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Сб 19 Сен 2015 - 19:18","sort_key":"2015-09-19 19:18:00","excerpt":"Автор, пожалуй, самых сильных и атмосферных вещей оста 7дл, April Rain, оказывается, в курсе о существовании мода. Жаль, нет меня в этих ваших контактах, привет бы передал."},{"doc_id":3556,"url":"../t130p325-topic.html#p17866","post_id":"p17866","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Сб 19 Сен 2015 - 19:44","sort_key":"2015-09-19 19:44:00","excerpt":"Интернеты вещь вечно расширяющая своё влияние повсеместно."},{"doc_id":3557,"url":"../t130p325-topic.html#p17971","post_id":"p17971","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пн 21 Сен 2015 - 17:19","sort_key":"2015-09-21 17:19:00","excerpt":"Краткое содержание Унылко-ФЗ-рута и возможные сюжетные ветки:"},{"doc_id":3558,"url":"../t130p325-topic.html#p17976","post_id":"p17976","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Пн 21 Сен 2015 - 18:19","sort_key":"2015-09-21 18:19:00","excerpt":"Спойлеры, спойлеры кругом!"},{"doc_id":3559,"url":"../t130p325-topic.html#p17979","post_id":"p17979","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Пн 21 Сен 2015 - 18:43","sort_key":"2015-09-21 18:43:00","excerpt":"Простите, пожалуйста. Я не буду больше."},{"doc_id":3560,"url":"../t130p325-topic.html#p17987","post_id":"p17987","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Пн 21 Сен 2015 - 19:30","sort_key":"2015-09-21 19:30:00","excerpt":"ФЗ збс. Пока копался с транзитом - мимоходом еще больше проникся шиком идеи. Настолько блин типично и актуально- из-за одной обидки закатать драму на недельку."},{"doc_id":3561,"url":"../t130p325-topic.html#p17999","post_id":"p17999","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 20:21","sort_key":"2015-09-21 20:21:00","excerpt":"Так-с, Chess, я снова здесь. Вы говорите, что не мистика. Ну в моём понимании это не обычно, что человек попадает в другой мир || прошлое). И, пока я ещё не прошёл руты все, мне интересен один вопрос: Хорошие концовки…"},{"doc_id":3562,"url":"../t130p325-topic.html#p18000","post_id":"p18000","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пн 21 Сен 2015 - 20:52","sort_key":"2015-09-21 20:52:00","excerpt":"Заглянул сегодня на форум, а тут..."},{"doc_id":3563,"url":"../t130p325-topic.html#p18001","post_id":"p18001","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Пн 21 Сен 2015 - 20:53","sort_key":"2015-09-21 20:53:00","excerpt":"И моим зубом уже клянутся"},{"doc_id":3564,"url":"../t130p325-topic.html#p18002","post_id":"p18002","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 20:55","sort_key":"2015-09-21 20:55:00","excerpt":"Уж прости, не изучил ещё столько материала, чтобы понять для себя только по пройденному Мику-руту"},{"doc_id":3565,"url":"../t130p325-topic.html#p18003","post_id":"p18003","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 21 Сен 2015 - 21:02","sort_key":"2015-09-21 21:02:00","excerpt":"Негромкое бубнение с заднего ряда зала. С точки зрения \"может быть, не может\" в личном хит-параде на первом месте, как самая реальная, стоит \"Тульпа\"."},{"doc_id":3566,"url":"../t130p325-topic.html#p18004","post_id":"p18004","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 21:03","sort_key":"2015-09-21 21:03:00","excerpt":"А что не глубина?)"},{"doc_id":3567,"url":"../t130p325-topic.html#p18005","post_id":"p18005","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 21 Сен 2015 - 21:06","sort_key":"2015-09-21 21:06:00","excerpt":"Я же говорю \"личном\". Ну вот так оно у меня сошлось."},{"doc_id":3568,"url":"../t130p325-topic.html#p18006","post_id":"p18006","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 21:07","sort_key":"2015-09-21 21:07:00","excerpt":"Меня больше интересует эта мысль автора Никак не могу понять, что она значит. Ведь если так рассуждать, то и Семён в лагере и Семён в жизни это 2 разных человека"},{"doc_id":3569,"url":"../t130p325-topic.html#p18010","post_id":"p18010","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Пн 21 Сен 2015 - 21:41","sort_key":"2015-09-21 21:41:00","excerpt":"Уважаемый co1lector, вот как я вижу эту ситуацию касательно истинной концовки Мику. Там у Виолы фраза идёт \"в твоём мире она программа, в её - ты это одно из названий шизофрении\". И дальше идёт текст, что складывается…"},{"doc_id":3570,"url":"../t130p325-topic.html#p18012","post_id":"p18012","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Пн 21 Сен 2015 - 22:09","sort_key":"2015-09-21 22:09:00","excerpt":"Ну у меня тоже создавалось впечатление, что всё, что происходит - это просто предсмертная иллюзия его, не более. Но автор опроверг это"},{"doc_id":3571,"url":"../t130p325-topic.html#p18041","post_id":"p18041","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:11","sort_key":"2015-09-22 20:11:00","excerpt":"Скажите, а НФ вы тоже к мистике относите? Вы ведь наверняка даже на низкой орбите не были, не говоря уж о других системах. А по поводу \"иллюзия - не иллюзия\"... Дайте чёткое определение объективной реальности для начала…"},{"doc_id":3572,"url":"../t130p325-topic.html#p18042","post_id":"p18042","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 20:17","sort_key":"2015-09-22 20:17:00","excerpt":"А \"хорошие\" - это какие? А ещё - это когда? Если следствие \"хорошей концовки\" - полная задница, она продолжает быть хорошей?"},{"doc_id":3573,"url":"../t130p350-topic.html#p18043","post_id":"p18043","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 20:18","sort_key":"2015-09-22 20:18:00","excerpt":"А вселенная - песчинка в кошачем латке огромного, вселенского кота, однако здравствуй, Чесс)"},{"doc_id":3574,"url":"../t130p350-topic.html#p18044","post_id":"p18044","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:19","sort_key":"2015-09-22 20:19:00","excerpt":"Хорошие, это которые автор посчитал хорошими и они называются \"гуд\" или иногда \"нейтрал\")"},{"doc_id":3575,"url":"../t130p350-topic.html#p18045","post_id":"p18045","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 20:20","sort_key":"2015-09-22 20:20:00","excerpt":"Ну... это всего-лишь условные обозначения, чтобы отличать одну от другой."},{"doc_id":3576,"url":"../t130p350-topic.html#p18046","post_id":"p18046","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:20","sort_key":"2015-09-22 20:20:00","excerpt":"Ну я в этом предназначении их и использую)"},{"doc_id":3577,"url":"../t130p350-topic.html#p18047","post_id":"p18047","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:22","sort_key":"2015-09-22 20:22:00","excerpt":"Мистика и фантастика для меня синонимы, к сожалению. Объективной реальностью в моде я считаю реальность пролога)"},{"doc_id":3578,"url":"../t130p350-topic.html#p18048","post_id":"p18048","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:26","sort_key":"2015-09-22 20:26:00","excerpt":"Сам привет. Вот не нужно сюда Больцмановский мозг приплетать, это антинаучно. © А на каком, простите, основании? И, повторюсь, тебе не кажется странным обыкновение Семёна прокручивать перед сном произошедшее за день и…"},{"doc_id":3579,"url":"../t130p350-topic.html#p18049","post_id":"p18049","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 20:29","sort_key":"2015-09-22 20:29:00","excerpt":"Угу. Т.е если я умею замечать спонтанные \"прыжки\" по реальностям, умею \"прыгать\" по своему желанию по ближайшим реальностям, да ещё и таскаю при этом с собой других - это уже не объективные реальности?"},{"doc_id":3580,"url":"../t130p350-topic.html#p18050","post_id":"p18050","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:32","sort_key":"2015-09-22 20:32:00","excerpt":"Потому что она изначальная, основа. По-крайней мере я просто взял её за истинную, как и Семён. А второе.. Прости, я не такой великий фантаст, как ты. Да и сам перед сном обдумываю произошедшие события, странным это мне…"},{"doc_id":3581,"url":"../t130p350-topic.html#p18051","post_id":"p18051","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 20:33","sort_key":"2015-09-22 20:33:00","excerpt":"Думаю, что девочка-кошка в советском лагере 87 года, куда попадают сычи и сценаристы, а так же наполненный девочками, с весьма яркими архетипами. Хотя, если брать твою теорию, что всё - иллюзия, то вполне реально, что…"},{"doc_id":3582,"url":"../t130p350-topic.html#p18052","post_id":"p18052","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:34","sort_key":"2015-09-22 20:34:00","excerpt":"Напрямую не могу, обещался Автору молчать, как рыба об лёд. Попробуй представить ситуацию, когда Семёну вечерние-утренние воспоминания необходимы просто-таки жизненно. То же и Штейна касается, кстати."},{"doc_id":3583,"url":"../t130p350-topic.html#p18053","post_id":"p18053","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:36","sort_key":"2015-09-22 20:36:00","excerpt":"В голову приходят только мысли о Сохранении -> Загрузке, но что-то я заигрался"},{"doc_id":3584,"url":"../t130p350-topic.html#p18054","post_id":"p18054","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:38","sort_key":"2015-09-22 20:38:00","excerpt":"Мысли не очень правильные, но ты на верном пути, скажем так."},{"doc_id":3585,"url":"../t130p350-topic.html#p18055","post_id":"p18055","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 20:40","sort_key":"2015-09-22 20:40:00","excerpt":"О, психология бессознательного сейчас пойдёт) Шуточка)"},{"doc_id":3586,"url":"../t130p350-topic.html#p18056","post_id":"p18056","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:40","sort_key":"2015-09-22 20:40:00","excerpt":"Такими темпами до финиша дойду, когда уже в релизе вся истинна открытым текстом будет) Может они ему необходимы, чтобы он не запутался в реальностях, ведь в каждой своя жизнь у него)"},{"doc_id":3587,"url":"../t130p350-topic.html#p18057","post_id":"p18057","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:43","sort_key":"2015-09-22 20:43:00","excerpt":"И ещё одна очень правильная мысль. Нужно только всё вместе увязать."},{"doc_id":3588,"url":"../t130p350-topic.html#p18058","post_id":"p18058","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 20:47","sort_key":"2015-09-22 20:47:00","excerpt":"Чесс, не уж то и ты решил себе протеже взять?)"},{"doc_id":3589,"url":"../t130p350-topic.html#p18059","post_id":"p18059","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 20:48","sort_key":"2015-09-22 20:48:00","excerpt":"А какой \"сейв\" тогда крайний? Выходит что он где-то за прологом, за выбором характера"},{"doc_id":3590,"url":"../t130p350-topic.html#p18060","post_id":"p18060","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 20:49","sort_key":"2015-09-22 20:49:00","excerpt":"Или далеко копаю"},{"doc_id":3591,"url":"../t130p350-topic.html#p18061","post_id":"p18061","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:52","sort_key":"2015-09-22 20:52:00","excerpt":"Тяжело очень, эх сейчас бы спойлеров в 2015"},{"doc_id":3592,"url":"../t130p350-topic.html#p18062","post_id":"p18062","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:53","sort_key":"2015-09-22 20:53:00","excerpt":"Чего? В смысле? Зачем оно мне? Вот ещё одна догадка, которая приближает тебя к пониманию истинной подоплеке происходящего. И, прошу заметить, человек сам догадался, я ничего не сливал."},{"doc_id":3593,"url":"../t130p350-topic.html#p18063","post_id":"p18063","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 20:55","sort_key":"2015-09-22 20:55:00","excerpt":"А почему ты так уверен, что в реальности Семёна есть место следующему году?"},{"doc_id":3594,"url":"../t130p350-topic.html#p18064","post_id":"p18064","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 20:59","sort_key":"2015-09-22 20:59:00","excerpt":"Да это к слову, а не по теме Видимо, моя фантазия не позволяет мне угадать истинну, не понял я оснований и для этого"},{"doc_id":3595,"url":"../t130p350-topic.html#p18065","post_id":"p18065","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 21:04","sort_key":"2015-09-22 21:04:00","excerpt":"Каждый раз начинается всё с предыстории, и заканчивается в финале, который Семён себе сам выстроил, на основе того происходило с ним в лагере. А если ещё и события лагеря строит тоже его разум, то ... Он так не сможет…"},{"doc_id":3596,"url":"../t130p350-topic.html#p18066","post_id":"p18066","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:07","sort_key":"2015-09-22 21:07:00","excerpt":"Т.е. для него и мир из пролога не изначальный? Ну к этому вроде как отсылок нет в сюжете. Или я опять недопонимаю. Вообще в Труъ концовке говорится, что пока он в этих мирах, или проще эти миры создаёт его мозг(самая…"},{"doc_id":3597,"url":"../t130p350-topic.html#p18067","post_id":"p18067","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:07","sort_key":"2015-09-22 21:07:00","excerpt":"Draug, ты даже не представляешь, насколько ты прав и не прав одновременно. Очень жаль, что мои намёки на вечер-утро так и не были всесторонне рассмотрены."},{"doc_id":3598,"url":"../t130p375-topic.html#p18068","post_id":"p18068","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:10","sort_key":"2015-09-22 21:10:00","excerpt":"Тяжёлые намёки. По крайней мере для меня)"},{"doc_id":3599,"url":"../t130p375-topic.html#p18069","post_id":"p18069","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 21:13","sort_key":"2015-09-22 21:13:00","excerpt":"Вот обдумываю что это может значить, пока не особо получается."},{"doc_id":3600,"url":"../t130p375-topic.html#p18070","post_id":"p18070","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:15","sort_key":"2015-09-22 21:15:00","excerpt":"А я гадаю, то ли у меня карт меньше(т.к. я только Мику-рут прошёл), чтоб догадаться, то ли воображения нет"},{"doc_id":3601,"url":"../t130p375-topic.html#p18071","post_id":"p18071","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:16","sort_key":"2015-09-22 21:16:00","excerpt":"Намёки вполне себе прозрачные на самом деле, нужно только уложить в голове уже основные сюжетки готовых рутов. Разжёвывания от автора вы всё равно не увидите до выхода \"Третьего Дня\"."},{"doc_id":3602,"url":"../t130p375-topic.html#p18072","post_id":"p18072","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:21","sort_key":"2015-09-22 21:21:00","excerpt":"Мы пытаемся выпытать из тебя Ну вот как Drag про прологи догадался. По-моему это читатель, а не Семён, пытается что-то узнать и рестартается"},{"doc_id":3603,"url":"../t130p375-topic.html#p18073","post_id":"p18073","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:23","sort_key":"2015-09-22 21:23:00","excerpt":"Ну, не знаю, может преподавательские амбиции заиграли, может близкий по духу человек, а может даже ( Сэмпай сейчас со стула полетит, при прочтении) ты решил немного альтруизма и благодетели проявить?)"},{"doc_id":3604,"url":"../t130p375-topic.html#p18074","post_id":"p18074","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:26","sort_key":"2015-09-22 21:26:00","excerpt":"Просто хочу прояснить для читателей некоторые моменты. Ну и пища для раз мыш лений, куда без неё. То есть мы опять приходим к концепции \"сон кота\"?"},{"doc_id":3605,"url":"../t130p375-topic.html#p18075","post_id":"p18075","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:28","sort_key":"2015-09-22 21:28:00","excerpt":"Ну, и то хорошо, кошку ждать к зиме или позже?"},{"doc_id":3606,"url":"../t130p375-topic.html#p18076","post_id":"p18076","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 21:32","sort_key":"2015-09-22 21:32:00","excerpt":"А сны котов связаны, пойду своих кошек спрашивать"},{"doc_id":3607,"url":"../t130p375-topic.html#p18077","post_id":"p18077","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:33","sort_key":"2015-09-22 21:33:00","excerpt":"Кошочка незримо стоит за плечом каждого читателя, посягнувшего на её рут. Обрати внимание на своё окружение, прислушивайсо к шорохам в ночи, запоминай сны. Кхм, чо-то меня понесло, пардон. Рут постараемся до конца осени…"},{"doc_id":3608,"url":"../t130p375-topic.html#p18078","post_id":"p18078","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:37","sort_key":"2015-09-22 21:37:00","excerpt":""},{"doc_id":3609,"url":"../t130p375-topic.html#p18079","post_id":"p18079","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:39","sort_key":"2015-09-22 21:39:00","excerpt":""},{"doc_id":3610,"url":"../t130p375-topic.html#p18080","post_id":"p18080","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 21:41","sort_key":"2015-09-22 21:41:00","excerpt":"Мой мозг на сне кошечки сдал позиции, моя Славя потребовала чтобы я шел спать. Она такая заботливая"},{"doc_id":3611,"url":"../t130p375-topic.html#p18081","post_id":"p18081","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:42","sort_key":"2015-09-22 21:42:00","excerpt":""},{"doc_id":3612,"url":"../t130p375-topic.html#p18082","post_id":"p18082","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:44","sort_key":"2015-09-22 21:44:00","excerpt":"Передай внутренней Славе, что она неправа - тема обширная и благодатнейшая. А \"сон кота\" - это так, лёгкое проявление солипсизма, не более."},{"doc_id":3613,"url":"../t130p375-topic.html#p18083","post_id":"p18083","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:45","sort_key":"2015-09-22 21:45:00","excerpt":"Штейн, так я и не утверждал, что в рекламе столетней давности принимал участие Стетхем. Это ты его запостил, теперь пожинай."},{"doc_id":3614,"url":"../t130p375-topic.html#p18084","post_id":"p18084","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:47","sort_key":"2015-09-22 21:47:00","excerpt":"Ой, сейчас ещё и до темы вайфу и тульп дойдём, хотя, насколько я помню, у Драуга всё хорошо и нет таких проблем)"},{"doc_id":3615,"url":"../t130p375-topic.html#p18085","post_id":"p18085","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:48","sort_key":"2015-09-22 21:48:00","excerpt":"Да я просто так его постю. Не, пожинать Стетхема - опасно. Я ещё с первого \"Адреланиа\" это понял)"},{"doc_id":3616,"url":"../t130p375-topic.html#p18086","post_id":"p18086","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:53","sort_key":"2015-09-22 21:53:00","excerpt":"С прискорбием отмечаю, что серьёзная тема обсуждения вариантов реальности с точки зрения протагониста скатилась до картиночек. Лично я опечален, в очередной раз убедился, что истина никого не интересует, а интересуют…"},{"doc_id":3617,"url":"../t130p375-topic.html#p18087","post_id":"p18087","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:55","sort_key":"2015-09-22 21:55:00","excerpt":"Ну я не участвовал в пересылке картиночками и по прежнему очень интересует истина. Но намёков не хватает мне, извини, не дорос."},{"doc_id":3618,"url":"../t130p375-topic.html#p18088","post_id":"p18088","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:55","sort_key":"2015-09-22 21:55:00","excerpt":"Ой, да ладно тебе, прости, коль обидел, я же так, шутя. Просто я не в теме, а Драуг покинул танцпол."},{"doc_id":3619,"url":"../t130p375-topic.html#p18089","post_id":"p18089","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 21:56","sort_key":"2015-09-22 21:56:00","excerpt":"Это я свою девушку называю Славей (только ей слышать не надо это) В её реальности я не сомневаюсь, если только сон кошечки таки правда"},{"doc_id":3620,"url":"../t130p375-topic.html#p18090","post_id":"p18090","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 21:58","sort_key":"2015-09-22 21:58:00","excerpt":"Может быть ты просто не можешь вспомнить, что на самом деле попал сюда не случайно и ты здесь не просто так"},{"doc_id":3621,"url":"../t130p375-topic.html#p18091","post_id":"p18091","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:58","sort_key":"2015-09-22 21:58:00","excerpt":"Эта, тащи... Я уже столько нанамёкивал, что меня даже Автор в личку попенял за излишнюю прозрачность. Извиняйте, дальше сами."},{"doc_id":3622,"url":"../t130p375-topic.html#p18092","post_id":"p18092","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 21:59","sort_key":"2015-09-22 21:59:00","excerpt":"Драуг не покинул танцпол"},{"doc_id":3623,"url":"../t130p400-topic.html#p18093","post_id":"p18093","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 21:59","sort_key":"2015-09-22 21:59:00","excerpt":"И очередная глубокая мысль, почти соответствующая общему концепту. Не хватает буквально кошочкиного коготка."},{"doc_id":3624,"url":"../t130p400-topic.html#p18094","post_id":"p18094","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 21:59","sort_key":"2015-09-22 21:59:00","excerpt":"А думаешь, что если вспомнишь, то легче станет? Как бы не так. Вспомнить мало. Отсель ещё и выбраться надо."},{"doc_id":3625,"url":"../t130p400-topic.html#p18095","post_id":"p18095","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 22:01","sort_key":"2015-09-22 22:01:00","excerpt":"Выбраться - дело десятое. Для начала нужно понять, кто есть Семён в мире \"Совёнка\". И да, это очередной намёк."},{"doc_id":3626,"url":"../t130p400-topic.html#p18096","post_id":"p18096","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 22 Сен 2015 - 22:03","sort_key":"2015-09-22 22:03:00","excerpt":"Ай, я только допёр, что вы не по солипсизму в целом, а касательно рута идёте, понтятненько. Просто солипсизм - не моё."},{"doc_id":3627,"url":"../t130p400-topic.html#p18097","post_id":"p18097","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 22:03","sort_key":"2015-09-22 22:03:00","excerpt":"А фиг ли понимать? Ключевая фигура, вокруг которой всё вертится и благодаря которой вообще \"Совёнок\" существует. Это в книжке выбраться дело десятое, а в реале - ой как не просто."},{"doc_id":3628,"url":"../t130p400-topic.html#p18098","post_id":"p18098","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Вт 22 Сен 2015 - 22:05","sort_key":"2015-09-22 22:05:00","excerpt":"Я ещё тут, но мне нужно спать Всё таки надо, иначе я к вам прийду компьютерным призраком в итоге, всем удачи и соглашайтесь пойти с ней. Или нет."},{"doc_id":3629,"url":"../t130p400-topic.html#p18100","post_id":"p18100","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:06","sort_key":"2015-09-22 22:06:00","excerpt":"\"Нет\" - это самый простой рут. Не мучал бы себя размышлениями сейчас"},{"doc_id":3630,"url":"../t130p400-topic.html#p18101","post_id":"p18101","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 22:08","sort_key":"2015-09-22 22:08:00","excerpt":"Не проблема. Придёшь призраком - отправим назад."},{"doc_id":3631,"url":"../t130p400-topic.html#p18102","post_id":"p18102","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:10","sort_key":"2015-09-22 22:10:00","excerpt":"По-моему вся наша концепция идёт в разрознь с ТруЪ концовкой Мику, а ведь та по словам автора объясняет истинну частично"},{"doc_id":3632,"url":"../t130p400-topic.html#p18103","post_id":"p18103","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 22:11","sort_key":"2015-09-22 22:11:00","excerpt":"Да не циклись ты на отдельных концовках. Смотри картинку в общем."},{"doc_id":3633,"url":"../t130p400-topic.html#p18104","post_id":"p18104","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:12","sort_key":"2015-09-22 22:12:00","excerpt":"В общем можно судить, что нет истинной реальности"},{"doc_id":3634,"url":"../t130p400-topic.html#p18105","post_id":"p18105","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 22 Сен 2015 - 22:12","sort_key":"2015-09-22 22:12:00","excerpt":"\"Моя Мику\" позволяет посмотреть на ситуацию чуть выше, со следующего этажа. Но кто сказал, что оттуда видно картину целиком? И кто сказал, что этот этаж - самый верхний?"},{"doc_id":3635,"url":"../t130p400-topic.html#p18106","post_id":"p18106","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:14","sort_key":"2015-09-22 22:14:00","excerpt":"Я думал, что хотя бы слова Виолы верны"},{"doc_id":3636,"url":"../t130p400-topic.html#p18107","post_id":"p18107","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 22:15","sort_key":"2015-09-22 22:15:00","excerpt":"Какие именно? Она много чего говорит."},{"doc_id":3637,"url":"../t130p400-topic.html#p18108","post_id":"p18108","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:18","sort_key":"2015-09-22 22:18:00","excerpt":"О том, что тело в его мире(мире Пролога будем считать) медленно умирает. Значит, просто вернуться в свой мир на 15 минут раньше допустим он не может, раз она говорит так, ведь он так уже делал, но видимо это были другие…"},{"doc_id":3638,"url":"../t130p400-topic.html#p18109","post_id":"p18109","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Вт 22 Сен 2015 - 22:18","sort_key":"2015-09-22 22:18:00","excerpt":"Почитай чего-нибудь про теорию Мультиверсума Хью Эверетта III. Реальностей дофига и все истинные. Просто в каждой раскручивается какой-то аспект. Другой разговор - кому всё это нужно..."},{"doc_id":3639,"url":"../t130p400-topic.html#p18110","post_id":"p18110","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 22:20","sort_key":"2015-09-22 22:20:00","excerpt":"Скажем так, Виола слегка не в курсе всего происходящего."},{"doc_id":3640,"url":"../t130p400-topic.html#p18111","post_id":"p18111","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вт 22 Сен 2015 - 22:20","sort_key":"2015-09-22 22:20:00","excerpt":"Шонену с суперпавой, конечно же!"},{"doc_id":3641,"url":"../t130p400-topic.html#p18112","post_id":"p18112","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 22:21","sort_key":"2015-09-22 22:21:00","excerpt":"[quote=\"Arlien\"] Вот из этого лично я понял только последние два слова."},{"doc_id":3642,"url":"../t130p400-topic.html#p18113","post_id":"p18113","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:22","sort_key":"2015-09-22 22:22:00","excerpt":"Немного вкурсе, судя по их разговору"},{"doc_id":3643,"url":"../t130p400-topic.html#p18114","post_id":"p18114","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 22 Сен 2015 - 22:23","sort_key":"2015-09-22 22:23:00","excerpt":"Вообще, честно говоря, она вообще не в курсе даже в кошкоруте. Просто интерпретирует события под себя."},{"doc_id":3644,"url":"../t130p400-topic.html#p18115","post_id":"p18115","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:26","sort_key":"2015-09-22 22:26:00","excerpt":"Очень интересно. Но, благодаря ей, у меня хотя бы укладывающаяся в голове идея появилась насчёт этого всего) Всё очень просто: Семён умирает, мозг перед смертью ему создаёт иллюзии лагерей, возвращений и т.п."},{"doc_id":3645,"url":"../t130p400-topic.html#p18116","post_id":"p18116","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 22 Сен 2015 - 22:29","sort_key":"2015-09-22 22:29:00","excerpt":"Если брать оценку товарища co1lector как среднюю по палате - что ж, не зря пишу, значит! Удалось добиться требуемого эффекта."},{"doc_id":3646,"url":"../t130p400-topic.html#p18117","post_id":"p18117","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:31","sort_key":"2015-09-22 22:31:00","excerpt":"Ну эта версия мне пришла сразу, как закончил рут. Вполне логичная и объясняемая. Но для Chess, я думаю, слишком простая Но зато никаких аспектов ей не противоречит. А что за эффект, если не секрет?"},{"doc_id":3647,"url":"../t130p400-topic.html#p18118","post_id":"p18118","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 22 Сен 2015 - 22:37","sort_key":"2015-09-22 22:37:00","excerpt":"Не секрет. Банальность. История Мику и Семёна - далеко не единственная, что происходит в лагере. А всё вместе создаёт общую картину. На которую со временем можно будет взглянуть."},{"doc_id":3648,"url":"../t130p425-topic.html#p18119","post_id":"p18119","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 22:40","sort_key":"2015-09-22 22:40:00","excerpt":"Но моя то версия про сюжет - дикая банальность. До такой смогут чуть меньше чем все дотянуть"},{"doc_id":3649,"url":"../t130p425-topic.html#p18120","post_id":"p18120","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 22 Сен 2015 - 23:03","sort_key":"2015-09-22 23:03:00","excerpt":"А большего на данном этапе и не требуется. На вопросы ответили? Чек. Историю закрыли? Чек. На грядущее развитие и кросс-отсылки из других рутов намекнули? Тоже в наличии. Теперь можно добивать 7дл-круг и садиться…"},{"doc_id":3650,"url":"../t130p425-topic.html#p18121","post_id":"p18121","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Вт 22 Сен 2015 - 23:06","sort_key":"2015-09-22 23:06:00","excerpt":"Не сказать, что историю закрыли Chess то тут явно намекал не на эту версию. Ну а текущая история по твоей задумке именно такая?"},{"doc_id":3651,"url":"../t130p425-topic.html#p18128","post_id":"p18128","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 0:15","sort_key":"2015-09-23 00:15:00","excerpt":"Семён смирился с условиями и вышел на циклические каникулы с Мику? Да, эпизод закрыт. Нужно что-то ещё?"},{"doc_id":3652,"url":"../t130p425-topic.html#p18131","post_id":"p18131","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 0:36","sort_key":"2015-09-23 00:36:00","excerpt":"Славя-5 - абсолютный топ OBNOV по коментам. Самый Сложный Рут, воистину."},{"doc_id":3653,"url":"../t130p425-topic.html#p18132","post_id":"p18132","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 0:41","sort_key":"2015-09-23 00:41:00","excerpt":"Стараемся репортить, спорим, высказываем мнение... Работа кипит, значит!"},{"doc_id":3654,"url":"../t130p425-topic.html#p18133","post_id":"p18133","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 0:45","sort_key":"2015-09-23 00:45:00","excerpt":"Угумс. А эпилог небось и еще больше комментариев соберет - будет легитимный повод ворчать за стратегические моменты, которые можно будет оценить во всей полноте."},{"doc_id":3655,"url":"../t130p425-topic.html#p18134","post_id":"p18134","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 0:46","sort_key":"2015-09-23 00:46:00","excerpt":"Ну, историю не закрыли, мягко говоря Раз уж с циклами и с реальностями, значит не закрыли"},{"doc_id":3656,"url":"../t130p425-topic.html#p18135","post_id":"p18135","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 1:20","sort_key":"2015-09-23 01:20:00","excerpt":"И 90% из них это багрепы (= Рут действительно сложный. Для меня."},{"doc_id":3657,"url":"../t130p425-topic.html#p18136","post_id":"p18136","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 1:31","sort_key":"2015-09-23 01:31:00","excerpt":"Потому и багрепы, что сложный) Но зато теперь 7ДЛ может похватстаться первым подключенным с обоих концов и рабочим транзитом! Веха!"},{"doc_id":3658,"url":"../t130p425-topic.html#p18137","post_id":"p18137","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 2:07","sort_key":"2015-09-23 02:07:00","excerpt":"Перечитываю Лена-рут. Даже там Мику-закольцовку (\"С новым счастьем!\") обнаружил в рисунках Лены... Всё очень сложно, и потому приятно находится в томительном ожидании тех самых ответов."},{"doc_id":3659,"url":"../t130p425-topic.html#p18138","post_id":"p18138","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 2:12","sort_key":"2015-09-23 02:12:00","excerpt":"Ещё есть один задуманный, но недоделанный транзит с Мику-классика. И да, ФЗ-рут пока что под галочкой и не работает."},{"doc_id":3660,"url":"../t130p425-topic.html#p18139","post_id":"p18139","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 2:32","sort_key":"2015-09-23 02:32:00","excerpt":"Он не недоделанный, он безжалостно зарезанный, ввиду зашкаливающей... зашкаливающего... Гхррр! *злобно пыхтит* А еще, раз уж историю помянули, был в 7ДЛ-Славе один весьма изящный на Леночку. Жаль, что с концами уехал и…"},{"doc_id":3661,"url":"../t130p425-topic.html#p18140","post_id":"p18140","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 2:41","sort_key":"2015-09-23 02:41:00","excerpt":"Хех. Да, видел я сие чудо из чудес. Специально в древних версиях нашёл - поужасался. После такой сцены плюнул бы на Славю и радостно транзитировался до Лены. Мозги насиловать самой себе и окружающим, как раз Лене больше…"},{"doc_id":3662,"url":"../t130p425-topic.html#p18141","post_id":"p18141","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 3:02","sort_key":"2015-09-23 03:02:00","excerpt":"Детали да, сомнительные, но сам зачин красивый и равновесный, без правых и виноватых. Леночке нужен друг? Нужен. Чревата такая дружба? Еще как. Сравните с теми же Мику-транзитами. 7ДЛ - на основании труселей, классик…"},{"doc_id":3663,"url":"../t130p425-topic.html#p18142","post_id":"p18142","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 3:11","sort_key":"2015-09-23 03:11:00","excerpt":"Ну труселя-то - повод для ревности некислый, но с них транзитироваться - очень странно (да ещё теперь и на 7ДЛ-Славю). А Мику-класс, похоже, очень хорошо, что я не видел (ну его лишний раз печалится). С ФЗ самые красивые…"},{"doc_id":3664,"url":"../t130p425-topic.html#p18143","post_id":"p18143","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 3:21","sort_key":"2015-09-23 03:21:00","excerpt":"Та не думаю, что на плохие - есть догадка, что тащ автор просто транформатор ЛП выставить забыл, а теперь отшучивается :Д В крайнем случае - можно будет полемизировать. А вот насчет Славя-бэда... Есть догадка, что Семена…"},{"doc_id":3665,"url":"../t130p425-topic.html#p18144","post_id":"p18144","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 3:38","sort_key":"2015-09-23 03:38:00","excerpt":"Механика новых переменных хороша, и правильно что в д5 Слави убрали одно лишнее СП, позволявшее выйти на хентайчик вечером. Чувствую, что хентай ранний до добра не доведёт. Но при этом странно, что чтобы выйти на него…"},{"doc_id":3666,"url":"../t130p425-topic.html#p18145","post_id":"p18145","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 4:03","sort_key":"2015-09-23 04:03:00","excerpt":"А я от энтой механики чет не в восторге... Ну серьезно, на каком еще руте разного рода забиения болта на пассию - это не фейл и верный путь в самый бэдовый бэд-энд, а всячески поощряемая часть геймплея? Ладно, допустим…"},{"doc_id":3667,"url":"../t130p425-topic.html#p18147","post_id":"p18147","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 4:29","sort_key":"2015-09-23 04:29:00","excerpt":"Может и подозрительно - будем посмотреть. На самом деле, если отбросить факт того, что это Славя, совсем тряпка-кун мало кому нужен с т.з. романтических отношений. Пока набор СП у Герка мне совсем не кажется плохим: де…"},{"doc_id":3668,"url":"../t130p425-topic.html#p18148","post_id":"p18148","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 4:44","sort_key":"2015-09-23 04:44:00","excerpt":"Ну для Локи проблемы тут совершенно правильны - Локи существо несистемное, ему сойтись с человеком, пляшушим от системы, и должно быть сложней всего. Дрищ меня беспокоит - СП у него в минус, кажется, уезжают. если вести…"},{"doc_id":3669,"url":"../t130p425-topic.html#p18149","post_id":"p18149","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 7:45","sort_key":"2015-09-23 07:45:00","excerpt":"Просто цитата из Пратчетта: Настоящий кот мечтает об одном: прожить жизнь безмятежно и чтобы люди поменьше в нее вмешивались. В этом он не слишком отличается от людей."},{"doc_id":3670,"url":"../t130p425-topic.html#p18152","post_id":"p18152","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 10:14","sort_key":"2015-09-23 10:14:00","excerpt":"Оно, очевидно, для него и должно быть проблемным. Но фишка в том, как это будет на выходе смотреться - не слишком ли ГГ, радикально забивая болт на Славю или ругаясь с ней ради СП, переборщит в глазах читателей. По…"},{"doc_id":3671,"url":"../t130p425-topic.html#p18153","post_id":"p18153","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 11:04","sort_key":"2015-09-23 11:04:00","excerpt":"Ну я так и знал, что всё очередным Славявя-срачем закончится..."},{"doc_id":3672,"url":"../t130p425-topic.html#p18155","post_id":"p18155","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 12:08","sort_key":"2015-09-23 12:08:00","excerpt":"Да норм всё будет. Всего лишь критические точки рута с Арли заранее проговорили, чтобы знать куда обращать внимание. Здоровые правки сделаем, и рут взлетит. Главное - избежать норкомании. Например такой:"},{"doc_id":3673,"url":"../t130p450-topic.html#p18158","post_id":"p18158","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 12:45","sort_key":"2015-09-23 12:45:00","excerpt":"Главное - чтобы упомянутый тобой тащ не пеногенерировал больше на любую мелочь, отличающуюся от его видения Идеала™."},{"doc_id":3674,"url":"../t130p450-topic.html#p18160","post_id":"p18160","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 13:15","sort_key":"2015-09-23 13:15:00","excerpt":"Давайте не будем устраивать на пустом месте перепалку. Пока судить не о чем - нам уж точно спорить в своём видении смысла нет. Мнение любое важно, тем более что здесь каждый пытается аргументировать свою позицию. \"В…"},{"doc_id":3675,"url":"../t130p450-topic.html#p18161","post_id":"p18161","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Ср 23 Сен 2015 - 13:17","sort_key":"2015-09-23 13:17:00","excerpt":"Да как так-то?!"},{"doc_id":3676,"url":"../t130p450-topic.html#p18162","post_id":"p18162","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 14:01","sort_key":"2015-09-23 14:01:00","excerpt":"Dantiras, дискуссия в моём представлении несколько отличается от \"вот моё мнение, и оно единственно правильное\"."},{"doc_id":3677,"url":"../t130p450-topic.html#p18164","post_id":"p18164","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 14:47","sort_key":"2015-09-23 14:47:00","excerpt":"Скажу откровенно - он не одинок в своём мнении. У меня есть друзья Славя-любители, и их мнение весьма схоже с мнением тов. Арли. Увы, здесь на форуме он представлен в единственном числе. Отсекать от его критики лишнее…"},{"doc_id":3678,"url":"../t130p450-topic.html#p18165","post_id":"p18165","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 14:48","sort_key":"2015-09-23 14:48:00","excerpt":"Согласен с Chess. Кстати, хотел спросить: есть ли люди, не разработчики, которые докопались до истинной задумки автора?"},{"doc_id":3679,"url":"../t130p450-topic.html#p18166","post_id":"p18166","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 14:53","sort_key":"2015-09-23 14:53:00","excerpt":"Нет, конечно. Даже сам автор не исключение. Слишком много вносится с форума."},{"doc_id":3680,"url":"../t130p450-topic.html#p18167","post_id":"p18167","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 14:58","sort_key":"2015-09-23 14:58:00","excerpt":"Ну, тогда думаю, что мою версию происходящего можно взять для начала, ведь ничего её не отрицает в существующем сюжете"},{"doc_id":3681,"url":"../t130p450-topic.html#p18168","post_id":"p18168","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 15:00","sort_key":"2015-09-23 15:00:00","excerpt":"Если под \"истинной задумкой\" понимать идею, с которой я приступил к написанию 7дл - то у кошкотим она есть почти полностью. А если то, что у меня сейчас в виде плана в голове находится, то фигушки я вам её дам."},{"doc_id":3682,"url":"../t130p450-topic.html#p18169","post_id":"p18169","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 15:01","sort_key":"2015-09-23 15:01:00","excerpt":"Ну, я и имел ввиду ту, что у кошкотим. Докопался ли кто-нибудь до неё не из кошкотим"},{"doc_id":3683,"url":"../t130p450-topic.html#p18170","post_id":"p18170","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Ср 23 Сен 2015 - 15:10","sort_key":"2015-09-23 15:10:00","excerpt":"Ты причину со следствием перепутал. Не \"те, кто в Кошкотиме, докопались до Сути(тм)\", а \"те, кто докопался до Сути(тм), неизбежно оказываются в Кошкотиме\". Короче, есть некоторые вещи, до которых не рекомендуется…"},{"doc_id":3684,"url":"../t130p450-topic.html#p18171","post_id":"p18171","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:11","sort_key":"2015-09-23 15:11:00","excerpt":"Автор нам её практически прямым текстом выдал. Это было необходимо для увязывания смежных ролей и общего сценария. Я вот вам намекаю - намекаю, а вы так и не хотите мозг включить и немного подумать. А ведь всё на…"},{"doc_id":3685,"url":"../t130p450-topic.html#p18172","post_id":"p18172","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:12","sort_key":"2015-09-23 15:12:00","excerpt":"Да ладно, всё равно же все умрут."},{"doc_id":3686,"url":"../t130p450-topic.html#p18173","post_id":"p18173","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Ср 23 Сен 2015 - 15:13","sort_key":"2015-09-23 15:13:00","excerpt":""},{"doc_id":3687,"url":"../t130p450-topic.html#p18174","post_id":"p18174","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:24","sort_key":"2015-09-23 15:24:00","excerpt":"Вообще, тащи тестеры, вы непростительно легкомысленно относитесь к намёкам Шизы. В кошкоруте она вообще периодически почти прямым текстом говорит, как и что."},{"doc_id":3688,"url":"../t130p450-topic.html#p18175","post_id":"p18175","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 15:24","sort_key":"2015-09-23 15:24:00","excerpt":"Я бы подумал, что либо Семён неосознанно для себя(но не для нас) в промежутке между днями скачет по рутам, либо несколько вариаций Семёна просто сменяют друг друга, а воспоминания это нечто \"пост сдал - пост принял\""},{"doc_id":3689,"url":"../t130p450-topic.html#p18176","post_id":"p18176","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:25","sort_key":"2015-09-23 15:25:00","excerpt":"Тёпленько, но не совсем."},{"doc_id":3690,"url":"../t130p450-topic.html#p18177","post_id":"p18177","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 15:26","sort_key":"2015-09-23 15:26:00","excerpt":"Ага. Вроде реакции на фотографию мадам Юлии: \"...\" =)"},{"doc_id":3691,"url":"../t130p450-topic.html#p18178","post_id":"p18178","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 15:28","sort_key":"2015-09-23 15:28:00","excerpt":"Просто как один из вариантов: он один раз уже нажёгся на сне и своей памяти, когда попал в \"Совёнок\". И теперь предпочитает сравнивать то, что он помнит и действительность. Или говоря по-другому - расставляет контрольные…"},{"doc_id":3692,"url":"../t130p450-topic.html#p18179","post_id":"p18179","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:30","sort_key":"2015-09-23 15:30:00","excerpt":"Фотки кошочки - это вообще шутка больного коллективного разума. Вот прям совсем тепло! А зачем ему это нужно?"},{"doc_id":3693,"url":"../t130p450-topic.html#p18180","post_id":"p18180","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 15:32","sort_key":"2015-09-23 15:32:00","excerpt":"Он уже был в таком состоянии раньше ? Может в коме"},{"doc_id":3694,"url":"../t130p450-topic.html#p18181","post_id":"p18181","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:33","sort_key":"2015-09-23 15:33:00","excerpt":"Эх, мимо... А ведь почти докопался."},{"doc_id":3695,"url":"../t130p450-topic.html#p18182","post_id":"p18182","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 15:39","sort_key":"2015-09-23 15:39:00","excerpt":"Не знаю, что думает по этому поводу автор, но я это делаю, чтобы понять, в какой из реальностей нахожусь. Не было ли \"прыжка\". А суммирование этих точек и, соответственно, происходящего в разных реальностях, позволяет…"},{"doc_id":3696,"url":"../t130p450-topic.html#p18183","post_id":"p18183","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 15:41","sort_key":"2015-09-23 15:41:00","excerpt":"Будем дальше счёсывать затылок до кости"},{"doc_id":3697,"url":"../t130p450-topic.html#p18184","post_id":"p18184","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:43","sort_key":"2015-09-23 15:43:00","excerpt":"С реальностями, кстати, в \"Совёнке\" тоже не всё привычно, но это отдельный разговор. Суммирование точек ничего не даст, кроме хэш-суммы самого Семёна. Хотя ты довольно близок к осознанию истинной подоплеки происходящего."},{"doc_id":3698,"url":"../t130p475-topic.html#p18185","post_id":"p18185","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 15:57","sort_key":"2015-09-23 15:57:00","excerpt":"Вы, кстати, в курсе, что в недрах сети отловлена Ульянка живьём?:"},{"doc_id":3699,"url":"../t130p475-topic.html#p18186","post_id":"p18186","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 16:00","sort_key":"2015-09-23 16:00:00","excerpt":"Отпустить надобно её, пусть растёт, размножается"},{"doc_id":3700,"url":"../t130p475-topic.html#p18187","post_id":"p18187","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:02","sort_key":"2015-09-23 16:02:00","excerpt":"Тащ Перегаррет яро агитировал за загон и контролируемое осеменение, так что ничо не могу поделать."},{"doc_id":3701,"url":"../t130p475-topic.html#p18188","post_id":"p18188","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 16:04","sort_key":"2015-09-23 16:04:00","excerpt":"Ну если так, то да, а если задуматься - зачем столько Ульянок ? ОО"},{"doc_id":3702,"url":"../t130p475-topic.html#p18189","post_id":"p18189","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:07","sort_key":"2015-09-23 16:07:00","excerpt":"Может он, как и мы, составляет общую картину и все факты систематизирует, все изменения анализирует , чтобы понять всё?"},{"doc_id":3703,"url":"../t130p475-topic.html#p18190","post_id":"p18190","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 16:09","sort_key":"2015-09-23 16:09:00","excerpt":"Опять же не буду гадать задумку и понимание всего этого автором, чисто с моей точки зрения. Я помню что было со мной, своего состояния, развитие событий в какой-то реальности. Моя память базируется на некоторых реперных…"},{"doc_id":3704,"url":"../t130p475-topic.html#p18191","post_id":"p18191","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:10","sort_key":"2015-09-23 16:10:00","excerpt":"И снова в молоко. Жаль. Но, с другой стороны, пищи для раз мыш лений я вам принёс."},{"doc_id":3705,"url":"../t130p475-topic.html#p18192","post_id":"p18192","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:12","sort_key":"2015-09-23 16:12:00","excerpt":"Интересно, раз кто-то уже догадывался до задумки, может порыскать на форумах? Допустим, если мы тут догадаемся, то ньюфаги потом смогут посмотреть и сразу всё понять"},{"doc_id":3706,"url":"../t130p475-topic.html#p18193","post_id":"p18193","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:15","sort_key":"2015-09-23 16:15:00","excerpt":"Тащ, прежде всего не нужно проводить аналогии между собственной личностью и Семёном, это есть гибельный путь, ведущий к различным нарушениям психики. Именно из-за этого \"ЮВАО-тим\" потеряла уже троих. Просто помните…"},{"doc_id":3707,"url":"../t130p475-topic.html#p18194","post_id":"p18194","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:16","sort_key":"2015-09-23 16:16:00","excerpt":"Гадаем дальше. Может, ему это нужно для того, чтобы понять, что есть действительность вообще?"},{"doc_id":3708,"url":"../t130p475-topic.html#p18195","post_id":"p18195","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 16:16","sort_key":"2015-09-23 16:16:00","excerpt":"Могу предложить ещё один вариант. Сёма более высокого уровня (можно назвыть его Сёма-\"бог\" или Сёма-\"дух\") имея доступ ко всем реальностям сразу, тупо развлекается, имея через своих аватар (локальных Семёнов) всех оптом…"},{"doc_id":3709,"url":"../t130p475-topic.html#p18196","post_id":"p18196","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:17","sort_key":"2015-09-23 16:17:00","excerpt":"Я, конечно, извиняюсь дико, но для меня ньюфагом являетесь именно вы. Много вам удаётся вынести из моих сообщений?"},{"doc_id":3710,"url":"../t130p475-topic.html#p18197","post_id":"p18197","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:17","sort_key":"2015-09-23 16:17:00","excerpt":"Я про будущих ньюфагов"},{"doc_id":3711,"url":"../t130p475-topic.html#p18198","post_id":"p18198","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:20","sort_key":"2015-09-23 16:20:00","excerpt":"Вот так вы коллективно, хотя и спорадически, подошли к идее невозможности признания реальности единственно верной."},{"doc_id":3712,"url":"../t130p475-topic.html#p18199","post_id":"p18199","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:23","sort_key":"2015-09-23 16:23:00","excerpt":"Но я же.. писал это сутки назад"},{"doc_id":3713,"url":"../t130p475-topic.html#p18200","post_id":"p18200","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:24","sort_key":"2015-09-23 16:24:00","excerpt":"Ну я же исключительно про мод, товарисч..."},{"doc_id":3714,"url":"../t130p475-topic.html#p18201","post_id":"p18201","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 16:26","sort_key":"2015-09-23 16:26:00","excerpt":"А я и не провожу аналогий. Почему и оговариваюсь каждый раз: это про меня, а это про Семёна. Поэтому и периодически оговариваю разницу: вот это фантазии автора, а вот это то, как работает в реале. А кысей мы договоримся."},{"doc_id":3715,"url":"../t130p475-topic.html#p18202","post_id":"p18202","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:26","sort_key":"2015-09-23 16:26:00","excerpt":"А я про что?"},{"doc_id":3716,"url":"../t130p475-topic.html#p18203","post_id":"p18203","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 16:27","sort_key":"2015-09-23 16:27:00","excerpt":"Блин! Да я про это говорил открытым текстом минимум несколько страниц назад."},{"doc_id":3717,"url":"../t130p475-topic.html#p18204","post_id":"p18204","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:28","sort_key":"2015-09-23 16:28:00","excerpt":"И я"},{"doc_id":3718,"url":"../t130p475-topic.html#p18205","post_id":"p18205","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:29","sort_key":"2015-09-23 16:29:00","excerpt":"И что, никаких параллелей с Семёном, вспоминающим дневные события, не проводится?"},{"doc_id":3719,"url":"../t130p475-topic.html#p18206","post_id":"p18206","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:34","sort_key":"2015-09-23 16:34:00","excerpt":"Даже не знаю. Ну вспомнилась \"Моя Мику\", где Семён попал в другое тело в роли шизы и потом только вспомнил прошлое \"тела\"."},{"doc_id":3720,"url":"../t130p475-topic.html#p18207","post_id":"p18207","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:34","sort_key":"2015-09-23 16:34:00","excerpt":"А ведь это \"ж-ж-ж\" неспроста."},{"doc_id":3721,"url":"../t130p475-topic.html#p18208","post_id":"p18208","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:37","sort_key":"2015-09-23 16:37:00","excerpt":"Пытаюсь сопоставить. Ну тут ему надо было вспомнить, чтобы понять что за Намики. А в лагере.. Куда там BlackDoomer пропал?"},{"doc_id":3722,"url":"../t130p475-topic.html#p18209","post_id":"p18209","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:40","sort_key":"2015-09-23 16:40:00","excerpt":"Лишь приходит на ум, что в роли шизы такой же Семён из другой реальности выступает"},{"doc_id":3723,"url":"../t130p50-topic.html#p17331","post_id":"p17331","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:12","sort_key":"2015-09-08 01:12:00","excerpt":"Чесс не тёмный, Чесса назначили, не спросив согласия!"},{"doc_id":3724,"url":"../t130p50-topic.html#p17332","post_id":"p17332","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:12","sort_key":"2015-09-08 01:12:00","excerpt":"Зато отлично справляешься, если хочешь комплимент от меня, я не считаю тебя мировым злом."},{"doc_id":3725,"url":"../t130p50-topic.html#p17333","post_id":"p17333","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:14","sort_key":"2015-09-08 01:14:00","excerpt":"А как шкалу калибровать? На сколько тёмный?"},{"doc_id":3726,"url":"../t130p50-topic.html#p17334","post_id":"p17334","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:15","sort_key":"2015-09-08 01:15:00","excerpt":"Хороший вопрос, это вообще отдельная тема в психоанализе и философских вибли вобли тайми вайми. У каждого есть свой комфортный баланс в себе, лично у меня 60 - 40."},{"doc_id":3727,"url":"../t130p50-topic.html#p17336","post_id":"p17336","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:17","sort_key":"2015-09-08 01:17:00","excerpt":"- А зачем вы живёте? - Хороший вопрос. - Нет. Это плохой вопрос."},{"doc_id":3728,"url":"../t130p50-topic.html#p17337","post_id":"p17337","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:18","sort_key":"2015-09-08 01:18:00","excerpt":"Только сегодня Юнга вспоминал: Главный вопрос не почему, а зачем."},{"doc_id":3729,"url":"../t130p50-topic.html#p17338","post_id":"p17338","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:22","sort_key":"2015-09-08 01:22:00","excerpt":"Чтобы увеличить энтропию и приблизить тепловую смерть Вселенной."},{"doc_id":3730,"url":"../t130p50-topic.html#p17339","post_id":"p17339","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:23","sort_key":"2015-09-08 01:23:00","excerpt":"Ну не, долой Уныние!)"},{"doc_id":3731,"url":"../t130p50-topic.html#p17340","post_id":"p17340","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"argh","posted_at":"Вт 8 Сен 2015 - 1:25","sort_key":"2015-09-08 01:25:00","excerpt":"Это не уныние. Это я сливаю концовку мода."},{"doc_id":3732,"url":"../t130p50-topic.html#p17341","post_id":"p17341","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:28","sort_key":"2015-09-08 01:28:00","excerpt":"Балин! Я то всё собирался Славю оформить, да никак датфилонастроения не наберусь, что бы в БЛ вернуться."},{"doc_id":3733,"url":"../t130p50-topic.html#p17342","post_id":"p17342","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:35","sort_key":"2015-09-08 01:35:00","excerpt":"Ну как дети малые, чесслово! \"Почему, зачем\"... Мы на самом деле вообще не живём. http://www.pravda.ru/science/planet/space/24-11-2014/1236803-universe-0/"},{"doc_id":3734,"url":"../t130p50-topic.html#p17343","post_id":"p17343","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:36","sort_key":"2015-09-08 01:36:00","excerpt":"О, рептилойды масоны, это я завсегда!"},{"doc_id":3735,"url":"../t130p50-topic.html#p17344","post_id":"p17344","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:46","sort_key":"2015-09-08 01:46:00","excerpt":"Не, на самом деле теория Вселенной-симулятора косвенно подтверждается, как ни странно. То же кватнотование пространства-времени, например, с точки зрения физики на данный момент ничем не объяснимо. Ну и комбинированная…"},{"doc_id":3736,"url":"../t130p50-topic.html#p17345","post_id":"p17345","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:50","sort_key":"2015-09-08 01:50:00","excerpt":"Старый добрый LOST, 1000 лет прошло с его просмотра, ностальгия прям."},{"doc_id":3737,"url":"../t130p50-topic.html#p17347","post_id":"p17347","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:51","sort_key":"2015-09-08 01:51:00","excerpt":"Не смотрел, пардон. А что, там тоже нечто подобное всплывало?"},{"doc_id":3738,"url":"../t130p50-topic.html#p17349","post_id":"p17349","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:54","sort_key":"2015-09-08 01:54:00","excerpt":"Они сделал так много перепитей сюжета, что сами запутались в них и концовку слили в стиле, вселенная - песчинка в кошачем латке мегакота!"},{"doc_id":3739,"url":"../t130p50-topic.html#p17350","post_id":"p17350","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Вт 8 Сен 2015 - 1:56","sort_key":"2015-09-08 01:56:00","excerpt":""},{"doc_id":3740,"url":"../t130p50-topic.html#p17351","post_id":"p17351","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 1:58","sort_key":"2015-09-08 01:58:00","excerpt":"Ахаха, нашли общий язык называется)"},{"doc_id":3741,"url":"../t130p50-topic.html#p17353","post_id":"p17353","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Вт 8 Сен 2015 - 2:07","sort_key":"2015-09-08 02:07:00","excerpt":"Вынужден откланяться, 4 часа сна - тоже сон, пусть хотя бы немного. Ночи."},{"doc_id":3742,"url":"../t130p50-topic.html#p17357","post_id":"p17357","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Вт 8 Сен 2015 - 16:08","sort_key":"2015-09-08 16:08:00","excerpt":"Если кому-то интересно - стрим по 7ДЛ (будет сегодня примерно до 22-00). http://www.twitch.tv/happasc2 http://goodgame.ru/channel/Happa_"},{"doc_id":3743,"url":"../t130p50-topic.html#p17358","post_id":"p17358","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вт 8 Сен 2015 - 16:17","sort_key":"2015-09-08 16:17:00","excerpt":"Кто стримит-то?"},{"doc_id":3744,"url":"../t130p50-topic.html#p17359","post_id":"p17359","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Вт 8 Сен 2015 - 16:22","sort_key":"2015-09-08 16:22:00","excerpt":"Плохая затея. Тут один стример уже попрощался со своим каналом."},{"doc_id":3745,"url":"../t130p50-topic.html#p17360","post_id":"p17360","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Вт 8 Сен 2015 - 16:23","sort_key":"2015-09-08 16:23:00","excerpt":"Стримит Хаппа. Он уже весь БЛ простримил (имхо, кошерно). А обыкновенно Хартстоун стримит."},{"doc_id":3746,"url":"../t130p50-topic.html#p17361","post_id":"p17361","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Вт 8 Сен 2015 - 16:25","sort_key":"2015-09-08 16:25:00","excerpt":"Кошочка не прощает! Интересно, а за что его закрыли-то?"},{"doc_id":3747,"url":"../t130p50-topic.html#p17362","post_id":"p17362","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Вт 8 Сен 2015 - 16:27","sort_key":"2015-09-08 16:27:00","excerpt":"Этому на 7ДЛ задонатили. А прошлый задарма летсплеил."},{"doc_id":3748,"url":"../t130p500-topic.html#p18210","post_id":"p18210","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:41","sort_key":"2015-09-23 16:41:00","excerpt":"Он неуважительно отозвался о кошочке же. Вот, кстати, наглядный пример."},{"doc_id":3749,"url":"../t130p500-topic.html#p18211","post_id":"p18211","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:41","sort_key":"2015-09-23 16:41:00","excerpt":""},{"doc_id":3750,"url":"../t130p500-topic.html#p18212","post_id":"p18212","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:41","sort_key":"2015-09-23 16:41:00","excerpt":"Ещё теплее, но путь рассуждений неверный."},{"doc_id":3751,"url":"../t130p500-topic.html#p18213","post_id":"p18213","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:44","sort_key":"2015-09-23 16:44:00","excerpt":"Не хватает меня Надо, наверное, кошко-рут пройти"},{"doc_id":3752,"url":"../t130p500-topic.html#p18214","post_id":"p18214","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 16:44","sort_key":"2015-09-23 16:44:00","excerpt":"Мне, например, интересно откуда в снах Леночки она видит Сёмины концовки с Мику. И как она суммарно подвязана с ГГ, что знает топонимику Питера и т.д. Последние послепослесловия вообще говорят о том, что в РФ все…"},{"doc_id":3753,"url":"../t130p500-topic.html#p18215","post_id":"p18215","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:47","sort_key":"2015-09-23 16:47:00","excerpt":"Вы не поверите, но ответ сокрыт в некоторых внутренних сюжетках кошкорута. И там даже не только про Унылку разгадки."},{"doc_id":3754,"url":"../t130p500-topic.html#p18216","post_id":"p18216","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:49","sort_key":"2015-09-23 16:49:00","excerpt":"Чорд с вами, держите спойлер:"},{"doc_id":3755,"url":"../t130p500-topic.html#p18217","post_id":"p18217","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 16:51","sort_key":"2015-09-23 16:51:00","excerpt":"Лучше дождаться выхода всего творения. Ибо пока что:"},{"doc_id":3756,"url":"../t130p500-topic.html#p18218","post_id":"p18218","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 16:51","sort_key":"2015-09-23 16:51:00","excerpt":"Что-то от картинки Ветровым попахивает. И да, не нужно путать кошочку с трио-рутом. Это таки две большие разницы."},{"doc_id":3757,"url":"../t130p500-topic.html#p18219","post_id":"p18219","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Ср 23 Сен 2015 - 16:52","sort_key":"2015-09-23 16:52:00","excerpt":"Евонное и есть."},{"doc_id":3758,"url":"../t130p500-topic.html#p18220","post_id":"p18220","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:53","sort_key":"2015-09-23 16:53:00","excerpt":"Ну стоит пройти хотя бы для того, чтобы узнать ещё чуть больше"},{"doc_id":3759,"url":"../t130p500-topic.html#p18221","post_id":"p18221","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 16:59","sort_key":"2015-09-23 16:59:00","excerpt":"Твой спойлер, конечно, полезен, но насчёт воспоминаний объяснений не даёт. Хотя, может если он не вспомнит, то может попасть на катапульту в свой мир? Да не, бред какой-то..."},{"doc_id":3760,"url":"../t130p500-topic.html#p18222","post_id":"p18222","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 17:00","sort_key":"2015-09-23 17:00:00","excerpt":"Старайтесь на труЪ-ветку кошкорута и возникнет ещё больше вопросов. Потом будете досаждать Чесса и Перегаррета вопросом - когда же доделают."},{"doc_id":3761,"url":"../t130p500-topic.html#p18223","post_id":"p18223","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:00","sort_key":"2015-09-23 17:00:00","excerpt":"Насчёт воспоминаний - это к кошочке автору. Мы только за кошкорут пока что отвечаем."},{"doc_id":3762,"url":"../t130p500-topic.html#p18224","post_id":"p18224","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:02","sort_key":"2015-09-23 17:02:00","excerpt":"Я бы посоветовал ещё тащу Бегуну мозг проедать. Именно он пишет весь гуд-пучок внутренних сюжетов рута."},{"doc_id":3763,"url":"../t130p500-topic.html#p18225","post_id":"p18225","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 17:03","sort_key":"2015-09-23 17:03:00","excerpt":"Ну ты же нас не 1 раз спрашивал, зачем же ему вспоминать. Значит знаешь"},{"doc_id":3764,"url":"../t130p500-topic.html#p18226","post_id":"p18226","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:04","sort_key":"2015-09-23 17:04:00","excerpt":"Естессно, знаю. Но не сдам. Извольте мозгом ворочать."},{"doc_id":3765,"url":"../t130p500-topic.html#p18227","post_id":"p18227","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 17:09","sort_key":"2015-09-23 17:09:00","excerpt":"Хм. Ну, может он на самом деле после каждого сна в новой реальности уже оказывается и ему необходимо вспоминать, чтобы понять происходящее."},{"doc_id":3766,"url":"../t130p500-topic.html#p18228","post_id":"p18228","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:12","sort_key":"2015-09-23 17:12:00","excerpt":"Чесс загадочно молчит. Спойлер: На самом деле, почти понял. Но не совсем."},{"doc_id":3767,"url":"../t130p500-topic.html#p18229","post_id":"p18229","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 17:13","sort_key":"2015-09-23 17:13:00","excerpt":"Значит нет?"},{"doc_id":3768,"url":"../t130p500-topic.html#p18230","post_id":"p18230","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 17:19","sort_key":"2015-09-23 17:19:00","excerpt":"Ох уж это не совсем"},{"doc_id":3769,"url":"../t130p500-topic.html#p18231","post_id":"p18231","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 17:30","sort_key":"2015-09-23 17:30:00","excerpt":"Дык, не он обещал во всепрочтение на вики к осени Кошочку выпустить."},{"doc_id":3770,"url":"../t130p500-topic.html#p18232","post_id":"p18232","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:33","sort_key":"2015-09-23 17:33:00","excerpt":"Ну неправильно оценил силы команды камрад. Давайте его теперь прибьём за это?"},{"doc_id":3771,"url":"../t130p500-topic.html#p18233","post_id":"p18233","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:34","sort_key":"2015-09-23 17:34:00","excerpt":"Хм, Штейн, очень приятно, рад знакомству)"},{"doc_id":3772,"url":"../t130p500-topic.html#p18234","post_id":"p18234","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 17:36","sort_key":"2015-09-23 17:36:00","excerpt":"Ну, пардоньте=) Из радикальных долгожителей тут только Арли. Это и имелось ввиду."},{"doc_id":3773,"url":"../t130p525-topic.html#p18235","post_id":"p18235","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:38","sort_key":"2015-09-23 17:38:00","excerpt":""},{"doc_id":3774,"url":"../t130p525-topic.html#p18236","post_id":"p18236","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:38","sort_key":"2015-09-23 17:38:00","excerpt":"Долго следил за товарищем Арли и за форумом, потом сам писать стал, на базисе работ Арли. Как вижу сейчас, кое-какие вещи угадал я, либо детальки были взяты автором, что мне сильно льстит, если это так. Понимаю, никто не…"},{"doc_id":3775,"url":"../t130p525-topic.html#p18237","post_id":"p18237","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:39","sort_key":"2015-09-23 17:39:00","excerpt":"Лол, не ты ли меня ругал за пикча-тред?) Подкол засчитан, 10 баллов факультету кошки. Ещё и Арли там колишь, ты сегодня прям в ударе)"},{"doc_id":3776,"url":"../t130p525-topic.html#p18238","post_id":"p18238","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:42","sort_key":"2015-09-23 17:42:00","excerpt":"Я люблю, твои коллеги сделали для меня очень многое. Ком цу мир, я тебя в дёсны облобызаю. Но как твоя специальность относится к обсуждению мода?"},{"doc_id":3777,"url":"../t130p525-topic.html#p18239","post_id":"p18239","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 17:43","sort_key":"2015-09-23 17:43:00","excerpt":"Я тоже Ваши работы долго вычитывал из Славя-треда. Только спустя две недели после регистрации, окончив чтение основных руто-тредов, приступил к активной деятельности. \"Лечение\" прошло успешно =) Хотя бы градус неадеквата…"},{"doc_id":3778,"url":"../t130p525-topic.html#p18240","post_id":"p18240","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:43","sort_key":"2015-09-23 17:43:00","excerpt":"А, м, скажем так, я весьма специфичный врач, психоаналитика и попытка запилить архетип Славяны - намекают)"},{"doc_id":3779,"url":"../t130p525-topic.html#p18241","post_id":"p18241","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:44","sort_key":"2015-09-23 17:44:00","excerpt":"О, польщён, спасибо) Да, у меня та же история с работами Арли была."},{"doc_id":3780,"url":"../t130p525-topic.html#p18242","post_id":"p18242","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:44","sort_key":"2015-09-23 17:44:00","excerpt":"Таки у тебя на форуме есть поциент. Ты ведь понял, о ком идёт речь?"},{"doc_id":3781,"url":"../t130p525-topic.html#p18243","post_id":"p18243","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 17:45","sort_key":"2015-09-23 17:45:00","excerpt":"Ком цу мир... В дёсны облобызаю...Что-то знакомые обороты..."},{"doc_id":3782,"url":"../t130p525-topic.html#p18244","post_id":"p18244","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:46","sort_key":"2015-09-23 17:46:00","excerpt":"А мне то как страшно, приедет ведь"},{"doc_id":3783,"url":"../t130p525-topic.html#p18245","post_id":"p18245","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:50","sort_key":"2015-09-23 17:50:00","excerpt":"Зная твои шуточки, я догадываюсь) Самое забавное, что это своего рода взаимное лечение) Этакий Юнговский эпирический метод, по средствам Человек человеку - врач, учитель и друг) А в общем, жду от тебя пособие: Как…"},{"doc_id":3784,"url":"../t130p525-topic.html#p18246","post_id":"p18246","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:51","sort_key":"2015-09-23 17:51:00","excerpt":"Прошу пояснить, что именно вы имели ввиду. Я существо исключительно мирное и подрывать могу только мозг неокрепших читателей."},{"doc_id":3785,"url":"../t130p525-topic.html#p18247","post_id":"p18247","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 17:55","sort_key":"2015-09-23 17:55:00","excerpt":"Ну или потроллировать фана ради=)"},{"doc_id":3786,"url":"../t130p525-topic.html#p18248","post_id":"p18248","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 17:56","sort_key":"2015-09-23 17:56:00","excerpt":"Янитакой!"},{"doc_id":3787,"url":"../t130p525-topic.html#p18249","post_id":"p18249","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 17:57","sort_key":"2015-09-23 17:57:00","excerpt":"А ещё любишь высасывать глаза за Алисочку, коль тронут) Лол, пойду-ка я линзы сниму, а то уже глаза от шерсти слезятся)"},{"doc_id":3788,"url":"../t130p525-topic.html#p18250","post_id":"p18250","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 18:00","sort_key":"2015-09-23 18:00:00","excerpt":"Ибо нефиг трогать Алисочку. По-моему, всё справедливо."},{"doc_id":3789,"url":"../t130p525-topic.html#p18251","post_id":"p18251","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 18:00","sort_key":"2015-09-23 18:00:00","excerpt":"Не, эт правильно, вздрогнем за это, сильный пол всё таки)"},{"doc_id":3790,"url":"../t130p525-topic.html#p18252","post_id":"p18252","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 18:02","sort_key":"2015-09-23 18:02:00","excerpt":"Слабый пол сильнее сильного в силу слабости сильного пола к слабому."},{"doc_id":3791,"url":"../t130p525-topic.html#p18253","post_id":"p18253","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 18:02","sort_key":"2015-09-23 18:02:00","excerpt":"Таки да"},{"doc_id":3792,"url":"../t130p525-topic.html#p18254","post_id":"p18254","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 18:03","sort_key":"2015-09-23 18:03:00","excerpt":"Да, мужик сильнее всего, а женщина, сильнее мужчины во многом, но не сильнее всего остального. Хорошо сказано."},{"doc_id":3793,"url":"../t130p525-topic.html#p18255","post_id":"p18255","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 18:04","sort_key":"2015-09-23 18:04:00","excerpt":"В этом вы с Арли и похожи. Только сменим рыжий на жёлтый."},{"doc_id":3794,"url":"../t130p525-topic.html#p18256","post_id":"p18256","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Ср 23 Сен 2015 - 18:05","sort_key":"2015-09-23 18:05:00","excerpt":"Шизизм же. (правильно, нет? Если у Виолы виолизмы, то что у Шизы?)"},{"doc_id":3795,"url":"../t130p525-topic.html#p18257","post_id":"p18257","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 18:14","sort_key":"2015-09-23 18:14:00","excerpt":"Прошу примеров, где я мешал оппонента с говном за адекватное высказывание в сторону Алисочки."},{"doc_id":3796,"url":"../t130p525-topic.html#p18258","post_id":"p18258","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 18:15","sort_key":"2015-09-23 18:15:00","excerpt":"А, вот вы о чём. Нет, за Шизу я не ответственен, оно само так получилось. Чесслово, не вру!"},{"doc_id":3797,"url":"../t130p525-topic.html#p18259","post_id":"p18259","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 18:18","sort_key":"2015-09-23 18:18:00","excerpt":"Пруфов не будет =) Имею в виду обострённую реакцию на конкретного персонажа новеллы и действия с ним. А дальше каждый реагирует в меру своего собственного характера, чувства юмора и выдержки."},{"doc_id":3798,"url":"../t130p550-topic.html#p18260","post_id":"p18260","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 18:22","sort_key":"2015-09-23 18:22:00","excerpt":"М-м-м... Скажем так, я неоднократно заявлял, что в ярости грызу угол стола, если кто-то негативно отзывается об Алисе, но, смею уверить, в реале такого не происходило. И во всех Алисо-срачах я не позволял себе переходить…"},{"doc_id":3799,"url":"../t130p550-topic.html#p18261","post_id":"p18261","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 18:27","sort_key":"2015-09-23 18:27:00","excerpt":"Как будто я написал что-то другое=) И ваши обсуждения я читал - в курсе всего. А вообще, давайте кончать обсуждение персоналий - мерзенькое это дельцо."},{"doc_id":3800,"url":"../t130p550-topic.html#p18262","post_id":"p18262","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Ср 23 Сен 2015 - 18:28","sort_key":"2015-09-23 18:28:00","excerpt":"Ну почему же? Срач бодрит унд будит фантазию!"},{"doc_id":3801,"url":"../t130p550-topic.html#p18263","post_id":"p18263","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 18:47","sort_key":"2015-09-23 18:47:00","excerpt":"Особенно Славя-срачи)"},{"doc_id":3802,"url":"../t130p550-topic.html#p18264","post_id":"p18264","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 18:49","sort_key":"2015-09-23 18:49:00","excerpt":"Иначе чем заняться пока пишется рут)"},{"doc_id":3803,"url":"../t130p550-topic.html#p18265","post_id":"p18265","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 18:52","sort_key":"2015-09-23 18:52:00","excerpt":"Именно! Так было и будет до тех пор, пока рут не будет дописан)"},{"doc_id":3804,"url":"../t130p550-topic.html#p18266","post_id":"p18266","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 18:54","sort_key":"2015-09-23 18:54:00","excerpt":"Нужен рут бесконечный"},{"doc_id":3805,"url":"../t130p550-topic.html#p18267","post_id":"p18267","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 18:55","sort_key":"2015-09-23 18:55:00","excerpt":"Блин, хорошо, что форму всё таки сделали открытым вновь, аве Автор)"},{"doc_id":3806,"url":"../t130p550-topic.html#p18268","post_id":"p18268","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 19:08","sort_key":"2015-09-23 19:08:00","excerpt":"Неадекватные личности повелись на то что форума им не видать, и забыли дорогу, это гуд"},{"doc_id":3807,"url":"../t130p550-topic.html#p18269","post_id":"p18269","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 19:16","sort_key":"2015-09-23 19:16:00","excerpt":"А тестеры, художники и просто хорошие люди только увеличивают своё множество, это замечательно."},{"doc_id":3808,"url":"../t130p550-topic.html#p18270","post_id":"p18270","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 19:20","sort_key":"2015-09-23 19:20:00","excerpt":"Поискать баги может? Полезное занятие, скажу я вам, господа."},{"doc_id":3809,"url":"../t130p550-topic.html#p18271","post_id":"p18271","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 19:23","sort_key":"2015-09-23 19:23:00","excerpt":"Ну, для этого есть ты) К сожалению, не был в лете уже месяца три, а об обновах и фичах - лишь читаю, да смотрю со стороны. Такие пироги."},{"doc_id":3810,"url":"../t130p550-topic.html#p18272","post_id":"p18272","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 19:31","sort_key":"2015-09-23 19:31:00","excerpt":"Подозревал это и раньше=) Потому даже не пытаюсь в обсуждения сюжеток лезть - работы очень много."},{"doc_id":3811,"url":"../t130p550-topic.html#p18273","post_id":"p18273","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Ср 23 Сен 2015 - 19:36","sort_key":"2015-09-23 19:36:00","excerpt":"Ну вот вы, как и другие господа реагируете быстрее, а я ко времени ваших багрепортов лишь начинаю читать спасибо моему непостоянному инету и девушке которая не сильно жалует БЛ"},{"doc_id":3812,"url":"../t130p550-topic.html#p18274","post_id":"p18274","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 19:39","sort_key":"2015-09-23 19:39:00","excerpt":"А так, как выдастся нормально время для прочтение всего залпом, явно выкачу крупную работу на тему Слави."},{"doc_id":3813,"url":"../t130p550-topic.html#p18275","post_id":"p18275","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 19:48","sort_key":"2015-09-23 19:48:00","excerpt":"Ну, несколько часов вечерком и в ночи выделить я всегда готов. Мне хватает, но иногда выдаются случаи потестировать побольше. Плохо, что многие здесь читают сразу в коде и не проверяют графическую и логическую часть в…"},{"doc_id":3814,"url":"../t130p550-topic.html#p18276","post_id":"p18276","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 22:18","sort_key":"2015-09-23 22:18:00","excerpt":"Кстати, о хардкорных старожилах - неправда, из старой гвардии тут еще Перегарыч! Ну и Ветров заглядывает изредка со своей офигительной историей."},{"doc_id":3815,"url":"../t130p550-topic.html#p18277","post_id":"p18277","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 22:35","sort_key":"2015-09-23 22:35:00","excerpt":"А Chess?"},{"doc_id":3816,"url":"../t130p550-topic.html#p18278","post_id":"p18278","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 22:36","sort_key":"2015-09-23 22:36:00","excerpt":"Да, мы тут о поборниках чести Славяны речь вели. Потому остальные кандидаты во внимание не принимались."},{"doc_id":3817,"url":"../t130p550-topic.html#p18279","post_id":"p18279","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 22:39","sort_key":"2015-09-23 22:39:00","excerpt":"Сундук изрядно позже подключился, если память не изменяет. Уже когда форум засетапили. ...а-а-а. Вторую версию 7ДЛ-Слави читали?) А то был у нас тут давным-давно еще один... поборник."},{"doc_id":3818,"url":"../t130p550-topic.html#p18280","post_id":"p18280","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Ср 23 Сен 2015 - 22:41","sort_key":"2015-09-23 22:41:00","excerpt":"Как раз не читал первую. В архивах не откопал."},{"doc_id":3819,"url":"../t130p550-topic.html#p18281","post_id":"p18281","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 22:43","sort_key":"2015-09-23 22:43:00","excerpt":"Это когда тотальный эротик-бутик, от которого я улетел на стратосферу, что-то там про елозинье под покрывалом на 2ом дне, оно?)"},{"doc_id":3820,"url":"../t130p550-topic.html#p18282","post_id":"p18282","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Ср 23 Сен 2015 - 22:47","sort_key":"2015-09-23 22:47:00","excerpt":"Пжалста! rghost.ru/7BYKTwSm4 И нет, это про другое, Соляр"},{"doc_id":3821,"url":"../t130p550-topic.html#p18283","post_id":"p18283","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 23:01","sort_key":"2015-09-23 23:01:00","excerpt":"Кто меня искал? И Chess, ты не прав. Кошки меня любят. А если мы иногда грызёмся, то это чисто наши кошачьи разборки. И кстати, гадать, что задумал автор, я не буду. Мне это не выгодно. То, что я пишу по этим темам - это…"},{"doc_id":3822,"url":"../t130p550-topic.html#p18284","post_id":"p18284","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 23:24","sort_key":"2015-09-23 23:24:00","excerpt":"На самом деле это то, что я писал. А перемещение в реальностях и во времени - это пока фантастика"},{"doc_id":3823,"url":"../t130p575-topic.html#p18285","post_id":"p18285","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Ср 23 Сен 2015 - 23:41","sort_key":"2015-09-23 23:41:00","excerpt":"Во времени - да. И то относительно. Игры со временем - отдельная песня. По реальностям - есть несколько способов. Один из них, когда перемещается не тушка, а сознание, ни разу не фантастика. Но необходимо выполнение…"},{"doc_id":3824,"url":"../t130p575-topic.html#p18286","post_id":"p18286","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Ср 23 Сен 2015 - 23:46","sort_key":"2015-09-23 23:46:00","excerpt":"Ну и много людей путешествовали по реальностям в жизни? Это больше похоже на то, что это просто его сон или галлюцинации. Потому что сознание то вроде в мозгу хранится, в таких же клетках. Так что если они могут…"},{"doc_id":3825,"url":"../t130p575-topic.html#p18287","post_id":"p18287","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 23:56","sort_key":"2015-09-23 23:56:00","excerpt":"Ох, старые ники) Ну, я попал именно на то, что описал. Тогда я на горящем пердаке прилетел сюда."},{"doc_id":3826,"url":"../t130p575-topic.html#p18288","post_id":"p18288","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Ср 23 Сен 2015 - 23:59","sort_key":"2015-09-23 23:59:00","excerpt":"Блин, я тут у Пикассо рылся и Чесса нашёл"},{"doc_id":3827,"url":"../t130p575-topic.html#p18289","post_id":"p18289","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 0:48","sort_key":"2015-09-24 00:48:00","excerpt":"Спойлер: Вообще-то если спонтанно - то много. Просто людям не свойственно обращать на это внимание. Им проще списать возникающие казусы на собственную забывчивость. Мы сами стали замечать такие моменты только тогда…"},{"doc_id":3828,"url":"../t130p575-topic.html#p18292","post_id":"p18292","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 9:39","sort_key":"2015-09-24 09:39:00","excerpt":"И как человек определяет, что он в другой реальности, если она такая же? Или не такая же? Насчёт этого официальная наука тоже другого мнения, поэтому это можно считать НФ. И кстати, раз ты разбираешься в подобных идеях…"},{"doc_id":3829,"url":"../t130p575-topic.html#p18294","post_id":"p18294","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 12:10","sort_key":"2015-09-24 12:10:00","excerpt":"Спойлер: На самом деле не так сложно. Просто немного наблюдательности из серии этого не может быть, потому, что не может быть никогда. Например, как ты думаешь, если ты проходишь каждый день одним и тем же маршрутом ты…"},{"doc_id":3830,"url":"../t130p575-topic.html#p18295","post_id":"p18295","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 12:28","sort_key":"2015-09-24 12:28:00","excerpt":"Во! А я давно говорил, что все мы - сон кота!"},{"doc_id":3831,"url":"../t130p575-topic.html#p18296","post_id":"p18296","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 12:44","sort_key":"2015-09-24 12:44:00","excerpt":"Ну, таких случаев у меня не было, да и наука это не подтверждает, так что можно не забивать этим голову пока что"},{"doc_id":3832,"url":"../t130p575-topic.html#p18297","post_id":"p18297","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 12:51","sort_key":"2015-09-24 12:51:00","excerpt":"А теперь давайте, наконец, отпустим тему реальностей, т.к. рассказывать задумку автора нам никто не собирается, и опустимся до обсуждения девушек мода? Почему Chess нравится Алиса?"},{"doc_id":3833,"url":"../t130p575-topic.html#p18298","post_id":"p18298","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 13:27","sort_key":"2015-09-24 13:27:00","excerpt":"Потому что он алисофаг, очевидно же!"},{"doc_id":3834,"url":"../t130p575-topic.html#p18299","post_id":"p18299","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 13:34","sort_key":"2015-09-24 13:34:00","excerpt":"Я извиняюсь, а кто Чессу должен нравится? Легкомысленная болтушка Мику, инфантильная Лена с тараканами в голове, или хитрая и расчётливая Славя?"},{"doc_id":3835,"url":"../t130p575-topic.html#p18300","post_id":"p18300","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 13:37","sort_key":"2015-09-24 13:37:00","excerpt":"Не гнать на Мику, она чудо. К тому же, далеко не легкомысленная."},{"doc_id":3836,"url":"../t130p575-topic.html#p18301","post_id":"p18301","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 13:42","sort_key":"2015-09-24 13:42:00","excerpt":"Тащ Автор, не мешайте срач разводить! Спойлер: И вообще, я прекрасно понимаю, что что-то хорошее можно найти в каждой девушке, но девушки - это девушки, а Алисочка - это Алисочка."},{"doc_id":3837,"url":"../t130p575-topic.html#p18302","post_id":"p18302","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 14:05","sort_key":"2015-09-24 14:05:00","excerpt":"Угу. Это из серии: \"- Ты суслика видишь? -Нет. - А он есть\"."},{"doc_id":3838,"url":"../t130p575-topic.html#p18303","post_id":"p18303","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 14:07","sort_key":"2015-09-24 14:07:00","excerpt":"А вместе они прекрасно дополняют друг друга..."},{"doc_id":3839,"url":"../t130p575-topic.html#p18304","post_id":"p18304","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 14:08","sort_key":"2015-09-24 14:08:00","excerpt":"Так что, теперь на всех внимание обращать? Так и на карандаш сточить можно. Семён, в конце концов, не Роокко Сиффреди."},{"doc_id":3840,"url":"../t130p575-topic.html#p18305","post_id":"p18305","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Элдхэнн","posted_at":"Чт 24 Сен 2015 - 14:28","sort_key":"2015-09-24 14:28:00","excerpt":"И тут я не выдержал. Что за грязные намёки на Алисочку?"},{"doc_id":3841,"url":"../t130p575-topic.html#p18306","post_id":"p18306","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 14:29","sort_key":"2015-09-24 14:29:00","excerpt":"Всё верно. Фотомодель - это фотомодель, но два раза - это всё-таки два раза!"},{"doc_id":3842,"url":"../t130p575-topic.html#p18307","post_id":"p18307","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 14:31","sort_key":"2015-09-24 14:31:00","excerpt":"Философски: Странное направление разговор принимает. И ведь это даже Перегаррет ещё не подошёл!"},{"doc_id":3843,"url":"../t130p575-topic.html#p18308","post_id":"p18308","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 24 Сен 2015 - 14:32","sort_key":"2015-09-24 14:32:00","excerpt":"Да вы и без меня справляетесь отлично."},{"doc_id":3844,"url":"../t130p575-topic.html#p18309","post_id":"p18309","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 24 Сен 2015 - 14:37","sort_key":"2015-09-24 14:37:00","excerpt":"Негодую, кстати. Ульяну забыл."},{"doc_id":3845,"url":"../t130p575-topic.html#p18310","post_id":"p18310","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 14:49","sort_key":"2015-09-24 14:49:00","excerpt":"Ладно, негодуй."},{"doc_id":3846,"url":"../t130p575-topic.html#p18311","post_id":"p18311","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 15:40","sort_key":"2015-09-24 15:40:00","excerpt":"На Мику не гнать! (2) Она просто от одиночества так свои мысли выражает."},{"doc_id":3847,"url":"../t130p575-topic.html#p18312","post_id":"p18312","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 15:42","sort_key":"2015-09-24 15:42:00","excerpt":"Хм, а автор только про Мику сказал, про остальное промолчал? Неужели он Микуфаг?"},{"doc_id":3848,"url":"../t130p600-topic.html#p18313","post_id":"p18313","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 15:43","sort_key":"2015-09-24 15:43:00","excerpt":"Автор с остальными оценками полностью согласен."},{"doc_id":3849,"url":"../t130p600-topic.html#p18314","post_id":"p18314","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 15:44","sort_key":"2015-09-24 15:44:00","excerpt":"Получается, что у Мику недостатков видимых нет в моде?"},{"doc_id":3850,"url":"../t130p600-topic.html#p18315","post_id":"p18315","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 16:09","sort_key":"2015-09-24 16:09:00","excerpt":"Кроме того, что она асоциал с синдромом дефицита внимания/гиперактивности? Нет, никаких, как только в голову пришло."},{"doc_id":3851,"url":"../t130p600-topic.html#p18316","post_id":"p18316","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 17:39","sort_key":"2015-09-24 17:39:00","excerpt":"Не, ну серьёзно - Алисочка же самая адекватная в \"Совёнке\". Человечек с непростым опытом жизненным, естественно, пытается свою ранимость спрятать под показной непрошибаемостью, а сама болезненно реагирует на любое грубое…"},{"doc_id":3852,"url":"../t130p600-topic.html#p18317","post_id":"p18317","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:31","sort_key":"2015-09-24 18:31:00","excerpt":"Это Алиса-то адекватная? Да брось... Самое адекватное существо в лагере - совёнок!"},{"doc_id":3853,"url":"../t130p600-topic.html#p18319","post_id":"p18319","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:33","sort_key":"2015-09-24 18:33:00","excerpt":"Чесс задумчиво косится на изгрызенный угол стола Ты не прав. Алисочка адекватнее комка пуха."},{"doc_id":3854,"url":"../t130p600-topic.html#p18320","post_id":"p18320","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 18:36","sort_key":"2015-09-24 18:36:00","excerpt":"Мне Алиса в 7ДЛ стала сильно напоминать Джек из МЕ, окромя желания убивать чтобы повышать свои шансы на выживание."},{"doc_id":3855,"url":"../t130p600-topic.html#p18321","post_id":"p18321","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 18:37","sort_key":"2015-09-24 18:37:00","excerpt":"А у кого в лагере этот опыт простой? Любого копни, у него история. Только не все превентивно эпатируют окружающих, это да."},{"doc_id":3856,"url":"../t130p600-topic.html#p18322","post_id":"p18322","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:38","sort_key":"2015-09-24 18:38:00","excerpt":"А что? Живёт себе на дереве, никого из себя не строит, никому мозг не выносит, на все вопросы честно отвечает: \"Угу-угу\". А если стол грызёшь, то это клетчатки в организму не хватает."},{"doc_id":3857,"url":"../t130p600-topic.html#p18324","post_id":"p18324","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:40","sort_key":"2015-09-24 18:40:00","excerpt":"Ну то, что автор написал про Мику - я недостатками не считаю. Мозг не выносит, нежится, красивая, ещё и певичка. А Алиса(в силу своего опыта, конечно же) мозг выносит"},{"doc_id":3858,"url":"../t130p600-topic.html#p18325","post_id":"p18325","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:41","sort_key":"2015-09-24 18:41:00","excerpt":"Ну спасибо хоть не коры ГМ."},{"doc_id":3859,"url":"../t130p600-topic.html#p18326","post_id":"p18326","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:42","sort_key":"2015-09-24 18:42:00","excerpt":"Алисочку жальче. Причины я вам в личку обосновывал."},{"doc_id":3860,"url":"../t130p600-topic.html#p18327","post_id":"p18327","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 18:42","sort_key":"2015-09-24 18:42:00","excerpt":"Эти причины называются субъективной оценкой. А мы тут стараемся быть объективными, ага-ага. (="},{"doc_id":3861,"url":"../t130p600-topic.html#p18329","post_id":"p18329","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:43","sort_key":"2015-09-24 18:43:00","excerpt":"Алиса всё равно не будет ламповой тян никогда в силу характера."},{"doc_id":3862,"url":"../t130p600-topic.html#p18330","post_id":"p18330","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:44","sort_key":"2015-09-24 18:44:00","excerpt":"Объективно тоже. У остальных загоны тараканьи в силу возраста, а Алисочка нитакая."},{"doc_id":3863,"url":"../t130p600-topic.html#p18331","post_id":"p18331","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:45","sort_key":"2015-09-24 18:45:00","excerpt":"Это потому что ты в ламповости ничего не понимаешь. Попробуй представить себе растянутое на годы общение с любой из девушек, и всё сразу встанет на свои места."},{"doc_id":3864,"url":"../t130p600-topic.html#p18332","post_id":"p18332","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:47","sort_key":"2015-09-24 18:47:00","excerpt":"Представил. Ничего плохого с Мику не вижу. Недостаток внимания пройдёт со временем и надоедать не будет. Честно говоря со всеми, кроме Алисы лучше, т.к. она одна по сути с такими загонами."},{"doc_id":3865,"url":"../t130p600-topic.html#p18333","post_id":"p18333","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:50","sort_key":"2015-09-24 18:50:00","excerpt":"Да как раз наоборот, срачи с Алисочкой будут только в первый год. А вот Мику любого заболтает до того, что Семён в окно выйдет. Сам подумай, каково жить под непрекращающийся монолог, на который, к тому же, придётся хотя…"},{"doc_id":3866,"url":"../t130p600-topic.html#p18334","post_id":"p18334","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:51","sort_key":"2015-09-24 18:51:00","excerpt":"Дак она же с ним говорить нормально начала, ты что рут не проходил? Да и говорю, со временем недостаток внимания этот пройдёт"},{"doc_id":3867,"url":"../t130p600-topic.html#p18335","post_id":"p18335","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:51","sort_key":"2015-09-24 18:51:00","excerpt":"Со Славей сложно будет, если не подкаблучник. Проще всего с Мику и Леной. С Ульянкой - не понятно, что будет, когда перерастёт свою дурь. С Алисой, пожалуй, сложнее всего. Её труднее и дольше всех выводить из проблем."},{"doc_id":3868,"url":"../t130p600-topic.html#p18336","post_id":"p18336","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:52","sort_key":"2015-09-24 18:52:00","excerpt":"Согласен. Ну, не проходил тут рут Слави, но в оригинале она вроде как решения ГГ доверяет."},{"doc_id":3869,"url":"../t130p600-topic.html#p18337","post_id":"p18337","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:53","sort_key":"2015-09-24 18:53:00","excerpt":"Это не важно. Она в принципе - лидер."},{"doc_id":3870,"url":"../t130p600-topic.html#p18338","post_id":"p18338","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:54","sort_key":"2015-09-24 18:54:00","excerpt":"И в оригинале? Или только в моде"},{"doc_id":3871,"url":"../t130p600-topic.html#p18339","post_id":"p18339","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 18:55","sort_key":"2015-09-24 18:55:00","excerpt":"Да нифига подобного. Алисочке просто нужен надёжный человек рядом, тот, который бы её любил и которому она могла бы безоговорочно довериться. А вот с остальными длительные отношения невозможны в принципе."},{"doc_id":3872,"url":"../t130p600-topic.html#p18340","post_id":"p18340","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:56","sort_key":"2015-09-24 18:56:00","excerpt":"Понимаешь, чел не может быть лидером, только в рабочее время, так же как нельзя быть ведьмой с 9 до 17. Это не переделывается. Но это не значит, что такой чел не может подчиняться при необходимости. Но в иерархии он…"},{"doc_id":3873,"url":"../t130p625-topic.html#p18341","post_id":"p18341","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 18:58","sort_key":"2015-09-24 18:58:00","excerpt":"Все стараются занять максимально высокое положение, иногда просто нейтральное, разве не так?"},{"doc_id":3874,"url":"../t130p625-topic.html#p18342","post_id":"p18342","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 18:58","sort_key":"2015-09-24 18:58:00","excerpt":"Не-не-не. Её эпатаж и впадание в детство основаны скорее всего на детской травме. Это тяжело убирается."},{"doc_id":3875,"url":"../t130p625-topic.html#p18343","post_id":"p18343","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:01","sort_key":"2015-09-24 19:01:00","excerpt":"Не так. Все хотят занять максимально высокое положение, но далеко не все могут. А вот люди с психотипом Слави - могут."},{"doc_id":3876,"url":"../t130p625-topic.html#p18344","post_id":"p18344","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:01","sort_key":"2015-09-24 19:01:00","excerpt":"Всё её поведение, по сути, является своего рода социальной мимикрией. Я не говорю, что притирание друг к другу произойдёт мгновенно и без ссор, но оно произойдёт. А у остальных тараканы размером с носорога. и куча…"},{"doc_id":3877,"url":"../t130p625-topic.html#p18345","post_id":"p18345","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:02","sort_key":"2015-09-24 19:02:00","excerpt":"Каких комплексов? Что, допустим, вымещать Лене? Про Мику я уже сказал, с Сёмой она нормально стала общаться."},{"doc_id":3878,"url":"../t130p625-topic.html#p18346","post_id":"p18346","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:03","sort_key":"2015-09-24 19:03:00","excerpt":"Вот как раз их тараканы и комплексы убираются достаточно легко. Часто за 2-3 прохода. А последствия детской психотравмы - гораздо сложнее."},{"doc_id":3879,"url":"../t130p625-topic.html#p18347","post_id":"p18347","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:05","sort_key":"2015-09-24 19:05:00","excerpt":"Лене-то как раз много чего вымещать, тащ. Она же неадекват полный. Чем забита голова у шеснадцатилетнего интроверта, упоротого по романтике в представлении авторов женских романов? А дичайшая неуверенность в себе? Она же…"},{"doc_id":3880,"url":"../t130p625-topic.html#p18348","post_id":"p18348","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:06","sort_key":"2015-09-24 19:06:00","excerpt":"А, кстати, можно ли, как считаешь, психотип изменить? И какие черты присущи лидеру"},{"doc_id":3881,"url":"../t130p625-topic.html#p18349","post_id":"p18349","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:06","sort_key":"2015-09-24 19:06:00","excerpt":"Извиняюсь категорически - вы психолог?"},{"doc_id":3882,"url":"../t130p625-topic.html#p18350","post_id":"p18350","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:08","sort_key":"2015-09-24 19:08:00","excerpt":"Не знаю, что у неё там в моде за маниакальный характер, но это скорее подростковое, типа Эмо"},{"doc_id":3883,"url":"../t130p625-topic.html#p18351","post_id":"p18351","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:09","sort_key":"2015-09-24 19:09:00","excerpt":"Не профессиональный, но заниматься этой работой мне приходится систематически. В том числе напару с психиатрами."},{"doc_id":3884,"url":"../t130p625-topic.html#p18352","post_id":"p18352","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:09","sort_key":"2015-09-24 19:09:00","excerpt":"Что, не встречались подобные \"Леночки\" в жизни? Ты везуч, товарисч."},{"doc_id":3885,"url":"../t130p625-topic.html#p18353","post_id":"p18353","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Элдхэнн","posted_at":"Чт 24 Сен 2015 - 19:10","sort_key":"2015-09-24 19:10:00","excerpt":"Ну да, ну да. Нажраться таблеток в ответ на \"дорогая, не так быстро\" - это не маниакальный характер. Ни разу."},{"doc_id":3886,"url":"../t130p625-topic.html#p18354","post_id":"p18354","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:11","sort_key":"2015-09-24 19:11:00","excerpt":"Может быть, мне лично Лена не нравится, я Микуфаг. Скучно с ней."},{"doc_id":3887,"url":"../t130p625-topic.html#p18355","post_id":"p18355","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:12","sort_key":"2015-09-24 19:12:00","excerpt":"Я же предположил, что это, возможно, подростковое. Такого не может быть?"},{"doc_id":3888,"url":"../t130p625-topic.html#p18356","post_id":"p18356","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:13","sort_key":"2015-09-24 19:13:00","excerpt":"Слишком сложно в таком возрасте социальную мимикрию включать. Да, и поведение у неё, пардон, А социальное. Де-факто те же самые тараканы, что и у Лены, но вместо эскапизма включается другой вариант инфантилизма…"},{"doc_id":3889,"url":"../t130p625-topic.html#p18357","post_id":"p18357","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:14","sort_key":"2015-09-24 19:14:00","excerpt":"Ну давай попробуем составит психологический портрет Унылки. В анемнезе романтика в пошлейшем смысле этого слова, дикая застенчивость и, как следствие, неумение строить диалог. Приплюсуем сюда папу, оберегающего от всех…"},{"doc_id":3890,"url":"../t130p625-topic.html#p18358","post_id":"p18358","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:16","sort_key":"2015-09-24 19:16:00","excerpt":"Кстати, по поводу Слави, кто проигрывал ей в финале ? Она будет в отчаяние со временем впадать, если люди рядом с ней целиком на неё сбросят всё и вся. Какой бы она сильной и непробивной не казалась, рядом нужен тот кто…"},{"doc_id":3891,"url":"../t130p625-topic.html#p18359","post_id":"p18359","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:18","sort_key":"2015-09-24 19:18:00","excerpt":"Про Славю отдельный разговор. Ей не нужен равный, ей нужен именно подкаблучник, который послужит инструментом для повышения её статуса."},{"doc_id":3892,"url":"../t130p625-topic.html#p18360","post_id":"p18360","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Элдхэнн","posted_at":"Чт 24 Сен 2015 - 19:19","sort_key":"2015-09-24 19:19:00","excerpt":"Господин Обидчивый, расскажите нам свою саксесс-стори про счастливую жизнь рядом с идеальным человеком."},{"doc_id":3893,"url":"../t130p625-topic.html#p18361","post_id":"p18361","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:20","sort_key":"2015-09-24 19:20:00","excerpt":"Так а если подкаблучник не справляется с возложенной задачей, а тот кто справляется - не такой уж подкаблучник ?"},{"doc_id":3894,"url":"../t130p625-topic.html#p18362","post_id":"p18362","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:20","sort_key":"2015-09-24 19:20:00","excerpt":"Уважаемый, отлезь, пожалуйста. Возможно, ты не заметил, но я тут с людьми беседую. Зачем вмешиваться туда, куда тебя не звали?"},{"doc_id":3895,"url":"../t130p625-topic.html#p18363","post_id":"p18363","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:21","sort_key":"2015-09-24 19:21:00","excerpt":"Видишь ли, Унылка ярко выраженный интроверт, детские комплексы (а у неё именно детские комплексы) у интровертов во многих случаях или сами проходят с возрастом, или достаточно легко снимаются. Добавь сюда поддержку…"},{"doc_id":3896,"url":"../t130p625-topic.html#p18364","post_id":"p18364","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:22","sort_key":"2015-09-24 19:22:00","excerpt":"Не справится - будет просто списан со счетов. Справится - повысят звание до надкаблучника. Ничего другого союз со Слявяной в принципе нести не может."},{"doc_id":3897,"url":"../t130p625-topic.html#p18365","post_id":"p18365","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:23","sort_key":"2015-09-24 19:23:00","excerpt":"На самом деле - не факт. Зависит от конкретной личности. Она как может быть лидером всюду, так может и хотеть не быть им хотя бы в одной сфере своей жизни. Вопрос тонкий - однозначного ответа на него нет."},{"doc_id":3898,"url":"../t130p650-topic.html#p18366","post_id":"p18366","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:23","sort_key":"2015-09-24 19:23:00","excerpt":"А на основании каких черт характера она лидер?"},{"doc_id":3899,"url":"../t130p650-topic.html#p18367","post_id":"p18367","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:24","sort_key":"2015-09-24 19:24:00","excerpt":"Ну как минимум, за умение брать инициативу и ответственность на себя."},{"doc_id":3900,"url":"../t130p650-topic.html#p18368","post_id":"p18368","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:25","sort_key":"2015-09-24 19:25:00","excerpt":"Из опыта могу сказать, что такие Унылки с детскими, легко излечимыми комплексами порой ведут себя несколько неадекватно даже по прошествии полугода в отношениях. Историю эту я уже рассказывал, всем очень понравилось."},{"doc_id":3901,"url":"../t130p650-topic.html#p18369","post_id":"p18369","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Элдхэнн","posted_at":"Чт 24 Сен 2015 - 19:25","sort_key":"2015-09-24 19:25:00","excerpt":"Я рад, что давным-давно данная мной характеристика всё ещё подтверждается."},{"doc_id":3902,"url":"../t130p650-topic.html#p18370","post_id":"p18370","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Чт 24 Сен 2015 - 19:25","sort_key":"2015-09-24 19:25:00","excerpt":"О!!!! Славя срач, вот это я вовремя, да ещё и Чесс курирует, великолепно, осталось Арли дождаться)"},{"doc_id":3903,"url":"../t130p650-topic.html#p18371","post_id":"p18371","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:26","sort_key":"2015-09-24 19:26:00","excerpt":"Да, летающие ножницы это конечно эпично"},{"doc_id":3904,"url":"../t130p650-topic.html#p18372","post_id":"p18372","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Чт 24 Сен 2015 - 19:26","sort_key":"2015-09-24 19:26:00","excerpt":"О, ничего себе, да ещё и товарищ Элдхэнн, на базе чьих работ я много своих по 7ДЛ накатал, тут. Жизнь становится интереснее)"},{"doc_id":3905,"url":"../t130p650-topic.html#p18373","post_id":"p18373","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:26","sort_key":"2015-09-24 19:26:00","excerpt":"Всегда пожалуйста."},{"doc_id":3906,"url":"../t130p650-topic.html#p18374","post_id":"p18374","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:27","sort_key":"2015-09-24 19:27:00","excerpt":"[quote=\"Chess\"] Надо у моей дамы сердца спросить, кто я есть"},{"doc_id":3907,"url":"../t130p650-topic.html#p18375","post_id":"p18375","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:28","sort_key":"2015-09-24 19:28:00","excerpt":"Тут не совсем Славя-срач."},{"doc_id":3908,"url":"../t130p650-topic.html#p18376","post_id":"p18376","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:28","sort_key":"2015-09-24 19:28:00","excerpt":"Ну, для начала, не бывает 100% ситуаций. Да, встречаются и такие, неисправимые. Однако если их хорошенько поковырять, то там тоже вылезает какая-нибудь причина-ситуация, с которой можно работать."},{"doc_id":3909,"url":"../t130p650-topic.html#p18377","post_id":"p18377","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:28","sort_key":"2015-09-24 19:28:00","excerpt":"И кстати, инициативность - не основная черта лидера. Некоторые люди настолько инициативны, что скорее рабы, чем лидеры."},{"doc_id":3910,"url":"../t130p650-topic.html#p18378","post_id":"p18378","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:29","sort_key":"2015-09-24 19:29:00","excerpt":"Увольте, больше ковырять мне не захотелось.Как я увернулся - сам до сих пор понять не могу."},{"doc_id":3911,"url":"../t130p650-topic.html#p18379","post_id":"p18379","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:30","sort_key":"2015-09-24 19:30:00","excerpt":"Воот! Именно об этом я и пытался сказать, благодарю за выраженную мысль."},{"doc_id":3912,"url":"../t130p650-topic.html#p18380","post_id":"p18380","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:30","sort_key":"2015-09-24 19:30:00","excerpt":"Тут беседа о достоинствах и недостатках девушек БЛ, в самой дружелюбной форме"},{"doc_id":3913,"url":"../t130p650-topic.html#p18381","post_id":"p18381","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:30","sort_key":"2015-09-24 19:30:00","excerpt":"Да, мы тут стараемся быть объективными, так что можно сказать, что не срач."},{"doc_id":3914,"url":"../t130p650-topic.html#p18382","post_id":"p18382","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:30","sort_key":"2015-09-24 19:30:00","excerpt":"А кто, кстати, сказал, что Славя - лидер? Славя просто хитра до невозможности и твёрдо намерена выбиться \"в люди\", в её понимании, естественно."},{"doc_id":3915,"url":"../t130p650-topic.html#p18383","post_id":"p18383","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:31","sort_key":"2015-09-24 19:31:00","excerpt":"Да, я про это и спрашиваю, почему она лидер. Но почему тогда ей нужен подкаблучник, если она не лидер?"},{"doc_id":3916,"url":"../t130p650-topic.html#p18384","post_id":"p18384","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:32","sort_key":"2015-09-24 19:32:00","excerpt":"Ну, ты то влип по-жизни, а я с этой фигнёй разбирался неоднократно по-работе, вот и приходится ковырять глубже. Хотя всё-равно встречаются особо упёрнутые экземпляры, которые не желают меняться ни под каким соусом."},{"doc_id":3917,"url":"../t130p650-topic.html#p18385","post_id":"p18385","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:33","sort_key":"2015-09-24 19:33:00","excerpt":"Почему же выбиться в люди плохо, тем более что ничего криминального или аморального она не делает. Да и вытянуть с собой кого-то пытается, попутно. \"Мне хорошо - хорошо, ещё кому-то хорошо - ещё лучше\""},{"doc_id":3918,"url":"../t130p650-topic.html#p18386","post_id":"p18386","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:34","sort_key":"2015-09-24 19:34:00","excerpt":"\"Подкаблучник\", \"инструмент\", \"отмычка\"... Смысл-то от этого не меняется? Семён Славе нужен только в качестве очередной ступеньки, как только он сломается - тут же перестанет Славю интересовать."},{"doc_id":3919,"url":"../t130p650-topic.html#p18387","post_id":"p18387","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:35","sort_key":"2015-09-24 19:35:00","excerpt":"Считаете, на любовь она не способна?"},{"doc_id":3920,"url":"../t130p650-topic.html#p18388","post_id":"p18388","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:36","sort_key":"2015-09-24 19:36:00","excerpt":"Вот положа руку на яйц на сердце - ты бы попытался на моём месте разобраться, что именно было не так, в чём лично ты виноват и как этих тараканов выловить и запереть?"},{"doc_id":3921,"url":"../t130p650-topic.html#p18389","post_id":"p18389","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:37","sort_key":"2015-09-24 19:37:00","excerpt":"Только сказали о том, что у нас не Славя-срач и заверте... =)"},{"doc_id":3922,"url":"../t130p650-topic.html#p18390","post_id":"p18390","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:37","sort_key":"2015-09-24 19:37:00","excerpt":"Славю карьера интересует, а не всякие глупости. Увлечься на пару месяцев она способна, но не больше. Дальше пойдёт холодный расчёт."},{"doc_id":3923,"url":"../t130p675-topic.html#p18391","post_id":"p18391","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:38","sort_key":"2015-09-24 19:38:00","excerpt":"Таки ответочка"},{"doc_id":3924,"url":"../t130p675-topic.html#p18392","post_id":"p18392","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:38","sort_key":"2015-09-24 19:38:00","excerpt":"Так щас и по остальным проедемся, штоп два раза не вставать."},{"doc_id":3925,"url":"../t130p675-topic.html#p18393","post_id":"p18393","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 19:38","sort_key":"2015-09-24 19:38:00","excerpt":"Вот глупысти говоришь же. Славе не нужен подкаблучник, её интересует как раз полноправный партнёр, который в ответ и долбануть может как следует. Между прочим, единственной, кто не стремится встать в колленно-локтевую и…"},{"doc_id":3926,"url":"../t130p675-topic.html#p18394","post_id":"p18394","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:39","sort_key":"2015-09-24 19:39:00","excerpt":"Способна. Но как только конфетно-букетный период скончается, ей станет скучно с челом, который слабее её. С равным - она не уживётся. В одной норе два лидера - это постоянная \"драка\". А вот более сильному он будет…"},{"doc_id":3927,"url":"../t130p675-topic.html#p18395","post_id":"p18395","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:40","sort_key":"2015-09-24 19:40:00","excerpt":"Я сужу о поведении, исходя исключительно из собственного опыта. Славя ведёт себя так, что мне мои выводы сами на язык просятся."},{"doc_id":3928,"url":"../t130p675-topic.html#p18396","post_id":"p18396","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:40","sort_key":"2015-09-24 19:40:00","excerpt":"А какими чертами характера обладает более сильный? Не физической же силой только"},{"doc_id":3929,"url":"../t130p675-topic.html#p18397","post_id":"p18397","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:41","sort_key":"2015-09-24 19:41:00","excerpt":"В первую очередь: ум, воля, способность принимать решения и брать на себя ответственность за них."},{"doc_id":3930,"url":"../t130p675-topic.html#p18398","post_id":"p18398","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 19:42","sort_key":"2015-09-24 19:42:00","excerpt":"Из собственного опыта жизни в одном доме со Славей? (="},{"doc_id":3931,"url":"../t130p675-topic.html#p18399","post_id":"p18399","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:43","sort_key":"2015-09-24 19:43:00","excerpt":"А какими чертами обладает лидер?"},{"doc_id":3932,"url":"../t130p675-topic.html#p18400","post_id":"p18400","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:43","sort_key":"2015-09-24 19:43:00","excerpt":"Нет, конечно. Просто типаж зело знакомый. Встречаться не встречался, но долгое время наблюдал в непосредственной близости."},{"doc_id":3933,"url":"../t130p675-topic.html#p18401","post_id":"p18401","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:44","sort_key":"2015-09-24 19:44:00","excerpt":"А лидер ещё и умеет вести за собой других, ставить задачи и добиваться их выполнения. Ну и то, что иногда называют \"харизмой\"."},{"doc_id":3934,"url":"../t130p675-topic.html#p18402","post_id":"p18402","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 19:49","sort_key":"2015-09-24 19:49:00","excerpt":"Наблюдать иногда недостаточно. Но могу сказать, что такие люди, как правило, стараются на личном фронте делать всё очень гладко и здорово - так что ни подкаблучник, ни домашний тиран их на кухне не устроит. Нужен кто-то…"},{"doc_id":3935,"url":"../t130p675-topic.html#p18403","post_id":"p18403","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:50","sort_key":"2015-09-24 19:50:00","excerpt":"Ага. До тех пор, пока партнёр может быть полезен."},{"doc_id":3936,"url":"../t130p675-topic.html#p18404","post_id":"p18404","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:52","sort_key":"2015-09-24 19:52:00","excerpt":"Хм, интересно. Стоило появиться Автору - и все как рыбы об лёд резко."},{"doc_id":3937,"url":"../t130p675-topic.html#p18405","post_id":"p18405","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 19:53","sort_key":"2015-09-24 19:53:00","excerpt":"Про полезность - это больше к Алисе как раз. Типичная домашная чёкупила. Чуть дашь слабину, пошлёт и выбросит вещи из квартиры."},{"doc_id":3938,"url":"../t130p675-topic.html#p18406","post_id":"p18406","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:54","sort_key":"2015-09-24 19:54:00","excerpt":"Думаю все просто масштабы измерили и решили постоять в стороне пока"},{"doc_id":3939,"url":"../t130p675-topic.html#p18407","post_id":"p18407","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:54","sort_key":"2015-09-24 19:54:00","excerpt":"А тут спорный вопрос. Если исходить из варианта Славя-ведьма, а Сёма - \"высшая су ч щность\", то прекрасно уживутся."},{"doc_id":3940,"url":"../t130p675-topic.html#p18408","post_id":"p18408","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:54","sort_key":"2015-09-24 19:54:00","excerpt":"Хе! Алисочка как раз нитакая. Алисочку приручать нужно, а когда она поймёт, что Семён искренен, превратится в идеал."},{"doc_id":3941,"url":"../t130p675-topic.html#p18409","post_id":"p18409","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:55","sort_key":"2015-09-24 19:55:00","excerpt":"Зачем ждать этого, если идеал уже есть?)"},{"doc_id":3942,"url":"../t130p675-topic.html#p18410","post_id":"p18410","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 19:56","sort_key":"2015-09-24 19:56:00","excerpt":"Правда? Где? Кто?"},{"doc_id":3943,"url":"../t130p675-topic.html#p18411","post_id":"p18411","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:57","sort_key":"2015-09-24 19:57:00","excerpt":"Угу. Но малейшая оплошность с твоей стороны и \"забирай свои игрушки и не писай в мой горшок\"."},{"doc_id":3944,"url":"../t130p675-topic.html#p18412","post_id":"p18412","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:57","sort_key":"2015-09-24 19:57:00","excerpt":"А может и включить обидку, и назло \"отморожу уши\" (без вскрываний, разумеется), и напакостить специально в процессе приручения, если что-то пойдёт не так."},{"doc_id":3945,"url":"../t130p675-topic.html#p18413","post_id":"p18413","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 19:58","sort_key":"2015-09-24 19:58:00","excerpt":"Беседа уже не такая дружественная становится, в бой идут личные симпатии)"},{"doc_id":3946,"url":"../t130p675-topic.html#p18414","post_id":"p18414","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 19:58","sort_key":"2015-09-24 19:58:00","excerpt":"Дак мы тут изначально о девушках завели спор, как без симпатий."},{"doc_id":3947,"url":"../t130p675-topic.html#p18415","post_id":"p18415","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 19:58","sort_key":"2015-09-24 19:58:00","excerpt":"И как только Семён даст слабину, идеал выбросит его вещи из квартиры. Ведь ей так трудно, а этот тряпканемужик даже не может её утешить и поддержать. А. Ещё. Она чайлдфри. Убеждённая."},{"doc_id":3948,"url":"../t130p700-topic.html#p18416","post_id":"p18416","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 19:59","sort_key":"2015-09-24 19:59:00","excerpt":"Ну Чесс сам переступил первый ту самую мирную грань."},{"doc_id":3949,"url":"../t130p700-topic.html#p18417","post_id":"p18417","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 19:59","sort_key":"2015-09-24 19:59:00","excerpt":"Чесс, стол оставь в покое..."},{"doc_id":3950,"url":"../t130p700-topic.html#p18418","post_id":"p18418","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:00","sort_key":"2015-09-24 20:00:00","excerpt":"Да нифига подобного. Просто нужно быть принципиальным."},{"doc_id":3951,"url":"../t130p700-topic.html#p18419","post_id":"p18419","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:01","sort_key":"2015-09-24 20:01:00","excerpt":"Голодовка и избиения Принципы и твёрдость в принятии решений. Ну и, разумеется. нужно решения логично и доступно обосновывать."},{"doc_id":3952,"url":"../t130p700-topic.html#p18420","post_id":"p18420","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:01","sort_key":"2015-09-24 20:01:00","excerpt":"Чессу тяжело наверное одному против всех"},{"doc_id":3953,"url":"../t130p700-topic.html#p18421","post_id":"p18421","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 20:02","sort_key":"2015-09-24 20:02:00","excerpt":"А давайте представим гибрид Алисы и Слави ? Жизнеспособный вариант ?"},{"doc_id":3954,"url":"../t130p700-topic.html#p18422","post_id":"p18422","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:03","sort_key":"2015-09-24 20:03:00","excerpt":"Твёрдость, принципиальность унд логика. А про чайлдфри - это маска. Она отвалится, как только Алисочка Семёну по-настоящему доверится."},{"doc_id":3955,"url":"../t130p700-topic.html#p18423","post_id":"p18423","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:04","sort_key":"2015-09-24 20:04:00","excerpt":"А для меня гибрид Слави и Мику"},{"doc_id":3956,"url":"../t130p700-topic.html#p18425","post_id":"p18425","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:05","sort_key":"2015-09-24 20:05:00","excerpt":"Ну как всегда, виноватым Чесса назначили... Всего-то неосторожно высказал своё мнение, так за него съесть готовы безобидного меня."},{"doc_id":3957,"url":"../t130p700-topic.html#p18426","post_id":"p18426","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 20:05","sort_key":"2015-09-24 20:05:00","excerpt":"Долгий и тернистый сие путь, тов. Чесс. У Сёмы не факт, что хватит этого терпения."},{"doc_id":3958,"url":"../t130p700-topic.html#p18427","post_id":"p18427","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:06","sort_key":"2015-09-24 20:06:00","excerpt":"Максимум год отношений."},{"doc_id":3959,"url":"../t130p700-topic.html#p18428","post_id":"p18428","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:06","sort_key":"2015-09-24 20:06:00","excerpt":"С Мику намного проще. Не устаю повторять."},{"doc_id":3960,"url":"../t130p700-topic.html#p18429","post_id":"p18429","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 20:07","sort_key":"2015-09-24 20:07:00","excerpt":"Если откинуть \"детскость\" и ещё одного таракана Алисы, то получится Славя-ведьма."},{"doc_id":3961,"url":"../t130p700-topic.html#p18430","post_id":"p18430","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 20:07","sort_key":"2015-09-24 20:07:00","excerpt":"А потом Сёма распивает бутыль водки и радуется их окончанию"},{"doc_id":3962,"url":"../t130p700-topic.html#p18431","post_id":"p18431","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 20:08","sort_key":"2015-09-24 20:08:00","excerpt":"А вот когда Семён упоминается в диалоге, мы о среднестатистическом Семёне говорите, пусть даже и роль учитывается, или то как поступили бы сами ? Я мод убеждённо читаю в роли Локи, и не сказал бы что он получился у меня…"},{"doc_id":3963,"url":"../t130p700-topic.html#p18432","post_id":"p18432","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 20:08","sort_key":"2015-09-24 20:08:00","excerpt":"С последним оратором соглашусь. На год облизывания Алисы терпения хватит лишь у самого упоротого фаната безнадёжно влюблённого поклонника. Ты год приручаешь человека, чтобы в результате получить гадюку, только и ждущую…"},{"doc_id":3964,"url":"../t130p700-topic.html#p18433","post_id":"p18433","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 24 Сен 2015 - 20:09","sort_key":"2015-09-24 20:09:00","excerpt":"И главное, ничто не предвещало..."},{"doc_id":3965,"url":"../t130p700-topic.html#p18434","post_id":"p18434","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:10","sort_key":"2015-09-24 20:10:00","excerpt":"Это что арт из будущего кошко-рута?"},{"doc_id":3966,"url":"../t130p700-topic.html#p18435","post_id":"p18435","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 20:10","sort_key":"2015-09-24 20:10:00","excerpt":"То у Ульянки лимонад или бальзам лечебный ?"},{"doc_id":3967,"url":"../t130p700-topic.html#p18436","post_id":"p18436","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:11","sort_key":"2015-09-24 20:11:00","excerpt":"Намного проще сойтись, и намного тяжелее заставить её считаться с собой."},{"doc_id":3968,"url":"../t130p700-topic.html#p18437","post_id":"p18437","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:11","sort_key":"2015-09-24 20:11:00","excerpt":"Это слабый, негодный Семён."},{"doc_id":3969,"url":"../t130p700-topic.html#p18438","post_id":"p18438","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 20:13","sort_key":"2015-09-24 20:13:00","excerpt":"Портвейн из города=)"},{"doc_id":3970,"url":"../t130p700-topic.html#p18439","post_id":"p18439","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Штейн","posted_at":"Чт 24 Сен 2015 - 20:13","sort_key":"2015-09-24 20:13:00","excerpt":"Да блин, эх, старые добрые баталии в треде, о времена..."},{"doc_id":3971,"url":"../t130p700-topic.html#p18440","post_id":"p18440","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:14","sort_key":"2015-09-24 20:14:00","excerpt":"Пф-ф-ф, всё бы вам побыстрее подавай. Лена сама налезает? Это нормально. Мику из трусиков выпрыгивает? Ваще зашибись! А я пытаюсь прогнозировать дальнейшие отношения с девушками, и Алисочка таки лидирует с огромным…"},{"doc_id":3972,"url":"../t130p700-topic.html#p18441","post_id":"p18441","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 20:14","sort_key":"2015-09-24 20:14:00","excerpt":"И платье, и продукты для вечера - таки Ульяна уже взрослая"},{"doc_id":3973,"url":"../t130p725-topic.html#p18442","post_id":"p18442","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:14","sort_key":"2015-09-24 20:14:00","excerpt":"Что значит \"Ничто не предвещало\"?! Я же тут есть!"},{"doc_id":3974,"url":"../t130p725-topic.html#p18443","post_id":"p18443","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:15","sort_key":"2015-09-24 20:15:00","excerpt":"Полегче, она что-то искала под роялем просто!"},{"doc_id":3975,"url":"../t130p725-topic.html#p18444","post_id":"p18444","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"BlackDoomer","posted_at":"Чт 24 Сен 2015 - 20:16","sort_key":"2015-09-24 20:16:00","excerpt":"А Алисочка сама не знает, чего хочет, но под портвешком согласная..."},{"doc_id":3976,"url":"../t130p725-topic.html#p18445","post_id":"p18445","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:16","sort_key":"2015-09-24 20:16:00","excerpt":"Угу, угу. А \"Я поняла, Сёмочка\" как вписать?"},{"doc_id":3977,"url":"../t130p725-topic.html#p18446","post_id":"p18446","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:17","sort_key":"2015-09-24 20:17:00","excerpt":"И как это препятствует долгим и счастливым отношениям?"},{"doc_id":3978,"url":"../t130p725-topic.html#p18447","post_id":"p18447","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:18","sort_key":"2015-09-24 20:18:00","excerpt":"А потому что портвешок снимает эмоциональные блоки, а секс в данном случае является суррогатом ощущения, что она кому-то нужна."},{"doc_id":3979,"url":"../t130p725-topic.html#p18448","post_id":"p18448","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:19","sort_key":"2015-09-24 20:19:00","excerpt":"Как препятствует долгим и счастливым отношениям доступность болтливой самочки? Ну я даже не знаю..."},{"doc_id":3980,"url":"../t130p725-topic.html#p18449","post_id":"p18449","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:19","sort_key":"2015-09-24 20:19:00","excerpt":"Даже если она и специально, то по крайней мере смотреть она не заставляла. А Алиса то как раз убедительно просила выпить с ней."},{"doc_id":3981,"url":"../t130p725-topic.html#p18450","post_id":"p18450","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 20:20","sort_key":"2015-09-24 20:20:00","excerpt":"Отношения, которые быстрее выходят на плейн - быстрее подстраивают людей друг к другу. Да, Лена и Мику по своей инициативе легко сократят дистанцию и пустят в самые далёкие уголки своей души. Если не быть клиническим…"},{"doc_id":3982,"url":"../t130p725-topic.html#p18451","post_id":"p18451","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:20","sort_key":"2015-09-24 20:20:00","excerpt":"И где гарантия, что эта доступность не только для Семёна? Он всё таки её первый"},{"doc_id":3983,"url":"../t130p725-topic.html#p18452","post_id":"p18452","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:21","sort_key":"2015-09-24 20:21:00","excerpt":"Именно! Это говорит нам о том, что Алисочке нужна опора, даже суррогат в виде приблудного Семёна подойдёт."},{"doc_id":3984,"url":"../t130p725-topic.html#p18453","post_id":"p18453","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 20:22","sort_key":"2015-09-24 20:22:00","excerpt":"Побыстрее? Вообще-то, в постель они все падают примерно в одно и то же время. Так что в этом плане ни у одной нет преимуществ. Ну и да, за неделю сделать прогноз на год совместной жизни это ненаучная фантастика…"},{"doc_id":3985,"url":"../t130p725-topic.html#p18454","post_id":"p18454","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:22","sort_key":"2015-09-24 20:22:00","excerpt":"Угу, особенно Лена. И хрен вылезешь потом."},{"doc_id":3986,"url":"../t130p725-topic.html#p18455","post_id":"p18455","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Чт 24 Сен 2015 - 20:23","sort_key":"2015-09-24 20:23:00","excerpt":"Так и есть. А надо ли?"},{"doc_id":3987,"url":"../t130p725-topic.html#p18456","post_id":"p18456","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:24","sort_key":"2015-09-24 20:24:00","excerpt":"И да, хорош уже про болтливую, ей просто не хватало внимания. На третий день она уже нормально разговаривает."},{"doc_id":3988,"url":"../t130p725-topic.html#p18457","post_id":"p18457","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 20:24","sort_key":"2015-09-24 20:24:00","excerpt":"А надо ли вылезать? Вот твоя гавань, успокаивайся и начинай строить жизнь. Незачем корчить из себя Агасфера до седых волос на заднице, тем более, что нашему Сёмчику не 18 уже десят лет как."},{"doc_id":3989,"url":"../t130p725-topic.html#p18458","post_id":"p18458","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:24","sort_key":"2015-09-24 20:24:00","excerpt":"Ой, товаrисч Автоr, ну давайте не будем уже с вами дискутиrовать за Алисочку? Ви-таки знаете, в чём пrичина моей упёrтости в данном напrавлении сrача."},{"doc_id":3990,"url":"../t130p725-topic.html#p18459","post_id":"p18459","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:25","sort_key":"2015-09-24 20:25:00","excerpt":"Ну, мазохист был бы счастлив, наверное."},{"doc_id":3991,"url":"../t130p725-topic.html#p18460","post_id":"p18460","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 20:25","sort_key":"2015-09-24 20:25:00","excerpt":"А я не за Алисочку, а за её \"преимущества\" перед другими девушками лагеря."},{"doc_id":3992,"url":"../t130p725-topic.html#p18461","post_id":"p18461","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:27","sort_key":"2015-09-24 20:27:00","excerpt":"Алисочка наиболее адаптивна и приспособлена к жизни. Это моё мнение, и даже вы меня не переубедите."},{"doc_id":3993,"url":"../t130p725-topic.html#p18462","post_id":"p18462","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Draug","posted_at":"Чт 24 Сен 2015 - 20:27","sort_key":"2015-09-24 20:27:00","excerpt":"Давайте нейтральную тему, поговорим про Ульянку"},{"doc_id":3994,"url":"../t130p725-topic.html#p18463","post_id":"p18463","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Chess","posted_at":"Чт 24 Сен 2015 - 20:28","sort_key":"2015-09-24 20:28:00","excerpt":"Найн! НА-А-АЙН! Щас Перегаррет заявится!"},{"doc_id":3995,"url":"../t130p725-topic.html#p18464","post_id":"p18464","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"7dl-kun","posted_at":"Чт 24 Сен 2015 - 20:29","sort_key":"2015-09-24 20:29:00","excerpt":"Алисочка убежала от родичей на улицу за свинчаткой в заднем кармане, греться на трубах теплоэлектроцентрали и причащаться продукцией \"Хенкель\". Это не приспособленность, это долбанутый юношеский максимализм. Насчёт…"},{"doc_id":3996,"url":"../t130p725-topic.html#p18465","post_id":"p18465","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Коллекционер","posted_at":"Чт 24 Сен 2015 - 20:29","sort_key":"2015-09-24 20:29:00","excerpt":"А он АлисоФаг?"},{"doc_id":3997,"url":"../t130p725-topic.html#p18466","post_id":"p18466","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"peregarrett","posted_at":"Чт 24 Сен 2015 - 20:30","sort_key":"2015-09-24 20:30:00","excerpt":"А давайте! У Ульяны, по сравнению с остальными затараканенными девушками, одно большое преимущество. Она вырастет и перебесится!"},{"doc_id":3998,"url":"../t130p75-topic.html#p17363","post_id":"p17363","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Arlien","posted_at":"Вт 8 Сен 2015 - 16:28","sort_key":"2015-09-08 16:28:00","excerpt":"Послушаем-с!"},{"doc_id":3999,"url":"../t130p75-topic.html#p17364","post_id":"p17364","topic_title":"Бар \"7 летних ночей\"","forum_title":"Флудильня","author":"Dantiras","posted_at":"Вт 8 Сен 2015 - 16:37","sort_key":"2015-09-08 16:37:00","excerpt":"Сам закрылся. Решил жить реальной жизнью и удалил канал."}];
